class FlowAgentFailedError(RuntimeError):
    """Flow's Agent panel showed "The agent failed. Please try again." and produced no images."""


class FlowAgentQuotaError(RuntimeError):
    """Raised when the current Google Flow Agent browser profile hits its quota."""


class FlowProjectNotFoundError(RuntimeError):
    """Raised before a Flow 404 page can be mistaken for the project editor."""


class RemoveLogoNoWatermarkError(RuntimeError):
    """Raised when removelogo finds no Gemini watermark to remove.

    Not a failure: the image is already clean, so the run keeps the original
    bytes instead of reporting that something went wrong.
    """


class FlowUiUpscaleUnavailableError(RuntimeError):
    """Flow's editor stopped handing out "2K Upscaled" downloads (per-account daily limit, 2026-09-09).

    The card is held untouched instead of being filled with 1K images; the generated images stay in the
    account's Flow project so their 2K versions can be fetched later without regenerating.
    """


def _model_dump(model: Any) -> Dict[str, Any]:
    if hasattr(model, "model_dump"):
        return model.model_dump(mode="json")
    return model.dict()


def _full_chromium_headless_launcher(original: Any) -> Any:
    """Chạy ẩn thì phải mở bản Chromium đầy đủ, không phải ``headless shell``.

    Đặt ``headless=True``, Playwright lặng lẽ đổi sang ``chrome-headless-shell``
    - một bản rút gọn. Nó vẫn mở đúng hồ sơ và vẫn giải mã được cookie Google,
    nhưng labs.google không cấp phiên next-auth cho nó: ``/fx/api/auth/session``
    trả về ``{}``, thế là không có Bearer token và mọi lệnh gọi Flow rơi xuống
    401 "API keys are not supported by this API" - đọc lên cứ như phiên đăng
    nhập đã hết hạn, trong khi bật cửa sổ lên là chạy ngon lành. Bản Chromium
    đầy đủ chạy chế độ ``--headless=new`` thì phiên đăng nhập còn nguyên.

    Máy nào chưa tải bản đầy đủ thì quay về lối cũ, thà chạy được còn hơn chết.
    """

    async def launch_persistent_context(self: Any, user_data_dir: Any, **kwargs: Any) -> Any:
        if not kwargs.get("headless") or kwargs.get("channel") or kwargs.get("executable_path"):
            return await original(self, user_data_dir, **kwargs)
        try:
            return await original(self, user_data_dir, channel="chromium", **kwargs)
        except Exception as exc:
            log.warning(
                "Không mở được bản Chromium đầy đủ để chạy ẩn (%s); "
                "quay về headless shell - Google Flow có thể báo hết phiên đăng nhập.",
                exc,
            )
        return await original(self, user_data_dir, **kwargs)

    launch_persistent_context.__flow_v2_full_chromium__ = True  # type: ignore[attr-defined]
    return launch_persistent_context


def _parse_iso_datetime(value: str) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


#: Sàn cho lần hỏi project poll thứ hai.  Lần ấy chỉ còn một câu để hỏi —
#: "ảnh đã hiện sẵn trong grid chưa" (``allow_visible_fallback=True``) — nên
#: nó cần đủ giờ để hỏi, không cần đủ giờ để chờ.
PROJECT_POLL_SECOND_CHANCE_FLOOR_S = 10.0


def remaining_project_poll_budget(
    budget_s: float,
    already_waited_s: float,
    floor_s: float = PROJECT_POLL_SECOND_CHANCE_FLOOR_S,
) -> float:
    """Phần ngân sách project poll còn lại sau cuộc đua A1.3.

    Cuộc đua và nhánh timeout **cùng** tiêu một ngân sách. Trước đây mỗi chỗ
    tự viết ``min(120, max(20, ui_timeout_s/2))``, nên một lượt không có ảnh
    nào trả ngân sách ấy hai lần — tới ~240s, trong khi bản cũ (chờ 45s rồi
    mới poll) chỉ mất ~165s. Tức là A1 tiết kiệm 30s cho lượt có ảnh và làm
    lượt hỏng đắt thêm 75s; không ai đo ra vì không có bài test nào nhìn vào
    tổng thời gian.

    Hàm này là chỗ trừ. Sàn ``floor_s`` giữ cho câu hỏi cuối cùng luôn được
    hỏi kể cả khi cuộc đua đã tiêu sạch giờ.
    """
    return max(float(floor_s), float(budget_s) - max(0.0, float(already_waited_s)))


async def race_interceptor_and_project_poll(
    interceptor_task: "asyncio.Future[Any]",
    project_task: "asyncio.Future[Any]",
    *,
    on_poll_error: Optional[Callable[[BaseException], Awaitable[None]]] = None,
) -> Tuple[Any, List[Any]]:
    """Đua interceptor với project poll; bên nào về trước thì bên ấy thắng.

    Trả về ``(result, raced_images)``: ``result`` là thứ interceptor bắt được,
    ``raced_images`` là ảnh project poll tìm thấy. Đúng một trong hai có giá
    trị; cả hai đường cùng hỏng thì ném lỗi của **interceptor**, vì đó là câu
    nói được vì sao lượt này không có ảnh.

    Ba chỗ dễ sai, và cả ba đều là lý do hàm này được tách ra khỏi
    ``_generate_single_reference_image_via_ui`` để có bài test đo được:

    - interceptor hết giờ **không** kết thúc cuộc đua — project poll vẫn còn
      cơ hội thắng;
    - poll về trước mà không có ảnh nào cũng không kết thúc cuộc đua;
    - đường poll nổ thì phải nói ra qua ``on_poll_error``. Trước đây nhánh ấy
      ``continue`` trơn, nên một bug trong project poll trông y hệt một lần
      hết giờ bình thường: log lượt chạy chỉ ghi "timeout/recaptcha" và câu
      lỗi thật không xuất hiện ở đâu cả.

    Trước khi tách, cuộc đua chỉ có hai bài ``assertIn`` đọc chữ trong source
    — xanh kể cả khi nối dây sai, task bị rò, hay cả hai đường cùng hỏng.
    """
    result: Any = None
    got_result = False
    raced_images: List[Any] = []
    pending = {interceptor_task, project_task}
    interceptor_error: Optional[BaseException] = None
    try:
        while pending and not got_result and not raced_images:
            done, pending = await asyncio.wait(
                pending, return_when=asyncio.FIRST_COMPLETED
            )
            for task in done:
                try:
                    outcome = task.result()
                except asyncio.CancelledError:
                    raise
                except Exception as task_exc:
                    if task is interceptor_task:
                        interceptor_error = task_exc
                    elif on_poll_error is not None:
                        await on_poll_error(task_exc)
                    continue
                if task is interceptor_task:
                    result = outcome
                    got_result = True
                elif outcome:
                    raced_images = list(outcome)
        if not got_result and not raced_images:
            if interceptor_error is not None:
                raise interceptor_error
            raise RuntimeError(
                "Google Flow chua tra ve anh tu man hinh Flow trong thoi gian cho."
            )
    finally:
        for task in (interceptor_task, project_task):
            if not task.done():
                task.cancel()
        # Dọn cho sạch: một task bị huỷ mà không ai đọc kết quả sẽ để lại
        # "Task exception was never retrieved" ở lượt sau.
        await asyncio.gather(interceptor_task, project_task, return_exceptions=True)
    return result, raced_images


