    def _flow_agent_multi_image_prompt(self, prompt: str, total: int, *, shot_offset: int = 0, full_total: int | None = None) -> str:
        total = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(total or 1)))
        full_total = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(full_total or total)))
        shot_offset = max(0, min(full_total - 1, int(shot_offset or 0)))
        shot_start = shot_offset + 1
        shot_end = min(full_total, shot_offset + total)
        all_shot_specs = self._flow_agent_shot_specs()
        shot_specs = all_shot_specs[shot_offset : shot_offset + total]
        if len(shot_specs) < total and all_shot_specs:
            shot_specs = [*shot_specs, *all_shot_specs[: total - len(shot_specs)]]
        shot_lines = " ".join(
            f"{shot_offset + index}. {shot['label']}: {shot['brief']} Negative direction: {shot['must_not']}"
            for index, shot in enumerate(shot_specs, start=1)
        )
        base = str(prompt or "").strip()
        occasion_decor_rule = self._flow_agent_occasion_decor_rule(base)
        has_base_shot_plan = "Required shot plan:" in base
        detail_collage_match = (
            re.search(r"(?:image|shot)\s*(\d+)[^.]{0,260}(?:four-panel|four close-up|4 close-up|collage)", base, re.IGNORECASE)
            or re.search(r"(?:four-panel|four close-up|4 close-up)[^.]{0,260}(?:image|shot)\s*(\d+)", base, re.IGNORECASE)
        )
        detail_collage_number = str(detail_collage_match.group(1)) if detail_collage_match else ""
        allows_four_panel_detail_collage = bool(detail_collage_match)
        allows_planned_prop_text = "Planned prop text exception:" in base
        added_readable_text_rule = (
            "The only added readable text allowed is the exact short greeting explicitly required by the Required shot plan, "
            "and it may appear only on that separate secondary greeting-card prop; never place it on the product or as an overlay. "
            if allows_planned_prop_text
            else "Do not add any readable name, initials, year, EST date, quote, slogan, label, or decorative text unless that readable text is visibly embroidered/printed on the source product image; for allowed name variants, keep the same product shape and motif exactly. "
        )
        detail_collage_label = f"image {detail_collage_number}" if detail_collage_number else "the explicitly planned close-up detail image"
        separate_output_rule = (
            f"Each requested output must be its own separate 1:1 square image file. The explicitly planned {detail_collage_label} may be one 1:1 four-panel close-up collage; every other output must not be panels inside one canvas. "
            if allows_four_panel_detail_collage
            else "Each output must be its own separate 1:1 square image file, not landscape, not portrait, not panels inside one canvas. "
        )
        square_frame_rule = (
            f"Every output must fit a square 1:1 frame; {detail_collage_label} may contain four close-up panels inside that square, and no output may look like a UI/gallery screenshot or wide cinematic crop. "
            if allows_four_panel_detail_collage
            else "The product must sit inside a square 1:1 frame with no side-by-side contact sheet, no wide cinematic crop, and no UI/gallery screenshot look. "
        )
        no_grid_rule = (
            f"Do NOT create a {total}-frame grid, contact sheet, storyboard, or multiple images inside one canvas; the only exception is the Required shot plan's {detail_collage_label}, which may be one four-panel embroidery close-up collage inside a single 1:1 image. "
            if allows_four_panel_detail_collage
            else f"Do NOT create a {total}-frame grid, contact sheet, collage, storyboard, multi-panel layout, or multiple images inside one canvas. "
        )
        requested_shot_range = self._required_shot_plan_range_text(base, shot_start, shot_end) if has_base_shot_plan else ""
        if has_base_shot_plan and (full_total > total or shot_offset):
            earlier_range = f"1-{shot_offset}" if shot_offset > 1 else "1" if shot_offset == 1 else ""
            restart_guard = (
                f" Do not create, summarize, repeat, or restart Required shot plan items {earlier_range}; those items were already assigned to an earlier Flow pass."
                if earlier_range
                else ""
            )
            shot_plan_text = (
                f"CURRENT UI PASS SHOT RANGE: create ONLY Required shot plan items {shot_start}-{shot_end}. "
                f"{restart_guard} "
                f"Use these exact Required shot items for this pass: {requested_shot_range or f'items {shot_start}-{shot_end} from the base brief'}. "
                f"Number and think of these outputs as continuation images {shot_start}-{shot_end}, not as a new set starting at image 1. "
            )
        elif has_base_shot_plan:
            shot_plan_text = "Follow the Required shot plan already written in the base brief exactly; do not replace it with generic shot ideas. "
        else:
            shot_plan_text = (
                f"CURRENT UI PASS SHOT RANGE: create ONLY images {shot_start}-{shot_end}. "
                f"CURRENT SHOT PLAN: {shot_lines} "
                if full_total > total or shot_offset
                else f"CURRENT SHOT PLAN: {shot_lines} "
            )
        if full_total > total or shot_offset:
            run_scope = (
                f"This is images {shot_start}-{shot_end} of a {full_total}-image product set. "
                f"Override any earlier full-set count in the base brief for this UI pass: create exactly {total} outputs now, not {full_total}. "
                "The app will handle the other images in separate Flow passes. "
                f"Fresh-task isolation is only to clear old Flow chat context; it does not reset the numbered shot range, so this pass must continue at image {shot_start}."
            )
        else:
            run_scope = "This run must produce the full image set."
        correction = (
            f"Create exactly {total} separate standalone images now in ONE Flow Agent run. This is the first instruction and it overrides any later broad/full-set wording. "
            f"Use the x{total} image setting when available, and if the UI setting is lower, Flow Agent must still plan and create exactly {total} outputs from this message. "
            f"{run_scope} "
            f"{self._flow_agent_fresh_context_rule()} "
            "These generated outputs are in addition to the attached ERP source/reference image; never count the source image as one of the generated outputs. "
            f"{separate_output_rule}"
            f"{square_frame_rule}"
            f"{shot_plan_text}"
            f"{occasion_decor_rule} "
            "HARD REFERENCE LOCK: use only the single attached ERP source image as the product reference; ignore other Flow project thumbnails, previous outputs, examples, or gallery images. "
            "The source image beats the filename/card title: do not infer apparel from 'tao_hinh...', do not infer a plush from an animal motif, and do not infer a pillow/banner/hoop unless that is the visible product object in the source image. "
            "Before every output, compare against the source image and preserve the exact product category, silhouette, outline shape, construction, scale, fabric/material, base color, design placement, motif, embroidery/print layout, and edge details. "
            "Do not reinterpret, upgrade, or transform the source into another product type: a pillow stays the same pillow shape, a pennant/banner stays the same pennant/banner shape, a pillowcase stays a pillowcase, a hoop stays a hoop, a dress stays a dress, and an apron stays an apron. "
            "Do not create derivative merchandise using the source embroidery, such as putting a pillow embroidery onto baby shirts, blankets, banners, hoops, totes, framed prints, or fabric swatches. "
            "If a planned scene would require changing the product shape or design, keep the product unchanged and only change the surrounding styling, props, camera angle, or background. "
            "All images must be visibly different from each other in camera angle, crop distance, background, props, and product presentation. "
            "If two ideas look like the same product-on-table view, change one before generating. "
            "Lighting for every output must be clean clear white neutral daylight with accurate whites; no yellow, orange, golden-hour, tungsten, sepia, beige, or warm color cast. "
            "Every stitched or embroidered area in every output must look like real hand embroidery: raised thread, visible stitch direction, tactile fibers, crisp embroidered edges, and natural thread shadows; never make embroidery look flat printed, painted, digital, vinyl, or sticker-like. "
            f"{self._flow_agent_embroidery_clarity_rule()} "
            "Product-specific exception: if the source is an embroidery hoop, khung theu, or embroidery frame, replace fabric colorway shots with personalized embroidered name variants only when the source image visibly contains an embroidered/personalized name; otherwise keep multiple hoop variants nameless while preserving the hoop/fabric/motif style. "
            f"Product-specific lock: if the source is a pennant/banner/flag wall hanging, every colorway or scene must keep the product as a flat hanging pennant/banner with top dowel/rod, cord hanger, side seams, pointed V bottom, and the same embroidery layout; for any wall-hanging banner output, {self.BANNER_VISIBLE_WALL_HOOK_RULE} Never copy the source motif/name onto a pillow, cushion, blanket, shirt, tote, hoop, or other product. For the explicitly planned process shot only, a round embroidery hoop may appear as a temporary tool holding the pennant fabric while stitching, not as a finished hoop product. "
            "For non-hoop fabric colorways, preserve the same exact product form and embroidery layout; only if the Required shot plan, ERP description, or colorway/multi-color shot requires variants and the source image visibly contains an embroidered or personalized name may each product option use a different plausible name while preserving the same lettering and stitch style; if the source has no name, do not invent names. "
            f"{self._flow_agent_colorway_text_variant_rule()} "
            f"{no_grid_rule}"
            f"{self._flow_agent_no_tag_label_rule()} "
            f"{added_readable_text_rule}"
            "Use the attached ERP source product image as the reference for every output. "
            "Keep every output 1:1 square, commercial product photography, and visually identical to the same source product identity."
        )
        return f"{correction}\n\n{base}" if base else correction

    def _required_shot_plan_range_text(self, base: str, start: int, end: int) -> str:
        text = str(base or "")
        if not text or "Required shot plan:" not in text:
            return ""
        start = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(start or 1)))
        end = max(start, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(end or start)))
        section = text[text.find("Required shot plan:") :]
        matches = list(re.finditer(r"(?<!\d)(\d{1,2})\.\s+", section))
        if not matches:
            return ""
        stop_markers = (
            "Lighting and color rule",
            "Product-specific notes",
            "Treat the ERP description",
            "Use the learned product-prompt style",
            "Preserve the original product shape",
            "Only change scene",
            "Do not change the source product",
            "All outputs must be true",
            "Do not use Google Sheet prompts",
            "Source card:",
        )
        items: List[str] = []
        for index, match in enumerate(matches):
            number = int(match.group(1))
            if number < start or number > end:
                continue
            next_start = matches[index + 1].start() if index + 1 < len(matches) else len(section)
            item = section[match.start() : next_start]
            for marker in stop_markers:
                marker_pos = item.find(marker)
                if marker_pos >= 0:
                    item = item[:marker_pos]
            item = re.sub(r"\s+", " ", item).strip(" ;")
            if item:
                items.append(item)
        return " ".join(items)

    async def _generate_single_reference_image_via_ui(
        self,
        client: Any,
        prompt: str,
        *,
        model: str,
        reference_media_name: str,
        reference_image_path: str = "",
        aspect: str = "square",
        workflow_id: str = "",
        count: int = 1,
        timeout_s: int = 120,
        flow_agent_enabled: bool = True,
        flow_agent_auto_approve: bool = True,
        job_id: str = "",
        require_project_media_baseline: bool = False,
    ) -> List[Any]:
        from flow._models import AspectRatio
        from flow._ui_interceptor import UIInterceptor

        safe_reference_image_path = str(reference_image_path or "").strip()
        # A prompt-only job has no source image at all, so every source-image
        # guard below has to stand down instead of refusing to submit.
        text_only_agent = bool(
            flow_agent_enabled and not str(reference_media_name or "").strip() and not safe_reference_image_path
        )
        resolved_workflow_id = str(workflow_id or "").strip()
        if not resolved_workflow_id and not text_only_agent:
            resolved_workflow_id = await self._find_workflow_id_for_media(client, reference_media_name)
        if not resolved_workflow_id and not (flow_agent_enabled and (safe_reference_image_path or text_only_agent)):
            raise RuntimeError("Google Flow chua tim thay workflow cua anh goc de mo man hinh chinh anh.")

        ui_timeout_s = max(60.0, min(600.0, float(timeout_s or 300)))
        target_count = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(count or 1)))
        aspect_value = self._parse_aspect(aspect or "square")
        ratio = (
            AspectRatio.PORTRAIT
            if aspect_value == "portrait"
            else AspectRatio.SQUARE
            if aspect_value == "square"
            else AspectRatio.LANDSCAPE
        )
        project_url = self._project_url(client.project_id)
        if flow_agent_enabled:
            page, page_detail = await self._acquire_isolated_flow_agent_page(client, project_url)
            self._install_flow_page_file_chooser_guard(page)
            if job_id:
                await self.store.append_log(job_id, f"Fallback UI Flow: dung tab Flow Agent moi ({page_detail[:120]}).")
        else:
            page = await client._bm.page()
        edit_url = f"{project_url}/edit/{quote(resolved_workflow_id, safe='')}" if resolved_workflow_id else project_url
        target_url = project_url if flow_agent_enabled else edit_url
        if job_id:
            await self.store.append_log(
                job_id,
                (
                    f"Fallback UI Flow: mở project để dùng Tác nhân Flow với ảnh nguồn {resolved_workflow_id}."
                    if flow_agent_enabled
                    else f"Fallback UI Flow: mở project và chọn ảnh nguồn {resolved_workflow_id}."
                ),
            )
        try:
            await page.goto(target_url, wait_until="domcontentloaded", timeout=60_000)
        except Exception:
            try:
                await page.goto(target_url, wait_until="commit", timeout=60_000)
            except Exception:
                await page.goto(project_url, wait_until="domcontentloaded", timeout=60_000)
        await asyncio.sleep(2.5)
        app_ready, app_ready_detail = await self._wait_for_flow_app_ready(page, timeout_s=45.0)
        top_banner_detail = await self._dismiss_flow_top_banner(page)
        if job_id:
            await self.store.append_log(job_id, f"Fallback UI Flow: tab hiện tại {str(getattr(page, 'url', '') or '')[:160]}.")
            if top_banner_detail:
                await self.store.append_log(job_id, f"Fallback UI Flow: {top_banner_detail[:160]}.")
            await self.store.append_log(
                job_id,
                (
                    f"Fallback UI Flow: trang Flow đã render ({app_ready_detail[:140]})."
                    if app_ready
                    else f"Fallback UI Flow: trang Flow chưa render xong sau khi chờ ({app_ready_detail[:140]})."
                ),
            )

        interceptor = UIInterceptor()
        interceptor.attach(page)
        interceptor.clear()

        try:
            await client._ui.open_settings_panel(page)
            await client._ui.select_image_model(page, self._image_ui_model_label(model))
            await client._ui.set_aspect_ratio(page, ratio)
            await client._ui.set_count(page, target_count)
            if job_id:
                await self.store.append_log(job_id, f"Fallback UI Flow: đã đặt số lượng ảnh x{target_count}.")
        except Exception as settings_exc:
            if job_id:
                await self.store.append_log(
                    job_id,
                    f"Fallback UI Flow: chưa chỉnh được model/số lượng trên UI ({humanize_flow_error(str(settings_exc))[:120]}).",
                )

        agent_opened = False
        if flow_agent_enabled:
            try:
                await page.keyboard.press("Escape")
                await asyncio.sleep(0.4)
            except Exception:
                pass
            agent_opened, agent_detail = await self._enable_flow_agent_mode(page)
            if job_id:
                if agent_opened:
                    await self.store.append_log(job_id, f"Fallback UI Flow: đã bật Tác nhân Flow ({agent_detail[:120]}).")
                else:
                    await self.store.append_log(
                        job_id,
                        f"Fallback UI Flow: chưa thấy nút Tác nhân, dừng để tránh tạo ảnh prompt-only ({agent_detail[:120]}).",
                    )
            if not agent_opened:
                raise RuntimeError(
                    "Auto AI ERP bắt buộc dùng Tác nhân Flow. App chưa thấy nút Tác nhân trên màn hình Flow, "
                    "nên đã dừng trước khi nhập lệnh để tránh tạo ảnh không dùng ảnh nguồn."
                )

        filled = False
        if flow_agent_enabled:
            panel_opened, panel_detail = await self._open_flow_agent_panel(page)
            if job_id:
                await self.store.append_log(
                    job_id,
                    (
                        f"Fallback UI Flow: đã mở panel Tác nhân ({panel_detail[:120]})."
                        if panel_opened
                        else f"Fallback UI Flow: chưa mở được panel Tác nhân ({panel_detail[:120]})."
                    ),
                )
            if not panel_opened:
                raise RuntimeError(
                    "Auto AI ERP cần mở panel Tác nhân Flow trước khi kéo ảnh vào AI. "
                    "App đã dừng để tránh chỉ gửi prompt mà không có ảnh nguồn."
                )

            fresh_panel, fresh_panel_detail = await self._ensure_fresh_flow_agent_panel(page)
            if job_id and fresh_panel_detail:
                await self.store.append_log(job_id, f"Fallback UI Flow: kiem tra phien Agent ({fresh_panel_detail[:160]}).")
            if not fresh_panel:
                discard_detail = await self._discard_cached_flow_agent_page(client, page)
                if job_id:
                    await self.store.append_log(
                        job_id,
                        f"Fallback UI Flow: đóng tab Agent chưa sạch trước khi thử lại ({discard_detail[:160]}).",
                    )
                raise RuntimeError(
                    "Tac nhan Flow dang mo lai hoi thoai cu hoac ngu canh project cu. "
                    "App da dung truoc khi gui prompt de tranh Flow lay sai san pham. "
                    f"Chi tiet: {fresh_panel_detail}; {discard_detail}"
                )

            filled, fill_detail = await self._fill_flow_agent_panel_instruction(page, prompt)
            if job_id and fill_detail:
                await self.store.append_log(job_id, f"Fallback UI Flow: nhập prompt trong panel Tác nhân ({fill_detail[:120]}).")
            if not filled:
                raise RuntimeError(
                    "Auto AI ERP đã bật Tác nhân Flow nhưng chưa nhập được lệnh vào panel Tác nhân. "
                    "App đã dừng trước khi dùng ô prompt thường."
                )
        else:
            filled = await client._ui.fill_prompt(page, prompt)
        if not filled:
            raise RuntimeError("Google Flow chua dien duoc prompt vao man hinh chinh anh.")
        if job_id:
            await self.store.append_log(
                job_id,
                "Fallback UI Flow: đã điền prompt vào panel Tác nhân Flow." if flow_agent_enabled else "Fallback UI Flow: đã điền prompt vào ô tạo ảnh.",
            )

        attached_agent_source = False
        attached_local_source = False
        source_attachment_before: Dict[str, Any] = {}
        source_attachment_verified = not flow_agent_enabled or text_only_agent
        source_verify_detail = ""
        if flow_agent_enabled and str(reference_media_name or "").strip():
            source_attachment_before = await self._flow_agent_panel_attachment_snapshot(page)
            dragged_source, drag_detail = await self._select_flow_edit_target_image(
                page,
                reference_media_name,
                workflow_id=resolved_workflow_id,
                allow_visible_fallback=False,
                require_agent_panel=True,
            )
            attached_agent_source = dragged_source
            if attached_agent_source:
                source_attachment_verified, source_verify_detail = await self._wait_for_flow_agent_source_attachment(
                    page,
                    source_attachment_before,
                )
            if job_id:
                await self.store.append_log(
                    job_id,
                    (
                        f"Fallback UI Flow: đã kéo ảnh nguồn vào khung Tác nhân ({drag_detail[:120]})."
                        if dragged_source
                        else f"Fallback UI Flow: chưa kéo được ảnh nguồn vào khung Tác nhân ({drag_detail[:120]})."
                    ),
                )
                if dragged_source:
                    await self.store.append_log(
                        job_id,
                        (
                            f"Fallback UI Flow: da xac minh anh nguon nam trong panel Tac nhan ({source_verify_detail[:140]})."
                            if source_attachment_verified
                            else f"Fallback UI Flow: chua thay anh nguon trong panel Tac nhan sau khi keo ({source_verify_detail[:140]})."
                        ),
                    )
        elif flow_agent_enabled and job_id:
            await self.store.append_log(
                job_id,
                "Fallback UI Flow: prompt-only, khong dinh kem anh nguon vao Tac nhan Flow."
                if text_only_agent
                else "Fallback UI Flow: no project media id for the ERP source; using local file attach in Flow Agent.",
            )

        if flow_agent_enabled and (not attached_agent_source or not source_attachment_verified) and safe_reference_image_path:
            fallback_before = await self._flow_agent_panel_attachment_snapshot(page)
            upload_call_start = len(getattr(interceptor, "_calls", []) or [])
            attached_local_source, attach_detail = await self._attach_flow_agent_source_file(
                page,
                safe_reference_image_path,
                before_snapshot=fallback_before,
            )
            if attached_local_source:
                attached_agent_source = True
                source_file_name = Path(safe_reference_image_path).name
                source_attachment_verified, source_verify_detail = await self._wait_for_flow_agent_source_attachment(
                    page,
                    fallback_before,
                    timeout_s=25.0,
                    source_file_name=source_file_name,
                )
                upload_ready, upload_ready_detail = await self._wait_for_flow_agent_upload_ready(
                    interceptor,
                    upload_call_start,
                    timeout_s=5.0 if source_attachment_verified else min(60.0, max(20.0, ui_timeout_s / 5)),
                )
                if not source_attachment_verified and upload_ready:
                    source_attachment_verified, source_verify_detail = await self._wait_for_flow_agent_source_attachment(
                        page,
                        fallback_before,
                        accept_stable_ready_after_attach=True,
                        source_file_name=source_file_name,
                    )
                source_verify_detail = f"{upload_ready_detail}; {source_verify_detail}"
            if job_id:
                await self.store.append_log(
                    job_id,
                    (
                        f"Fallback UI Flow: đã upload ảnh ERP vào khung Tác nhân ({attach_detail[:120]})."
                        if attached_local_source and source_attachment_verified
                        else f"Fallback UI Flow: chưa upload được ảnh ERP vào khung Tác nhân ({attach_detail[:120]})."
                    ),
                )
            if not attached_agent_source or not source_attachment_verified:
                raise RuntimeError(
                    "Auto AI ERP chưa kéo/upload được ảnh ERP vào Tác nhân Flow. "
                    f"App đã dừng trước khi bấm tạo để tránh tạo ảnh không dùng ảnh nguồn. Chi tiết: {attach_detail}; {source_verify_detail}"
                )

        elif flow_agent_enabled and not source_attachment_verified:
            raise RuntimeError(
                "Auto AI ERP chua xac minh duoc anh nguon trong panel Tac nhan Flow. "
                "App da dung truoc khi bam tao de tranh Flow Agent dung ngu canh/anh cu. "
                f"Chi tiet: {source_verify_detail or 'khong thay attachment moi trong panel'}"
            )

        if not attached_agent_source:
            selected, selected_detail = await self._select_flow_edit_target_image(
                page,
                reference_media_name,
                workflow_id=resolved_workflow_id,
                allow_visible_fallback=not flow_agent_enabled,
            )
            if not selected:
                raise RuntimeError(
                    "Google Flow chua gan duoc anh goc vao lenh tao anh, nen em dung lai de tranh tao anh moi tu prompt. "
                    f"Chi tiet: {selected_detail or 'khong tim thay anh co the click'}"
                )
            if job_id:
                await self.store.append_log(job_id, f"Fallback UI Flow: đã gắn ảnh gốc vào lệnh ({selected_detail[:120]}).")

        try:
            known_media_before_submit = self._project_media_names(await client._api.get_project_data())
        except Exception as exc:
            if require_project_media_baseline:
                raise RuntimeError(
                    "Auto AI ERP không đọc được danh sách ảnh hiện có trong Flow trước khi bấm tạo. "
                    "App đã dừng để tránh lấy nhầm ảnh cũ trong project rồi upload sai card."
                ) from exc
            known_media_before_submit = set()
        # Grid srcs already on the page: anything else that appears after the submit is this card's output.
        visible_before_submit: set[str] | None = (await self._visible_flow_grid_image_keys(client)) if flow_agent_enabled else None

        pre_submit_quota_message = ""
        pre_submit_try_again_message = ""
        if flow_agent_enabled:
            pre_submit_quota_message = await self._visible_flow_agent_quota_message(page)
            pre_submit_try_again_message = await self._visible_flow_agent_try_again_message(page)

        if flow_agent_enabled:
            clicked, click_detail = await self._click_flow_agent_panel_send(page)
        else:
            clicked, click_detail = await self._click_flow_create_button(page)
            if not clicked:
                clicked = await client._ui.click_submit(page)
                click_detail = "fallback FlowUI.click_submit"
        if not clicked:
            raise RuntimeError(
                (
                    "Tác nhân Flow đã có prompt và ảnh nguồn nhưng app chưa bấm được nút gửi trong panel AI. "
                    if flow_agent_enabled
                    else "Google Flow chua bam duoc nut tao anh o man hinh chinh anh. "
                )
                + f"Chi tiet: {click_detail or 'khong tim thay nut Create/Tao'}"
            )
        if job_id:
            await self.store.append_log(
                job_id,
                (
                    f"Fallback UI Flow: đã gửi panel Tác nhân ({click_detail[:120]}), chờ Flow trả ảnh tối đa {int(ui_timeout_s)} giây."
                    if flow_agent_enabled
                    else f"Fallback UI Flow: đã bấm nút tạo ảnh ({click_detail[:120]}), chờ Flow trả ảnh tối đa {int(ui_timeout_s)} giây."
                ),
            )

        if flow_agent_enabled:
            await asyncio.sleep(1.5)
            await self._raise_flow_agent_quota_if_visible(
                page,
                job_id=job_id,
                ignore_message=pre_submit_quota_message,
            )
            await self._raise_flow_agent_try_again_if_visible(
                page,
                job_id=job_id,
                ignore_message=pre_submit_try_again_message,
            )
            panel_ok, panel_detail, needs_prompt = await self._ensure_flow_agent_panel_submitted(page, prompt, submit_if_needed=False)
            if job_id:
                await self.store.append_log(
                    job_id,
                    (
                        f"Fallback UI Flow: đã mở/dùng panel Tác nhân ({panel_detail[:160]})."
                        if panel_ok
                        else f"Fallback UI Flow: chưa xác nhận được panel Tác nhân ({panel_detail[:160]})."
                    ),
                )
            if needs_prompt:
                raise RuntimeError(
                    "Tác nhân Flow đã mở panel nhưng app chưa gửi được lệnh trong panel Agent. "
                    "App đã dừng trước khi chờ ảnh để tránh chạy sai."
                )

        if flow_agent_enabled and flow_agent_auto_approve:
            approved, approve_detail = await self._approve_flow_agent_generation(
                page,
                timeout_s=min(45.0, max(10.0, ui_timeout_s / 6)),
            )
            if job_id:
                await self.store.append_log(
                    job_id,
                    (
                        f"Fallback UI Flow: đã tự phê duyệt Tác nhân Flow ({approve_detail[:120]})."
                        if approved
                        else f"Fallback UI Flow: không thấy hộp phê duyệt Tác nhân ({approve_detail[:120]})."
                    ),
                )

        network_wait_s = (
            min(ui_timeout_s, self._flow_agent_network_wait_seconds())
            if flow_agent_enabled
            else ui_timeout_s
        )
        try:
            result = await interceptor.wait_for(
                "batchGenerateImages",
                timeout=network_wait_s,
                require_success=True,
            )
        except Exception as exc:
            detail = str(exc or "").lower()
            if "timed out" in detail or "timeout" in detail or "recaptcha" in detail:
                if job_id:
                    await self.store.append_log(job_id, f"Fallback UI Flow timeout/recaptcha: {str(exc)[:300]}")
                if flow_agent_enabled:
                    await self._raise_flow_agent_quota_if_visible(
                        page,
                        job_id=job_id,
                        ignore_message=pre_submit_quota_message,
                    )
                    await self._raise_flow_agent_try_again_if_visible(
                        page,
                        job_id=job_id,
                        ignore_message=pre_submit_try_again_message,
                    )
                    try:
                        if flow_agent_auto_approve:
                            approved, approve_detail = await self._approve_flow_agent_generation(page, timeout_s=8.0)
                            if approved and job_id:
                                await self.store.append_log(
                                    job_id,
                                    f"Fallback UI Flow: đã tự phê duyệt Tác nhân Flow sau timeout ({approve_detail[:120]}).",
                                )
                        # Under load the Agent needs 4-6 minutes for 12 images; re-submitting earlier
                        # generates a second set for the same card (double Flow credits).
                        images = await self._wait_for_flow_agent_images_after_submit(
                            client,
                            page,
                            known_media_before_submit,
                            prompt=prompt,
                            target_count=target_count,
                            timeout_s=max(float(ui_timeout_s), 420.0),
                            fallback_workflow_id=resolved_workflow_id,
                            job_id=job_id,
                            visible_before=visible_before_submit,
                        )
                        if images:
                            if job_id and getattr(images[0], "_raw", {}).get("visible_ui_fallback"):
                                await self.store.append_log(
                                    job_id,
                                    f"Fallback UI Flow: nhan {len(images)} anh moi tu grid Flow (khong co trong grid truoc khi gui).",
                                )
                            if job_id:
                                await self.store.append_log(
                                    job_id,
                                    f"Fallback UI Flow: Flow Agent đã tạo {len(images)} ảnh mới trong project.",
                                )
                            return images[:target_count]
                    except FlowAgentFailedError:
                        raise
                    except Exception as project_exc:
                        if job_id:
                            await self.store.append_log(
                                job_id,
                                f"Fallback UI Flow: chưa lấy được ảnh mới sau Flow Agent ({str(project_exc)[:220]}).",
                            )
                raise RuntimeError(
                    "Google Flow chua tra ve anh tu man hinh Flow trong thoi gian cho. "
                    "Hay kiem tra tab Flow co dang tao, bi dung o nut Create, hoac co thong bao can thao tac thu cong khong. "
                    f"Chi tiet: {humanize_flow_error(str(exc))[:240]}"
                ) from exc
            raise

        if not self._flow_image_call_uses_selected_image(
            result,
            reference_media_name,
            resolved_workflow_id,
            allow_any_image_input=attached_local_source,
        ):
            raise RuntimeError(
                "Flow vua gui request tao anh nhung request khong co anh goc dang chon. "
                "Em da dung lai de tranh luu anh moi khong dung card ERP."
            )

        images = self._parse_images_from_flow_payload(
            result.resp,
            prompt=prompt,
            fallback_workflow_id=resolved_workflow_id,
        )
        if not images:
            images = await self._wait_for_new_project_images(
                client,
                known_media_before_submit,
                prompt=prompt,
                target_count=target_count,
                timeout_s=ui_timeout_s,
                fallback_workflow_id=resolved_workflow_id,
                allow_visible_fallback=flow_agent_enabled and not known_media_before_submit,
            )
        elif flow_agent_enabled and len(images) < target_count:
            if job_id:
                await self.store.append_log(
                    job_id,
                    f"Fallback UI Flow: response đầu có {len(images)}/{target_count} ảnh; app chờ project render thêm trước khi chạy lượt mới.",
                )
            try:
                project_images = await self._wait_for_new_project_images(
                    client,
                    known_media_before_submit,
                    prompt=prompt,
                    target_count=target_count,
                    timeout_s=min(ui_timeout_s, 150.0),
                    fallback_workflow_id=resolved_workflow_id,
                    settle_s=min(90.0, max(25.0, ui_timeout_s / 5)),
                    allow_visible_fallback=flow_agent_enabled and not known_media_before_submit,
                )
                merged: List[Any] = []
                seen_keys: set[str] = set()
                for image in [*images, *project_images]:
                    key = (
                        str(getattr(image, "media_name", "") or "").strip()
                        or str(getattr(image, "fife_url", "") or "").strip()
                        or str(getattr(image, "workflow_id", "") or "").strip()
                    )
                    if key and key in seen_keys:
                        continue
                    if key:
                        seen_keys.add(key)
                    merged.append(image)
                images = merged
                if job_id:
                    await self.store.append_log(
                        job_id,
                        f"Fallback UI Flow: sau khi chờ project có {len(images)}/{target_count} ảnh.",
                    )
            except Exception as project_exc:
                if job_id:
                    await self.store.append_log(
                        job_id,
                        f"Fallback UI Flow: chưa thấy thêm ảnh sau khi chờ project ({str(project_exc)[:220]}).",
                    )

        if not images:
            raise RuntimeError("Google Flow khong tra anh nao ve tu man hinh chinh anh.")
        return images[:target_count]

    def _flow_agent_enabled_for_request(self, request: CreateJobRequest) -> bool:
        enabled = self._config_bool(getattr(request, "flow_agent_enabled", True), default=True)
        try:
            graph = self._automation_graph_payload(request)
        except Exception:
            graph = {"modules": []}
        for module in graph.get("modules", []):
            if module.get("type") != "flow":
                continue
            settings = module.get("settings") if isinstance(module.get("settings"), dict) else {}
            if "flowAgentEnabled" in settings:
                return self._config_bool(settings.get("flowAgentEnabled"), default=enabled)
        return enabled

    def _flow_agent_auto_approve_enabled_for_request(self, request: CreateJobRequest) -> bool:
        enabled = self._config_bool(getattr(request, "flow_agent_auto_approve", True), default=True)
        try:
            graph = self._automation_graph_payload(request)
        except Exception:
            graph = {"modules": []}
        for module in graph.get("modules", []):
            if module.get("type") != "flow":
                continue
            settings = module.get("settings") if isinstance(module.get("settings"), dict) else {}
            if "flowAgentAutoApprove" in settings:
                return self._config_bool(settings.get("flowAgentAutoApprove"), default=enabled)
        return enabled

    def _request_requires_flow_agent_ui(self, request: CreateJobRequest) -> bool:
        if not self._flow_agent_enabled_for_request(request):
            return False
        marker = " ".join(
            str(value or "")
            for value in (
                getattr(request, "title", ""),
                getattr(request, "prompt", ""),
                getattr(request, "prompt_notes", ""),
                getattr(request, "prompt_product", ""),
                getattr(request, "prompt_product_key", ""),
            )
        ).lower()
        if self._normalize_erp_task_id(getattr(request, "erp_task_id", "")):
            return True
        return any(
            token in marker
            for token in (
                "use google flow agent",
                "flow agent",
                "tác nhân flow",
                "tac nhan flow",
                "auto ai erp",
            )
        )

    async def _acquire_isolated_flow_agent_page(self, client: Any, project_url: str) -> tuple[Any, str]:
        target_url = str(project_url or "").strip()
        browser = getattr(client, "_bm", None)
        context = getattr(browser, "context", None)
        if context is not None:
            cached_page = getattr(browser, "_flow_agent_page", None)
            if cached_page is not None:
                try:
                    is_closed = bool(cached_page.is_closed()) if hasattr(cached_page, "is_closed") else False
                    if not is_closed:
                        # A previous Flow Agent prompt can still be rendering in this
                        # tab even after our network wait times out or a batch moves on.
                        # Reusing it would navigate the page and wipe the in-flight
                        # Agent command, so leave it open and create a fresh tab below.
                        pass
                except Exception:
                    try:
                        browser._flow_agent_page = None
                    except Exception:
                        pass
            try:
                page = await context.new_page()
                try:
                    browser._page = page
                except Exception:
                    pass
                try:
                    browser._flow_agent_page = page
                except Exception:
                    pass
                if target_url:
                    ok, detail = await self._ensure_valid_flow_project_page(page, target_url)
                    if not ok:
                        raise FlowProjectNotFoundError(detail)
                try:
                    await page.bring_to_front()
                except Exception:
                    pass
                return page, "new isolated project tab"
            except FlowProjectNotFoundError:
                raise
            except Exception as exc:
                detail = humanize_flow_error(str(exc))
                try:
                    page = await browser.page()
                    return page, f"fallback existing tab after new tab failed: {detail[:80]}"
                except Exception:
                    raise

        page = await browser.page()
        return page, "browser manager page"

    async def _discard_cached_flow_agent_page(self, client: Any, page: Any) -> str:
        browser = getattr(client, "_bm", None)
        if browser is None or page is None:
            return "no cached Flow Agent tab to close"
        try:
            cached_page = getattr(browser, "_flow_agent_page", None)
        except Exception:
            cached_page = None
        if cached_page is not page:
            return "current tab is not cached Flow Agent tab"

        try:
            browser._flow_agent_page = None
        except Exception:
            pass
        try:
            if getattr(browser, "_page", None) is page:
                browser._page = None
        except Exception:
            pass

        try:
            is_closed = bool(page.is_closed()) if hasattr(page, "is_closed") else False
        except Exception:
            is_closed = False
        if is_closed:
            return "cached Flow Agent tab was already closed"

        try:
            await page.close()
            return "closed stale cached Flow Agent tab"
        except Exception as exc:
            return f"could not close stale cached Flow Agent tab: {humanize_flow_error(str(exc))[:120]}"

    async def _wait_flow_agent_prior_context(self, page: Any, settle_s: float = 4.0) -> Dict[str, Any]:
        deadline = asyncio.get_running_loop().time() + max(0.5, float(settle_s or 4.0))
        state: Dict[str, Any] = {}
        while True:
            state = await self._flow_agent_panel_context_state(page)
            if state.get("has_prior_context"):
                return state
            if asyncio.get_running_loop().time() >= deadline:
                return state
            await asyncio.sleep(0.75)

    async def _ensure_fresh_flow_agent_panel(self, page: Any) -> tuple[bool, str]:
        # flow.google.com restores the previous Agent session a few seconds after the
        # panel opens, so an immediate check can pass on a panel that is about to fill
        # with old context. Settle first, then start a new session whenever the UI offers one.
        parts: List[str] = []
        state = await self._wait_flow_agent_prior_context(page, settle_s=4.0)
        if state.get("has_prior_context"):
            parts.append("old context visible after settle")
        new_session_ok, new_session_detail = await self._click_flow_agent_new_session_button(page)
        if new_session_ok:
            parts.append(new_session_detail)
            state = await self._wait_flow_agent_prior_context(page, settle_s=3.0)
        if state.get("has_prior_context"):
            reset_ok, reset_detail = await self._reset_flow_agent_panel_context(page)
            if not reset_ok:
                return False, f"old context visible; reset unavailable: {reset_detail}"
            parts.append(f"reset old Agent context: {reset_detail}")
            state = await self._wait_flow_agent_prior_context(page, settle_s=3.0)
            if state.get("has_prior_context"):
                return False, f"old context still visible after reset: {state.get('detail') or reset_detail}"
        parts.append(str(state.get("detail") or "agent panel has no prior context"))
        return True, "; ".join(part for part in parts if part)

    async def _flow_agent_panel_context_state(self, page: Any) -> Dict[str, Any]:
        try:
            result = await page.evaluate(
                """
                () => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 180 || rect.height < 120) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0'
                      && rect.bottom > 0
                      && rect.top < window.innerHeight;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                    el.getAttribute('data-testid') || '',
                    el.getAttribute('placeholder') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const panels = [...document.querySelectorAll('aside, dialog, section, div[role="dialog"], div')]
                    .filter(visible)
                    .map((el) => {
                      const rect = el.getBoundingClientRect();
                      const text = labelFor(el);
                      const rightPanel = rect.left >= window.innerWidth * 0.45 || rect.right >= window.innerWidth * 0.78;
                      const agentish = /Bạn\\s*muốn\\s*tạo\\s*gì|Ban\\s*muon\\s*tao\\s*gi|What\\s+do\\s+you|Flow\\s+Agent|Tác\\s*nhân|Tac\\s*nhan|Credit\\s+Spend\\s+Approval|Shot\\s+Brief|Design\\s+Analysis|generated\\s+the\\s+final/i.test(text);
                      const score = (rightPanel ? 1000 : 0) + (agentish ? 800 : 0) + rect.height / 10;
                      return { el, rect, text, score };
                    })
                    .filter((item) => item.score >= 900)
                    .sort((a, b) => b.score - a.score);
                  const panel = panels[0];
                  if (!panel) return { visible: false, has_prior_context: false, detail: 'agent panel not detected' };
                  const ariaText = [...panel.el.querySelectorAll('[aria-label]')]
                    .map((el) => el.getAttribute('aria-label') || '')
                    .join(' ');
                  const text = `${panel.text || ''} ${ariaText}`;
                  const hasPrior = /I['’]?ve\\s+generated|generated\\s+the\\s+final|Design\\s+Analysis|Shot\\s+Brief|Credit\\s+Spend\\s+Approval|source\\s+product\\s+image\\s+as\\s+the\\s+reference|Sheep\\s+pillow|Pillow\\s+with\\s+sheep|Teddy\\s+Swims|Good\\s+response|Bad\\s+response|Flag\\s+output|Open\\s+image\\s+in\\s+editor|I['’]?ve\\s+found\\s+several|Which\\s+one\\s+would\\s+you\\s+like/i.test(text);
                  return {
                    visible: true,
                    has_prior_context: hasPrior,
                    detail: hasPrior ? 'old Flow Agent conversation text is visible' : 'agent panel looks fresh',
                  };
                }
                """
            )
        except Exception as exc:
            return {"visible": False, "has_prior_context": False, "detail": f"agent context check skipped: {humanize_flow_error(str(exc))[:120]}"}
        return result if isinstance(result, dict) else {"visible": False, "has_prior_context": False, "detail": "agent context check unavailable"}

    async def _reset_flow_agent_panel_context(self, page: Any) -> tuple[bool, str]:
        direct_ok, direct_detail = await self._click_flow_agent_new_session_button(page)
        if direct_ok:
            return True, direct_detail
        try:
            menu_result = await page.evaluate(
                """
                () => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 18 || rect.height < 18) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0'
                      && !el.disabled
                      && rect.bottom > 0
                      && rect.top < window.innerHeight;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                    el.getAttribute('data-testid') || '',
                    el.getAttribute('class') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const panels = [...document.querySelectorAll('aside, dialog, section, div[role="dialog"], div')]
                    .filter((el) => {
                      if (!visible(el)) return false;
                      const rect = el.getBoundingClientRect();
                      return rect.width >= 280 && rect.height >= window.innerHeight * 0.45 && rect.left >= window.innerWidth * 0.35;
                    })
                    .sort((a, b) => b.getBoundingClientRect().right - a.getBoundingClientRect().right);
                  const panel = panels[0];
                  if (!panel) return { ok: false, detail: 'agent panel not found for reset' };
                  const panelRect = panel.getBoundingClientRect();
                  const buttons = [...panel.querySelectorAll('button, [role="button"], [aria-label], [title], svg, mat-icon')]
                    .filter(visible)
                    .map((el) => {
                      const control = el.closest('button, [role="button"], [tabindex]') || el;
                      const rect = control.getBoundingClientRect();
                      const label = `${labelFor(el)} ${labelFor(control)}`.replace(/\\s+/g, ' ').trim();
                      const topLeft = rect.top <= panelRect.top + 96 && rect.left <= panelRect.left + 96;
                      const menuish = /menu|hamburger|drawer|history|chat|conversation|more|list/i.test(label);
                      const compact = rect.width <= 80 && rect.height <= 80;
                      const score = (topLeft ? 1200 : 0) + (menuish ? 800 : 0) + (compact ? 250 : -500) - (label.length > 160 ? 700 : 0);
                      return { el: control, rect, label, score };
                    })
                    .filter(({ el }, index, arr) => arr.findIndex((item) => item.el === el) === index)
                    .filter((item) => item.score >= 900)
                    .sort((a, b) => b.score - a.score);
                  const target = buttons[0];
                  if (!target) return { ok: false, detail: 'no agent menu button' };
                  target.el.scrollIntoView({ block: 'center', inline: 'center' });
                  target.el.click();
                  return { ok: true, detail: target.label || 'agent menu button' };
                }
                """
            )
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

        if not isinstance(menu_result, dict) or not menu_result.get("ok"):
            return False, str((menu_result or {}).get("detail") or "agent menu not opened") if isinstance(menu_result, dict) else "agent menu not opened"

        await asyncio.sleep(0.5)
        try:
            item_result = await page.evaluate(
                """
                () => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 36 || rect.height < 22) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0'
                      && !el.disabled
                      && rect.bottom > 0
                      && rect.top < window.innerHeight;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                    el.getAttribute('data-testid') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const candidates = [...document.querySelectorAll('[role="menu"] button, [role="menu"] [role="menuitem"], dialog button, aside button, button, [role="button"]')]
                    .filter(visible)
                    .map((el) => {
                      const rect = el.getBoundingClientRect();
                      const label = labelFor(el);
                      const rightHalf = rect.left >= window.innerWidth * 0.35 || rect.right >= window.innerWidth * 0.65;
                      const newish = /new\\s*(chat|conversation|session|task)|start\\s*new|fresh\\s*(chat|task)|reset\\s*(chat|conversation)|clear\\s*(chat|conversation)|cuộc\\s+trò\\s+chuyện\\s+mới|cuoc\\s+tro\\s+chuyen\\s+moi|phiên\\s+mới|phien\\s+moi|tạo\\s+mới|tao\\s+moi|mới$/i.test(label);
                      const dangerous = /new\\s*project|dự\\s*án\\s*mới|du\\s*an\\s*moi|delete|xóa|xoa|trash|remove/i.test(label);
                      const score = (rightHalf ? 800 : 0) + (newish ? 1500 : 0) - (dangerous ? 2000 : 0) - (label.length > 120 ? 500 : 0);
                      return { el, rect, label, score };
                    })
                    .filter((item) => item.score >= 1500)
                    .sort((a, b) => b.score - a.score);
                  const target = candidates[0];
                  if (!target) return { ok: false, detail: 'no new chat/session item' };
                  target.el.scrollIntoView({ block: 'center', inline: 'center' });
                  target.el.click();
                  return { ok: true, detail: target.label || 'new chat item' };
                }
                """
            )
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

        if isinstance(item_result, dict) and item_result.get("ok"):
            return True, str(item_result.get("detail") or menu_result.get("detail") or "new Agent session")
        return False, str((item_result or {}).get("detail") or "new Agent session item not found") if isinstance(item_result, dict) else "new Agent session item not found"

    async def _enable_flow_agent_mode(self, page: Any) -> tuple[bool, str]:
        try:
            state = await self._flow_agent_panel_state(page, "")
            if state.get("visible"):
                return True, str(state.get("detail") or "agent panel already visible")
        except Exception:
            pass

        locator_patterns = [
            re.compile(r"^\s*(Tác\s*nhân|Tac\s*nhan|Agent)\s*$", re.IGNORECASE),
        ]
        for pattern in locator_patterns:
            for locator_factory in (
                lambda pat=pattern: page.get_by_role("button", name=pat).first(),
            ):
                try:
                    locator = locator_factory()
                    if await locator.count():
                        label = ""
                        try:
                            label = str(await locator.inner_text(timeout=800) or "").strip()
                        except Exception:
                            label = getattr(pattern, "pattern", "Flow Agent")
                        await locator.click(timeout=2500)
                        await asyncio.sleep(0.8)
                        return True, label or getattr(pattern, "pattern", "Flow Agent")
                except Exception:
                    continue

        try:
            result = await page.evaluate(
                """
                () => {
                  const deepQuery = (selector, root = document, seen = new Set()) => {
                    const found = [];
                    const visit = (node) => {
                      if (!node || seen.has(node)) return;
                      seen.add(node);
                      try {
                        found.push(...node.querySelectorAll(selector));
                        for (const el of node.querySelectorAll('*')) {
                          if (el.shadowRoot) visit(el.shadowRoot);
                        }
                      } catch (_) {}
                    };
                    visit(root);
                    return found;
                  };
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 36 || rect.height < 24) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0'
                      && rect.bottom > 0
                      && rect.top < window.innerHeight;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                    el.getAttribute('data-testid') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const controls = deepQuery('button, [role="button"], a, div, span')
                    .filter(visible)
                    .map((el) => {
                      const control = el.closest('button, [role="button"], a') || el;
                      const rect = control.getBoundingClientRect();
                      const rawLabel = `${labelFor(el)} ${labelFor(control)}`.replace(/\\s+/g, ' ').trim();
                      const exact = /^\\s*(Tác\\s*nhân|Tac\\s*nhan|Agent)\\s*$/i.test(rawLabel);
                      const contains = /Tác\\s*nhân|Tac\\s*nhan|Agent/i.test(rawLabel);
                      const compact = rect.width >= 52 && rect.width <= 280 && rect.height >= 28 && rect.height <= 110;
                      const bottom = rect.top >= window.innerHeight * 0.35;
                      const noisy = rawLabel.length > 120 || rect.width > window.innerWidth * 0.55 || rect.height > 180;
                      const score = (exact ? 3000 : 0)
                        + (contains ? 800 : 0)
                        + (compact ? 900 : -700)
                        + (bottom ? 250 : 0)
                        - (noisy ? 1600 : 0)
                        + rect.bottom / 100;
                      return { el: control, rect, label: rawLabel, score, contains };
                    })
                    .filter(({ el }, index, arr) => arr.findIndex((item) => item.el === el) === index)
                    .filter(({ contains, score }) => contains && score > 0);
                  const target = controls
                    .sort((a, b) => b.score - a.score)[0];
                  if (!target) return { ok: false, detail: 'no visible Tac nhan/Agent button' };
                  target.el.scrollIntoView({ block: 'center', inline: 'center' });
                  const rect = target.el.getBoundingClientRect();
                  return {
                    ok: true,
                    x: rect.left + rect.width / 2,
                    y: rect.top + rect.height / 2,
                    detail: target.label || target.el.outerHTML?.slice(0, 160) || 'Tac nhan',
                  };
                }
                """
            )
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

        ok = bool((result or {}).get("ok")) if isinstance(result, dict) else False
        detail = str((result or {}).get("detail") or "").strip() if isinstance(result, dict) else ""
        if not ok:
            panel_opened, panel_detail = await self._open_flow_agent_panel(page, timeout_s=3.0)
            if panel_opened:
                return True, f"agent panel opened without toggle: {panel_detail}"
            return False, detail
        try:
            await page.mouse.click(float((result or {}).get("x")), float((result or {}).get("y")))
            await asyncio.sleep(0.8)
            return True, detail
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

    async def _open_flow_agent_panel(self, page: Any, timeout_s: float = 6.0) -> tuple[bool, str]:
        deadline = asyncio.get_running_loop().time() + max(1.5, float(timeout_s or 6.0))
        last_detail = "agent panel not visible"
        while asyncio.get_running_loop().time() < deadline:
            state = await self._flow_agent_panel_state(page, "")
            if state.get("visible"):
                return True, str(state.get("detail") or "agent panel visible")

            try:
                result = await page.evaluate(
                    """
                    () => {
                      const deepQuery = (selector, root = document, seen = new Set()) => {
                        const found = [];
                        const visit = (node) => {
                          if (!node || seen.has(node)) return;
                          seen.add(node);
                          try {
                            found.push(...node.querySelectorAll(selector));
                            for (const el of node.querySelectorAll('*')) {
                              if (el.shadowRoot) visit(el.shadowRoot);
                            }
                          } catch (_) {}
                        };
                        visit(root);
                        return found;
                      };
                      const visible = (el) => {
                        if (!el || !(el instanceof Element)) return false;
                        const rect = el.getBoundingClientRect();
                        if (rect.width < 24 || rect.height < 24) return false;
                        const style = window.getComputedStyle(el);
                        return style.visibility !== 'hidden'
                          && style.display !== 'none'
                          && style.opacity !== '0'
                          && !el.disabled
                          && rect.bottom > 0
                          && rect.top < window.innerHeight;
                      };
                      const disabledish = (el) => Boolean(
                        el.disabled
                        || el.getAttribute('aria-disabled') === 'true'
                        || el.closest('[disabled], [aria-disabled="true"]')
                      );
                      const labelFor = (el) => [
                        el.textContent || '',
                        el.getAttribute('aria-label') || '',
                        el.getAttribute('title') || '',
                        el.getAttribute('data-testid') || '',
                        el.getAttribute('jsname') || '',
                        el.getAttribute('class') || '',
                      ].join(' ').replace(/\\s+/g, ' ').trim();
                      const buttons = deepQuery('button, [role="button"], a, div, span, mat-icon, svg, [aria-label], [data-testid]')
                        .filter(visible)
                        .map((el) => {
                          const control = el.closest('button, [role="button"], a, [tabindex]') || el;
                          const rect = control.getBoundingClientRect();
                          const label = `${labelFor(el)} ${labelFor(control)}`.replace(/\\s+/g, ' ').trim();
                          const bottomComposer = rect.top >= window.innerHeight * 0.55;
                          const rightish = rect.left >= window.innerWidth * 0.62 || rect.right >= window.innerWidth * 0.82;
                          const arrowish = /arrow_forward|arrow_upward|arrow|send|gửi|gui|mũi\\s*tên|mui\\s*ten|open|expand|agent|tác\\s*nhân|tac\\s*nhan/i.test(label);
                          const compact = rect.width >= 24 && rect.width <= 112 && rect.height >= 24 && rect.height <= 112;
                          const unlabeledArrowSpot = !label && bottomComposer && rightish && compact;
                          const noisy = label.length > 160 || rect.width > 240 || rect.height > 160;
                          const score = (bottomComposer ? 900 : 0)
                            + (rightish ? 1000 : 0)
                            + (arrowish ? 900 : 0)
                            + (unlabeledArrowSpot ? 650 : 0)
                            + (compact ? 250 : -900)
                            - (noisy ? 1200 : 0)
                            + rect.right / 50;
                          return { el: control, rect, label, score, disabled: disabledish(control) };
                        })
                        .filter(({ el }, index, arr) => arr.findIndex((item) => item.el === el) === index)
                        .filter((item) => !item.disabled && item.score >= 1800)
                        .sort((a, b) => b.score - a.score);
                      const target = buttons[0];
                      if (!target) return { ok: false, detail: 'no visible agent panel opener' };
                      target.el.scrollIntoView({ block: 'center', inline: 'center' });
                      const rect = target.el.getBoundingClientRect();
                      return {
                        ok: true,
                        x: rect.left + rect.width / 2,
                        y: rect.top + rect.height / 2,
                        detail: target.label || target.el.outerHTML?.slice(0, 120) || 'agent panel opener',
                      };
                    }
                    """
                )
            except Exception as exc:
                return False, humanize_flow_error(str(exc))

            ok = bool((result or {}).get("ok")) if isinstance(result, dict) else False
            last_detail = str((result or {}).get("detail") or last_detail).strip() if isinstance(result, dict) else last_detail
            if ok:
                try:
                    await page.mouse.click(float((result or {}).get("x")), float((result or {}).get("y")))
                    await asyncio.sleep(1.0)
                except Exception as exc:
                    return False, humanize_flow_error(str(exc))
            else:
                await asyncio.sleep(0.5)

        state = await self._flow_agent_panel_state(page, "")
        if state.get("visible"):
            return True, str(state.get("detail") or "agent panel visible")
        return False, str(state.get("detail") or last_detail)

    async def _ensure_flow_agent_panel_submitted(
        self,
        page: Any,
        prompt: str,
        timeout_s: float = 8.0,
        *,
        submit_if_needed: bool = True,
    ) -> tuple[bool, str, bool]:
        prompt = str(prompt or "").strip()
        deadline = asyncio.get_running_loop().time() + max(1.0, float(timeout_s or 8.0))
        last_detail = "agent panel not visible"
        while asyncio.get_running_loop().time() < deadline:
            state = await self._flow_agent_panel_state(page, prompt)
            if state.get("visible"):
                detail = str(state.get("detail") or "agent panel visible")
                if state.get("has_prompt"):
                    return True, f"{detail}; prompt already submitted", False
                if state.get("has_prompt_in_textbox"):
                    sent, send_detail = await self._click_flow_agent_panel_send(page)
                    if not sent:
                        return False, f"{detail}; prompt remains in composer; send failed: {send_detail}", True
                    await asyncio.sleep(1.5)
                    submitted_state = await self._flow_agent_panel_state(page, prompt)
                    if submitted_state.get("has_prompt") or not submitted_state.get("has_prompt_in_textbox"):
                        return True, f"{detail}; sent prompt in panel via {send_detail}", False
                    return False, f"{detail}; prompt remains in composer after clicking {send_detail}", True
                if not submit_if_needed:
                    return True, f"{detail}; send already clicked", False
                if not state.get("has_textbox"):
                    return True, f"{detail}; no editable textbox", False
                filled, fill_detail = await self._fill_flow_agent_panel_instruction(page, prompt)
                if not filled:
                    return False, f"{detail}; {fill_detail}", True
                sent, send_detail = await self._click_flow_agent_panel_send(page)
                if not sent:
                    return False, f"{detail}; prompt filled but send failed: {send_detail}", True
                await asyncio.sleep(1.5)
                return True, f"{detail}; sent prompt in panel via {send_detail}", False
            last_detail = str(state.get("detail") or last_detail)
            await asyncio.sleep(0.5)
        return False, last_detail, False

    async def _flow_agent_panel_state(self, page: Any, prompt: str) -> Dict[str, Any]:
        prompt = str(prompt or "").strip()
        prompt_probe = prompt[:80]
        try:
            result = await page.evaluate(
                """
                ({ promptProbe }) => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 80 || rect.height < 40) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0'
                      && rect.bottom > 0
                      && rect.top < window.innerHeight;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('placeholder') || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                    el.getAttribute('data-testid') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const panels = [...document.querySelectorAll('aside, dialog, section, div[role="dialog"], div')]
                    .filter(visible)
                    .map((el) => {
                      const rect = el.getBoundingClientRect();
                      const text = labelFor(el);
                      const looksAgent = /Phiên\\s+không\\s+có\\s+tiêu\\s+đề|Phien\\s+khong\\s+co\\s+tieu\\s+de|Chào|Chao|Bạn\\s+muốn\\s+làm\\s+gì|Ban\\s+muon\\s+lam\\s+gi|Cùng\\s+tôi\\s+lên\\s+ý\\s+tưởng|Cung\\s+toi\\s+len\\s+y\\s+tuong/i.test(text);
                      const sidePanel = rect.width >= 280 && rect.height >= window.innerHeight * 0.45 && rect.left >= window.innerWidth * 0.35;
                      const score = (looksAgent ? 1000 : 0) + (sidePanel ? 300 : 0) + rect.height / 10;
                      return { el, rect, text, score, looksAgent, sidePanel };
                    })
                    .filter((item) => item.looksAgent || item.sidePanel)
                    .sort((a, b) => b.score - a.score);
                  const panel = panels[0];
                  if (!panel) return { visible: false, detail: 'agent panel not visible' };
                  const textboxes = [...panel.el.querySelectorAll('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]')]
                    .filter((el) => {
                      if (!visible(el)) return false;
                      const label = labelFor(el);
                      const rect = el.getBoundingClientRect();
                      return rect.width >= 160 && rect.height >= 18 && /Bạn\\s*muốn\\s*tạo\\s*gì|Ban\\s*muon\\s*tao\\s*gi|What\\s+do\\s+you|prompt|create/i.test(label + ' ' + (el.textContent || ''));
                    });
                  const text = panel.text || '';
                  const probe = String(promptProbe || '').trim();
                  const composerText = textboxes
                    .map((el) => `${el.value || ''} ${el.textContent || ''}`.replace(/\\s+/g, ' ').trim())
                    .join('\\n');
                  const transcript = panel.el.cloneNode(true);
                  for (const editor of transcript.querySelectorAll('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]')) {
                    editor.remove();
                  }
                  const transcriptText = (transcript.textContent || '').replace(/\\s+/g, ' ').trim();
                  const hasPrompt = probe.length >= 16 && transcriptText.includes(probe);
                  const hasPromptInTextbox = probe.length >= 16 && composerText.includes(probe);
                  return {
                    visible: true,
                    has_textbox: textboxes.length > 0,
                    has_prompt: hasPrompt,
                    has_prompt_in_textbox: hasPromptInTextbox,
                    detail: (text.match(/Phiên\\s+không\\s+có\\s+tiêu\\s+đề|Phien\\s+khong\\s+co\\s+tieu\\s+de|Chào[^\\n]{0,40}|Chao[^\\n]{0,40}/i) || ['agent panel visible'])[0],
                  };
                }
                """,
                {"promptProbe": prompt_probe},
            )
        except Exception as exc:
            return {"visible": False, "detail": humanize_flow_error(str(exc))}
        return result if isinstance(result, dict) else {"visible": False, "detail": "agent panel state unavailable"}

    async def _fill_flow_agent_panel_instruction(self, page: Any, prompt: str) -> tuple[bool, str]:
        prompt = str(prompt or "").strip()
        if not prompt:
            return False, "empty prompt"
        try:
            result = await page.evaluate(
                """
                () => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 160 || rect.height < 18) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0'
                      && rect.bottom > 0
                      && rect.top < window.innerHeight;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('placeholder') || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const candidates = [...document.querySelectorAll('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]')]
                    .filter(visible)
                    .map((el) => {
                      const rect = el.getBoundingClientRect();
                      const label = labelFor(el);
                      const inRightPanel = rect.left >= window.innerWidth * 0.35;
                      const agentish = /Bạn\\s*muốn\\s*tạo\\s*gì|Ban\\s*muon\\s*tao\\s*gi|What\\s+do\\s+you|prompt|create/i.test(label);
                      const score = (inRightPanel ? 1000 : 0) + (agentish ? 600 : 0) + rect.bottom / 10;
                      return { el, rect, label, score };
                    })
                    .sort((a, b) => b.score - a.score);
                  const target = candidates[0];
                  if (!target) return { ok: false, detail: 'no agent panel textbox' };
                  target.el.scrollIntoView({ block: 'center', inline: 'center' });
                  const rect = target.el.getBoundingClientRect();
                  return {
                    ok: true,
                    x: rect.left + Math.min(rect.width - 16, Math.max(16, rect.width * 0.18)),
                    y: rect.top + rect.height / 2,
                    detail: target.label || target.el.tagName,
                  };
                }
                """
            )
        except Exception as exc:
            return False, humanize_flow_error(str(exc))
        if not isinstance(result, dict) or not result.get("ok"):
            return False, str((result or {}).get("detail") or "no agent panel textbox") if isinstance(result, dict) else "no agent panel textbox"
        try:
            await page.mouse.click(float(result.get("x")), float(result.get("y")))
            await asyncio.sleep(0.1)
            await page.keyboard.press("Meta+a")
            await page.keyboard.press("Control+a")
            await page.keyboard.press("Backspace")
            try:
                await page.keyboard.insert_text(prompt)
            except Exception:
                await page.keyboard.type(prompt, delay=10)
            await asyncio.sleep(1.0)
            return True, str(result.get("detail") or "agent panel textbox")
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

    async def _click_flow_agent_panel_send(self, page: Any) -> tuple[bool, str]:
        await self._dismiss_flow_top_banner(page)
        try:
            result = await page.evaluate(
                """
                /* agent-panel-send */
                () => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 24 || rect.height < 24) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden' && style.display !== 'none' && style.opacity !== '0' && !el.disabled;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                    el.getAttribute('data-testid') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const textboxes = [...document.querySelectorAll('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]')]
                    .filter((el) => {
                      if (!visible(el)) return false;
                      const rect = el.getBoundingClientRect();
                      return rect.left >= window.innerWidth * 0.35 && rect.width >= 160 && rect.height >= 18;
                    })
                    .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom);
                  const composer = textboxes[0];
                  if (!composer) return { ok: false, detail: 'no agent panel composer' };
                  const composerRect = composer.getBoundingClientRect();
                  const candidates = [...document.querySelectorAll('button, [role="button"]')]
                    .filter(visible)
                    .map((el) => {
                      const rect = el.getBoundingClientRect();
                      const label = labelFor(el);
                      const inRightPanel = rect.left >= window.innerWidth * 0.35;
                      const nearComposerBottom = Math.abs((rect.top + rect.height / 2) - composerRect.bottom) <= 150;
                      const insideComposerY = rect.top >= composerRect.top + composerRect.height * 0.55
                        && rect.bottom <= composerRect.bottom + 60;
                      const rightZone = rect.left >= composerRect.left + composerRect.width * 0.62;
                      const compact = rect.width <= 96 && rect.height <= 96;
                      const sendish = /arrow_forward|arrow_upward|send|gửi|gui|tạo|tao|create/i.test(label);
                      const excluded = /close|cancel|dismiss|attach|add|plus|settings|tune|menu|more|delete|remove|clear|đóng|dong|hủy|huy|đính\\s*kèm|dinh\\s*kem|cài\\s*đặt|cai\\s*dat/i.test(label);
                      const score = (inRightPanel ? 700 : -1000)
                        + (nearComposerBottom ? 1200 : -700)
                        + (insideComposerY ? 700 : -400)
                        + (rightZone ? 900 : -500)
                        + (sendish ? 1800 : 0)
                        + (compact ? 250 : -900)
                        + rect.right / 100;
                      return { el, rect, label, score, excluded };
                    });
                  const explicitSendButtons = candidates
                    .filter((item) =>
                      !item.excluded
                      && /arrow_forward|arrow_upward|send|gửi|gui|tạo|tao|create/i.test(item.label)
                      && item.rect.left >= window.innerWidth * 0.35
                      && item.rect.top >= window.innerHeight * 0.55
                      && item.rect.width <= 96
                      && item.rect.height <= 96
                    )
                    .sort((a, b) => (b.rect.right - a.rect.right) || (b.rect.bottom - a.rect.bottom));
                  const buttons = candidates
                    .filter((item) => !item.excluded && item.score >= 2600)
                    .sort((a, b) => b.score - a.score);
                  const target = explicitSendButtons[0] || buttons[0];
                  if (!target) return { ok: false, detail: 'no agent panel send button' };
                  let targetRect = target.rect;
                  if (targetRect.top + targetRect.height / 2 >= window.innerHeight - 2) {
                    try { target.el.scrollIntoView({ block: 'end', inline: 'nearest' }); } catch (_) {}
                    targetRect = target.el.getBoundingClientRect();
                  }
                  return {
                    ok: true,
                    x: targetRect.left + targetRect.width / 2,
                    y: targetRect.top + targetRect.height / 2,
                    offscreen: targetRect.top + targetRect.height / 2 >= window.innerHeight - 2 || targetRect.bottom <= 0,
                    detail: target.label || target.el.outerHTML?.slice(0, 120) || 'send',
                  };
                }
                """
            )
        except Exception as exc:
            return False, humanize_flow_error(str(exc))
        if not isinstance(result, dict) or not result.get("ok"):
            return False, str((result or {}).get("detail") or "no agent panel send button") if isinstance(result, dict) else "no agent panel send button"
        if result.get("offscreen"):
            return False, f"send button below the fold: {str(result.get('detail') or 'send')[:80]}"
        try:
            await page.mouse.click(float(result.get("x")), float(result.get("y")))
            await asyncio.sleep(0.8)
            return True, str(result.get("detail") or "send")
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

    async def _fill_flow_agent_instruction(self, page: Any, prompt: str) -> tuple[bool, str]:
        prompt = str(prompt or "").strip()
        if not prompt:
            return False, "empty prompt"
        try:
            result = await page.evaluate(
                """
                () => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 180 || rect.height < 18) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0'
                      && rect.bottom > 0
                      && rect.top < window.innerHeight;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('placeholder') || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                  ].join(' ');
                  const candidates = [...document.querySelectorAll('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]')]
                    .filter(visible)
                    .map((el) => {
                      const rect = el.getBoundingClientRect();
                      const label = labelFor(el);
                      let score = rect.top;
                      if (/Bạn\\s*muốn\\s*tạo\\s*gì|Ban\\s*muon\\s*tao\\s*gi|What\\s+do\\s+you\\s+want|prompt|create/i.test(label)) score += 1000;
                      if (rect.top > window.innerHeight * 0.45) score += 300;
                      return { el, rect, label, score };
                    })
                    .sort((a, b) => b.score - a.score);
                  const target = candidates[0];
                  if (!target) return { ok: false, detail: 'no prompt textbox for Tac nhan' };
                  target.el.scrollIntoView({ block: 'center', inline: 'center' });
                  const rect = target.el.getBoundingClientRect();
                  return {
                    ok: true,
                    x: rect.left + Math.min(rect.width - 16, Math.max(16, rect.width * 0.18)),
                    y: rect.top + rect.height / 2,
                    detail: target.label.trim() || target.el.tagName,
                  };
                }
                """
            )
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

        ok = bool((result or {}).get("ok")) if isinstance(result, dict) else False
        detail = str((result or {}).get("detail") or "").strip() if isinstance(result, dict) else ""
        if not ok:
            return False, detail
        try:
            await page.mouse.click(float((result or {}).get("x")), float((result or {}).get("y")))
            await asyncio.sleep(0.15)
            await page.keyboard.press("Meta+a")
            await page.keyboard.press("Control+a")
            await asyncio.sleep(0.05)
            await page.keyboard.press("Backspace")
            await asyncio.sleep(0.05)
            try:
                await page.keyboard.insert_text(prompt)
            except Exception:
                await page.keyboard.type(prompt, delay=10)
            await asyncio.sleep(0.2)
            return True, detail
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

    # Nút có sẵn của panel Tác nhân, không bao giờ là nút phê duyệt. Job
    # bca8eb89 (10/9) gắn ảnh, gửi lệnh xong thì bấm nhầm "Start new session":
    # phiên đang tạo ảnh bị bỏ, job không ra ảnh nào.
    _FLOW_AGENT_PANEL_OWN_BUTTON = re.compile(
        r"new\s*session|phi[eê]n\s*m[oớ]i|new\s*chat|edit_square|start\s*generation|arrow_forward|arrow_upward",
        re.IGNORECASE,
    )
    # Chữ phê duyệt thật. Ngoài hộp phê duyệt thì chỉ chữ này mới được bấm;
    # "Start/Run/Continue" trơn khớp cả nút panel lẫn câu trả lời của Agent.
    _FLOW_AGENT_APPROVE_WORD = re.compile(
        r"ph[eê]\s*duy[eệ]t|approve|allow|confirm|cho\s*ph[eé]p|[đd][oồ]ng\s*[yý]|ch[aấ]p\s*thu[aậ]n",
        re.IGNORECASE,
    )

    def _flow_agent_approve_target_refused(self, label: str, source: str = "") -> str:
        """Lý do không bấm nút ``label``; chuỗi rỗng là được bấm."""
        text = str(label or "").strip()
        if self._FLOW_AGENT_PANEL_OWN_BUTTON.search(text):
            return f"bo qua nut cua panel Tac nhan ({text[:60]})"
        if source != "dialog" and not self._FLOW_AGENT_APPROVE_WORD.search(text):
            return f"bo qua nut khong phai phe duyet ({text[:60]})"
        return ""

    async def _approve_flow_agent_generation(self, page: Any, timeout_s: float = 30.0) -> tuple[bool, str]:
        deadline = asyncio.get_running_loop().time() + max(2.0, float(timeout_s or 30.0))
        last_detail = "approval dialog not visible"
        while asyncio.get_running_loop().time() < deadline:
            for pattern in (
                re.compile(r"Phê\s*duyệt|Phe\s*duyet|Approve|Allow|Confirm", re.IGNORECASE),
                re.compile(r"^\\s*✓?\\s*Phê\\s*duyệt\\s*$|^\\s*✓?\\s*Approve\\s*$", re.IGNORECASE),
            ):
                try:
                    locator = page.get_by_role("button", name=pattern).first()
                    if await locator.count():
                        label = ""
                        try:
                            label = str(await locator.inner_text(timeout=800) or "").strip()
                        except Exception:
                            label = getattr(pattern, "pattern", "approve")
                        await locator.click(timeout=2500)
                        await asyncio.sleep(1.0)
                        return True, label or getattr(pattern, "pattern", "approve")
                except Exception:
                    continue
            try:
                result = await page.evaluate(
                    """
                    () => {
                      const visible = (el) => {
                        if (!el || !(el instanceof Element)) return false;
                        const rect = el.getBoundingClientRect();
                        if (rect.width < 24 || rect.height < 18) return false;
                        const style = window.getComputedStyle(el);
                        return style.visibility !== 'hidden'
                          && style.display !== 'none'
                          && style.opacity !== '0'
                          && rect.bottom > 0
                          && rect.top < window.innerHeight;
                      };
                      const labelFor = (el) => [
                        el.textContent || '',
                        el.getAttribute('aria-label') || '',
                        el.getAttribute('title') || '',
                        el.getAttribute('data-testid') || '',
                      ].join(' ').replace(/\\s+/g, ' ').trim();
                      const deepQuery = (selector, root = document, seen = new Set()) => {
                        const found = [];
                        const visit = (node) => {
                          if (!node || seen.has(node)) return;
                          seen.add(node);
                          try {
                            found.push(...node.querySelectorAll(selector));
                            for (const el of node.querySelectorAll('*')) {
                              if (el.shadowRoot) visit(el.shadowRoot);
                            }
                          } catch (_) {}
                        };
                        visit(root);
                        return found;
                      };
                      const bodyText = document.body?.innerText || '';
                      const plainText = (value) => String(value || '')
                        .normalize('NFD')
                        .replace(/[\\u0300-\\u036f]/g, '')
                        .replace(/[\\u0111\\u0110]/g, 'd')
                        .toLowerCase();
                      const approvalTextPattern = /Phê\\s*duyệt|Phe\\s*duyet|Approve|Allow|Confirm|Cho\\s*phép|Cho\\s*phep|Đồng\\s*ý|Dong\\s*y|Bạn\\s*có\\s*muốn|Ban\\s*co\\s*muon|0\\s*tín\\s*dụng|0\\s*tin\\s*dung/i;
                      const isNegativeLabel = (label) => {
                        const plain = plainText(label);
                        return (
                          /Từ\\s*chối|Tu\\s*choi|Reject|Cancel|Hủy|Huy|Đóng|Close|Stop|Dừng|Dung|Xoá|Xóa|Xoa|Delete|delete_forever|Cài\\s*đặt|Cai\\s*dat|Settings|tune|không\\s*cho\\s*phép|khong\\s*cho\\s*phep|new\\s*session|phiên\\s*mới|phien\\s*moi|edit_square|session\\s*history|history|instruction|article_spark|start\\s*generation|arrow_forward|ingredient|add\\s*media|upload|menu|more_vert|filter|help|account|thumb_up|thumb_down|content_copy|flag|open\\s*image|editor|collections?|storyboard|moodboard/i.test(label)
                          || /\\b(tu\\s*choi|reject|cancel|huy|close|stop|dung|xoa|delete|settings|cai\\s*dat|khong\\s*cho\\s*phep|new\\s*session|phien\\s*moi)\\b/i.test(plain)
                        ) && !/không\\s*hỏi\\s*lại|khong\\s*hoi\\s*lai|don.?t\\s+ask/i.test(label);
                      };
                      const isApproveLabel = (label) => {
                        const plain = plainText(label);
                        return (
                          /Phê\\s*duyệt|Phe\\s*duyet|Approve|Allow|Confirm|Cho\\s*phép|Cho\\s*phep|Đồng\\s*ý|Dong\\s*y|Tiếp\\s*tục|Tiep\\s*tuc|Chấp\\s*thuận|Chap\\s*thuan|Continue|\\bRun\\b|\\bStart\\b(?!\\s*(new|generation))/i.test(label)
                          || /\\b(phe\\s*duyet|approve|allow|confirm|cho\\s*phep|dong\\s*y|tiep\\s*tuc|chap\\s*thuan|continue|run|start)\\b(?!\\s*(new|generation|ing))/i.test(plain)
                        ) && !isNegativeLabel(label) && !/starting\\s+generation/i.test(label);
                      };
                      const isApprovalActionLabel = (label) => {
                        const plain = plainText(label);
                        return (
                          isApproveLabel(label)
                          || /Create|Generate|Submit|Send|Go/i.test(label)
                          || /\\b(tao|tao\\s*anh|chay|gui|create|generate|submit|send|go)\\b/i.test(plain)
                        ) && !isNegativeLabel(label);
                      };
                      const approveButtons = deepQuery('button, [role="button"]')
                        .filter(visible)
                        .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
                        .filter(({ label }) => isApproveLabel(label))
                        .sort((a, b) => (b.rect.right - a.rect.right) || (b.rect.bottom - a.rect.bottom));
                      const textCandidates = deepQuery('span, div, p, label, a, mat-label')
                        .filter(visible)
                        .map((el) => {
                          const rect = el.getBoundingClientRect();
                          const label = labelFor(el);
                          const clickable = el.closest('button, [role="button"], [tabindex], a') || el;
                          const clickRect = clickable.getBoundingClientRect();
                          return { el: clickable, rect: clickRect.width && clickRect.height ? clickRect : rect, label };
                        })
                        .filter(({ label, rect }) => label.length <= 120 && isApproveLabel(label) && rect.width <= 420 && rect.height <= 140)
                        .sort((a, b) => ((a.rect.width * a.rect.height) - (b.rect.width * b.rect.height)) || (b.rect.right - a.rect.right));
                      const bodyMentionsApproval = approvalTextPattern.test(bodyText);
                      const dialogRoots = deepQuery('[role="dialog"], [aria-modal="true"], mat-dialog-container, .mat-mdc-dialog-container, .cdk-overlay-pane')
                        .filter(visible)
                        .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
                        .sort((a, b) => (b.rect.bottom - a.rect.bottom) || (b.rect.right - a.rect.right));
                      const approvalDialogRoots = dialogRoots.filter((root) => {
                        const text = `${root.label || ''} ${root.el?.innerText || ''}`;
                        return approvalTextPattern.test(text);
                      });
                      const approvalTextRoots = bodyMentionsApproval
                        ? deepQuery('section, aside, form, div, [role="group"], [role="alertdialog"], [role="status"]')
                            .filter(visible)
                            .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el), text: el.innerText || el.textContent || '' }))
                            .filter(({ rect, text }) =>
                              approvalTextPattern.test(text)
                              && rect.width >= 180
                              && rect.height >= 70
                              && rect.width <= window.innerWidth * 0.96
                              && rect.height <= window.innerHeight * 0.9
                            )
                            .sort((a, b) => (a.rect.width * a.rect.height) - (b.rect.width * b.rect.height))
                        : [];
                      const approvalRoots = [...approvalDialogRoots, ...approvalTextRoots]
                        .filter(({ el }, index, arr) => arr.findIndex((item) => item.el === el) === index);
                      const waiting = approvalDialogRoots.length > 0 || approvalTextRoots.some((root) =>
                        deepQuery('button, [role="button"], [tabindex], a', root.el)
                          .filter(visible)
                          .some((el) => isApprovalActionLabel(labelFor(el)))
                      );
                      const dialogFallbackButtons = waiting
                        ? approvalRoots.flatMap((root) =>
                            deepQuery('button, [role="button"], [tabindex], a', root.el)
                              .filter(visible)
                              .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
                          )
                            .filter(({ label, rect }) => isApprovalActionLabel(label) && rect.width >= 24 && rect.height >= 18 && rect.width <= 360 && rect.height <= 120)
                            .sort((a, b) => (b.rect.bottom - a.rect.bottom) || (b.rect.right - a.rect.right))
                        : [];
                      const approve = approveButtons[0] || textCandidates[0] || dialogFallbackButtons[0];
                      if (!approve) {
                        return { ok: false, waiting, detail: waiting ? 'approval text visible, approve button not found' : 'approval dialog not visible' };
                      }
                      const rememberControls = deepQuery('input[type="checkbox"], input[type="radio"], [role="checkbox"], [role="radio"], label, button, [role="button"], div')
                        .filter(visible)
                        .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
                        .filter(({ label }) => /không\\s*hỏi\\s*lại|khong\\s*hoi\\s*lai|don.?t\\s+ask/i.test(label))
                        .sort((a, b) => (b.rect.width * b.rect.height) - (a.rect.width * a.rect.height));
                      const remember = rememberControls[0];
                      const approveRect = approve.el.getBoundingClientRect();
                      const rememberRect = remember?.el?.getBoundingClientRect?.();
                      approve.el.scrollIntoView({ block: 'center', inline: 'center' });
                      return {
                        ok: true,
                        approveX: approveRect.left + approveRect.width / 2,
                        approveY: approveRect.top + approveRect.height / 2,
                        rememberX: rememberRect ? rememberRect.left + Math.min(rememberRect.width - 12, Math.max(12, rememberRect.width * 0.12)) : 0,
                        rememberY: rememberRect ? rememberRect.top + rememberRect.height / 2 : 0,
                        hasRemember: Boolean(rememberRect),
                        detail: approve.label || 'approve',
                      };
                    }
                    """
                )
            except Exception as exc:
                return False, humanize_flow_error(str(exc))

            ok = bool((result or {}).get("ok")) if isinstance(result, dict) else False
            last_detail = str((result or {}).get("detail") or last_detail).strip() if isinstance(result, dict) else last_detail
            if not ok:
                await asyncio.sleep(0.5)
                continue
            try:
                if bool((result or {}).get("hasRemember")):
                    await page.mouse.click(float((result or {}).get("rememberX")), float((result or {}).get("rememberY")))
                    await asyncio.sleep(0.25)
                await page.mouse.click(float((result or {}).get("approveX")), float((result or {}).get("approveY")))
                await asyncio.sleep(1.0)
                return True, last_detail
            except Exception as exc:
                return False, humanize_flow_error(str(exc))
        return False, last_detail

    async def _click_flow_create_button(self, page: Any) -> tuple[bool, str]:
        try:
            result = await page.evaluate(
                """
                () => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 24 || rect.height < 24) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden' && style.display !== 'none' && style.opacity !== '0' && !el.disabled;
                  };
                  const buttons = [...document.querySelectorAll('button')]
                    .filter(visible)
                    .map((el) => ({
                      el,
                      rect: el.getBoundingClientRect(),
                      text: [
                        el.textContent || '',
                        el.getAttribute('aria-label') || '',
                        el.getAttribute('title') || '',
                        el.getAttribute('data-testid') || '',
                      ].join(' ').trim(),
                    }))
                    .filter(({text}) => /Create|Tạo|Tao|Send|Gửi|Gui|arrow_forward|arrow_upward|send|add_2/i.test(text));
                  const createButtons = buttons
                    .filter(({text}) => /Create|Tạo|Tao|Send|Gửi|Gui|arrow_forward|arrow_upward|send/i.test(text))
                    .sort((a, b) => (b.rect.top - a.rect.top) || (b.rect.right - a.rect.right));
                  const target = createButtons[0] || buttons.sort((a, b) => (b.rect.top - a.rect.top) || (b.rect.right - a.rect.right))[0];
                  if (!target) return {ok: false, detail: 'no visible create button'};
                  const x = target.rect.left + target.rect.width / 2;
                  const y = target.rect.top + target.rect.height / 2;
                  target.el.scrollIntoView({block: 'center', inline: 'center'});
                  return {ok: true, x, y, detail: target.text || target.el.outerHTML?.slice(0, 160) || target.el.tagName};
                }
                """
            )
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

        ok = bool((result or {}).get("ok")) if isinstance(result, dict) else False
        detail = str((result or {}).get("detail") or "").strip() if isinstance(result, dict) else ""
        if not ok:
            return False, detail
        try:
            x = float((result or {}).get("x"))
            y = float((result or {}).get("y"))
            await page.mouse.move(x, y)
            await asyncio.sleep(0.1)
            await page.mouse.click(x, y)
            await asyncio.sleep(0.7)
            return True, detail
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

    async def _flow_agent_panel_attachment_snapshot(self, page: Any) -> Dict[str, Any]:
        try:
            result = await page.evaluate(
                """
                () => {
                  const deepQuery = (selector, root = document, seen = new Set()) => {
                    const found = [];
                    const visit = (node) => {
                      if (!node || seen.has(node)) return;
                      seen.add(node);
                      try {
                        found.push(...node.querySelectorAll(selector));
                        for (const el of node.querySelectorAll('*')) {
                          if (el.shadowRoot) visit(el.shadowRoot);
                        }
                      } catch (_) {}
                    };
                    visit(root);
                    return found;
                  };
                  const visible = (el, minW = 1, minH = 1) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < minW || rect.height < minH) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0'
                      && rect.bottom > 0
                      && rect.top < window.innerHeight
                      && rect.right > 0
                      && rect.left < window.innerWidth;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('alt') || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                    el.getAttribute('data-testid') || '',
                    el.getAttribute('class') || '',
                    el.getAttribute('src') || '',
                    el.getAttribute('style') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const panels = deepQuery('aside, dialog, section, [role="dialog"], [aria-modal="true"], div')
                    .filter((el) => visible(el, 260, 160))
                    .map((el) => {
                      const rect = el.getBoundingClientRect();
                      const text = labelFor(el);
                      const rightPanel = rect.left >= window.innerWidth * 0.35
                        && rect.right >= window.innerWidth * 0.72
                        && rect.width <= window.innerWidth * 0.72;
                      const hasTextbox = Boolean(deepQuery('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]', el).length);
                      const agentish = /Flow\\s+Agent|Tác\\s*nhân|Tac\\s*nhan|Bạn\\s*muốn|Ban\\s*muon|What\\s+do\\s+you|Credit\\s+Spend\\s+Approval|Shot\\s+Brief|Design\\s+Analysis/i.test(text);
                      const score = (rightPanel ? 1400 : -900) + (hasTextbox ? 700 : 0) + (agentish ? 600 : 0) + rect.height / 20 + rect.left / 20;
                      return { el, rect, text, score };
                    })
                    .filter((item) => item.score >= 1200)
                    .sort((a, b) => b.score - a.score);
                  const panel = panels[0];
                  const fileInputsWithFiles = deepQuery('input[type="file"]')
                    .filter((el) => {
                      try {
                        const accept = `${el.getAttribute('accept') || ''} ${labelFor(el)}`;
                        return el.files && el.files.length > 0 && (!accept.trim() || /image|jpeg|jpg|png|webp|heic|media|file/i.test(accept));
                      } catch (_) {
                        return false;
                      }
                    })
                    .map((el) => {
                      try {
                        return [...el.files].map((file) => file.name || file.type || 'selected file').join(', ');
                      } catch (_) {
                        return 'selected file';
                      }
                    });
                  if (!panel) {
                    const count = fileInputsWithFiles.length;
                    return {
                      visible: count > 0,
                      count,
                      ready_count: 0,
                      busy_count: 0,
                      composer_ready_count: 0,
                      composer_busy_count: 0,
                      media_count: 0,
                      chip_count: 0,
                      file_input_count: count,
                      card_count: 0,
                      labels: fileInputsWithFiles.slice(0, 12),
                      ready_labels: [],
                      composer_ready_labels: [],
                      detail: `agent panel not found; files=${count}`,
                    };
                  }
                  const panelRect = panel.rect;
                  const textboxes = deepQuery('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]', panel.el)
                    .filter((el) => visible(el, 120, 12))
                    .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
                    .sort((a, b) => b.rect.bottom - a.rect.bottom);
                  const inputBox = textboxes[0];
                  const composerContainer = (() => {
                    if (!inputBox) return null;
                    const candidates = [];
                    let node = inputBox.el;
                    for (let depth = 0; node && node !== panel.el && depth < 14; depth += 1, node = node.parentElement) {
                      if (!(node instanceof Element)) continue;
                      const rect = node.getBoundingClientRect();
                      if (rect.width < 160 || rect.height < 32) continue;
                      if (rect.left < panelRect.left - 16 || rect.right > panelRect.right + 16) continue;
                      if (rect.bottom < window.innerHeight * 0.55 || rect.bottom < inputBox.rect.bottom - 18) continue;
                      if (rect.height >= panelRect.height - 52) continue;
                      const controls = [...node.querySelectorAll('button, [role="button"], [aria-label], [data-testid]')]
                        .filter((el) => visible(el, 18, 18)).length;
                      const score = rect.bottom / 8
                        + (controls ? 240 : 0)
                        + Math.min(rect.height, 520) / 16
                        - depth * 10
                        - Math.abs(rect.right - panelRect.right) / 18;
                      candidates.push({ el: node, rect, score });
                    }
                    candidates.sort((a, b) => b.score - a.score);
                    return candidates[0] || null;
                  })();
                  const composerRect = (() => {
                    if (composerContainer) return composerContainer.rect;
                    if (!inputBox) {
                      return {
                        left: panelRect.left,
                        right: panelRect.right,
                        top: Math.max(panelRect.top + 44, panelRect.bottom - 280),
                        bottom: panelRect.bottom + 12,
                      };
                    }
                    const topPad = Math.min(340, Math.max(160, panelRect.height * 0.34));
                    return {
                      left: panelRect.left,
                      right: panelRect.right,
                      top: Math.max(panelRect.top + 44, inputBox.rect.top - topPad),
                      bottom: panelRect.bottom + 12,
                    };
                  })();
                  const composerTop = inputBox ? Math.max(panelRect.top + 44, inputBox.rect.top - Math.max(260, panelRect.height * 0.62)) : panelRect.top + 44;
                  const composerBottom = panelRect.bottom + 12;
                  const insideTextbox = (el) => textboxes.some((box) => box.el === el || box.el.contains(el));
                  const inCurrentComposer = (el) => {
                    const rect = el.getBoundingClientRect();
                    return rect.top >= composerRect.top - 8
                      && rect.bottom <= composerRect.bottom + 8
                      && rect.left >= composerRect.left - 8
                      && rect.right <= composerRect.right + 8;
                  };
                  const inPanelAttachmentArea = (el) => {
                    const rect = el.getBoundingClientRect();
                    return rect.top >= composerTop
                      && rect.bottom <= composerBottom
                      && rect.left >= panelRect.left - 8
                      && rect.right <= panelRect.right + 8;
                  };
                  const mediaCandidates = deepQuery('img, canvas, video, [role="img"], [style*="background-image"]', panel.el);
                  const media = mediaCandidates
                    .filter((el) => visible(el, 24, 24))
                    .filter((el) => inPanelAttachmentArea(el) && !insideTextbox(el))
                    .filter((el) => {
                      const rect = el.getBoundingClientRect();
                      return rect.width * rect.height >= 900 && !(rect.width <= 38 && rect.height <= 38);
                    })
                    .map((el) => labelFor(el).slice(0, 80));
                  const chips = deepQuery('span, div, p, a, button, [role="button"]', panel.el)
                    .filter((el) => visible(el, 24, 12))
                    .filter((el) => inPanelAttachmentArea(el) && !insideTextbox(el))
                    .map((el) => labelFor(el))
                    .filter((label) => label.length > 0 && label.length <= 180)
                    .filter((label) => /\\.jpe?g|\\.png|\\.webp|\\.heic|erp-|source|upload(ed)?|attached|attachment|thumbnail|preview|file|media|ảnh|anh|image/i.test(label))
                    .slice(0, 12);
                  const attachmentCards = deepQuery('[data-testid], [aria-label], [title], [class]', panel.el)
                    .filter((el) => visible(el, 24, 18))
                    .filter((el) => inPanelAttachmentArea(el) && !insideTextbox(el))
                    .map((el) => {
                      const rect = el.getBoundingClientRect();
                      return { label: labelFor(el), area: rect.width * rect.height };
                    })
                    .filter((item) => item.area >= 900 && item.label.length > 0 && item.label.length <= 220)
                    .filter((item) => /upload|attached|attachment|thumbnail|preview|file|media|image|photo|picture|remove.*image|xoa.*anh|ảnh|anh/i.test(item.label))
                    .map((item) => item.label.slice(0, 80))
                    .slice(0, 12);
                  const busyLabel = (label) => /uploading|loading|progress|spinner|pending|processing|dang\\s*tai|dang\\s*upload|tai\\s*len|cho\\s*tai|đang\\s*tải|đang\\s+upload|đang\\s+xử\\s*lý|ch\u1edd\\s*t\u1ea3i/i.test(label || '');
                  const busyIndicators = deepQuery('[role="progressbar"], progress, mat-spinner, [class*="spinner" i], [class*="loading" i], [aria-busy="true"]', panel.el)
                    .filter((el) => visible(el, 12, 12))
                    .filter((el) => inPanelAttachmentArea(el) && !insideTextbox(el))
                    .map((el) => labelFor(el).slice(0, 80) || el.tagName.toLowerCase());
                  const composerMedia = mediaCandidates
                    .filter((el) => visible(el, 24, 24))
                    .filter((el) => inCurrentComposer(el))
                    .filter((el) => {
                      const rect = el.getBoundingClientRect();
                      return rect.width * rect.height >= 900 && !(rect.width <= 38 && rect.height <= 38);
                    })
                    .map((el) => labelFor(el).slice(0, 80) || 'composer image preview');
                  const composerChips = deepQuery('span, div, p, a, button, [role="button"]', panel.el)
                    .filter((el) => visible(el, 24, 12))
                    .filter((el) => inCurrentComposer(el))
                    .map((el) => labelFor(el))
                    .filter((label) => label.length > 0 && label.length <= 220)
                    .filter((label) => /\\.jpe?g|\\.png|\\.webp|\\.heic|erp-|source|upload(ed)?|attached|attachment|thumbnail|preview|file|media|ảnh|anh|image/i.test(label));
                  const composerCards = deepQuery('[data-testid], [aria-label], [title], [class]', panel.el)
                    .filter((el) => visible(el, 24, 18))
                    .filter((el) => inCurrentComposer(el))
                    .map((el) => {
                      const rect = el.getBoundingClientRect();
                      return { label: labelFor(el), area: rect.width * rect.height };
                    })
                    .filter((item) => item.area >= 900 && item.label.length > 0 && item.label.length <= 220)
                    .filter((item) => /upload|attached|attachment|thumbnail|preview|file|media|image|photo|picture|remove.*image|xoa.*anh|ảnh|anh/i.test(item.label))
                    .map((item) => item.label.slice(0, 80));
                  const composerBusyIndicators = deepQuery('[role="progressbar"], progress, mat-spinner, [class*="spinner" i], [class*="loading" i], [aria-busy="true"]', panel.el)
                    .filter((el) => visible(el, 12, 12))
                    .filter((el) => inCurrentComposer(el))
                    .map((el) => labelFor(el).slice(0, 80) || el.tagName.toLowerCase());
                  const readyChips = chips.filter((label) => !busyLabel(label));
                  const readyCards = attachmentCards.filter((label) => !busyLabel(label));
                  const composerReadyChips = composerChips.filter((label) => !busyLabel(label));
                  const composerReadyCards = composerCards.filter((label) => !busyLabel(label));
                  const readyLabels = [...media, ...readyChips, ...readyCards]
                    .filter((label, index, arr) => label && arr.indexOf(label) === index)
                    .slice(0, 12);
                  const composerReadyLabels = [...composerMedia, ...composerReadyChips, ...composerReadyCards]
                    .filter((label, index, arr) => label && arr.indexOf(label) === index)
                    .slice(0, 12);
                  const labels = [...readyLabels, ...busyIndicators, ...fileInputsWithFiles]
                    .filter((label, index, arr) => label && arr.indexOf(label) === index)
                    .slice(0, 12);
                  const readyCount = media.length + readyChips.length + readyCards.length;
                  const busyCount = busyIndicators.length
                    + chips.filter((label) => busyLabel(label)).length
                    + attachmentCards.filter((label) => busyLabel(label)).length;
                  const composerReadyCount = composerMedia.length + composerReadyChips.length + composerReadyCards.length;
                  const composerBusyCount = composerBusyIndicators.length
                    + composerChips.filter((label) => busyLabel(label)).length
                    + composerCards.filter((label) => busyLabel(label)).length;
                  const count = readyCount + busyCount + fileInputsWithFiles.length;
                  return {
                    visible: true,
                    count,
                    ready_count: readyCount,
                    busy_count: busyCount,
                    composer_ready_count: composerReadyCount,
                    composer_busy_count: composerBusyCount,
                    media_count: media.length,
                    chip_count: readyChips.length,
                    file_input_count: fileInputsWithFiles.length,
                    card_count: readyCards.length,
                    labels,
                    ready_labels: readyLabels,
                    composer_ready_labels: composerReadyLabels,
                    detail: `attachments=${count} ready=${readyCount} busy=${busyCount} composerReady=${composerReadyCount} composerBusy=${composerBusyCount} media=${media.length} chips=${readyChips.length} files=${fileInputsWithFiles.length} cards=${readyCards.length} allMedia=${mediaCandidates.length}`,
                  };
                }
                """
            )
        except Exception as exc:
            return {
                "visible": False,
                "count": 0,
                "ready_count": 0,
                "busy_count": 0,
                "composer_ready_count": 0,
                "composer_busy_count": 0,
                "media_count": 0,
                "chip_count": 0,
                "file_input_count": 0,
                "card_count": 0,
                "ready_labels": [],
                "composer_ready_labels": [],
                "detail": humanize_flow_error(str(exc)),
            }
        if not isinstance(result, dict):
            result = {
                "visible": False,
                "count": 0,
                "ready_count": 0,
                "busy_count": 0,
                "composer_ready_count": 0,
                "composer_busy_count": 0,
                "media_count": 0,
                "chip_count": 0,
                "file_input_count": 0,
                "card_count": 0,
                "ready_labels": [],
                "composer_ready_labels": [],
                "detail": "attachment snapshot unavailable",
            }
        try:
            chip_state = await page.evaluate(self.FLOW_AGENT_COMPOSER_CHIP_JS)
        except Exception as exc:
            chip_state = {"composer_chip_count": 0, "composer_chip_labels": [], "composer_chip_detail": humanize_flow_error(str(exc))[:80]}
        chip_state = chip_state if isinstance(chip_state, dict) else {}
        try:
            result["composer_chip_count"] = max(0, int(chip_state.get("composer_chip_count") or 0))
        except Exception:
            result["composer_chip_count"] = 0
        result["composer_chip_labels"] = [str(label) for label in (chip_state.get("composer_chip_labels") or []) if label][:8]
        result["composer_chip_detail"] = str(chip_state.get("composer_chip_detail") or "")[:120]
        result["detail"] = f"{result.get('detail') or ''} {result['composer_chip_detail']}".strip()
        return result

    FLOW_AGENT_COMPOSER_CHIP_JS = """
        /* composer-chip-probe */
        () => {
          const deepQuery = (selector, root = document, seen = new Set()) => {
            const found = [];
            const visit = (node) => {
              if (!node || seen.has(node)) return;
              seen.add(node);
              try {
                found.push(...node.querySelectorAll(selector));
                for (const el of node.querySelectorAll('*')) {
                  if (el.shadowRoot) visit(el.shadowRoot);
                }
              } catch (_) {}
            };
            visit(root);
            return found;
          };
          const visible = (el, minW = 20, minH = 20) => {
            if (!el || !(el instanceof Element)) return false;
            const rect = el.getBoundingClientRect();
            if (rect.width < minW || rect.height < minH) return false;
            const style = window.getComputedStyle(el);
            return style.visibility !== 'hidden'
              && style.display !== 'none'
              && style.opacity !== '0'
              && rect.bottom > 0
              && rect.top < window.innerHeight;
          };
          const labelFor = (el) => [
            el.textContent || '',
            el.getAttribute('aria-label') || '',
            el.getAttribute('title') || '',
            el.getAttribute('alt') || '',
            el.getAttribute('data-testid') || '',
          ].join(' ').replace(/\\s+/g, ' ').trim();
          const textboxes = deepQuery('textarea, [contenteditable="true"], [role="textbox"]')
            .filter((el) => visible(el, 120, 12))
            .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
            .filter((item) => item.rect.left >= window.innerWidth * 0.35)
            .sort((a, b) => b.rect.bottom - a.rect.bottom);
          const ingredientChips = deepQuery('button, [role="button"]')
            .filter((el) => visible(el, 20, 20))
            .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
            .filter((item) => item.rect.left >= window.innerWidth * 0.35)
            .filter((item) => /ingredient|nguyên\\s*liệu|nguyen\\s*lieu/i.test(item.label)
              && /cancel|close|remove|xóa|xoa|delete|bỏ|huỷ|huy/i.test(item.label)
              && !/add\\s*ingredient|thêm|them\\b/i.test(item.label));
          // Ingredient chips sit at the top of the composer; with a long prompt they scroll far above
          // the viewport, so count them by their markup instead of by visibility.
          const chipLike = deepQuery('.chip-container, [class*="chip"], [class*="ingredient"]')
            .filter((el) => el instanceof Element)
            .map((el) => ({
              el,
              rect: el.getBoundingClientRect(),
              label: `${labelFor(el)} ${[...el.querySelectorAll('img')].map((img) => img.getAttribute('alt') || '').join(' ')}`.replace(/\\s+/g, ' ').trim(),
            }))
            .filter((item) => item.rect.width >= 16 && item.rect.height >= 16)
            .filter((item) => {
              const style = window.getComputedStyle(item.el);
              return style.display !== 'none' && style.visibility !== 'hidden';
            })
            .filter((item) => item.rect.left >= window.innerWidth * 0.35)
            .filter((item) => !item.el.closest('[role="dialog"], [role="listbox"], [role="menu"], [aria-modal="true"]'))
            .filter((item) => /ingredient|nguyên\\s*liệu|nguyen\\s*lieu/i.test(item.label))
            .filter((item) => !/add\\s*ingredient|thêm\\s*nguyên|them\\s*nguyen|prompt\\s*box/i.test(item.label));
          const explicitChips = chipLike.filter((item) => !chipLike.some((other) => other.el !== item.el && other.el.contains(item.el)));
          const box = textboxes[0];
          if (!box) {
            return {
              composer_chip_count: Math.max(ingredientChips.length, explicitChips.length),
              composer_chip_labels: [...ingredientChips, ...explicitChips].map((item) => item.label.slice(0, 80)).slice(0, 8),
              composer_chip_detail: `composerChips=${Math.max(ingredientChips.length, explicitChips.length)} explicitChips=${explicitChips.length} (no composer textbox)`,
            };
          }
          let container = box.el.parentElement;
          let found = null;
          for (let depth = 0; container && depth < 12; depth += 1, container = container.parentElement) {
            const rect = container.getBoundingClientRect();
            if (rect.width < 160 || rect.width > window.innerWidth * 0.6) break;
            const hasToolbar = [...container.querySelectorAll('button, [role="button"]')]
              .some((btn) => /ingredient|start\\s*generation|arrow_forward|send|gửi|tune|settings/i.test(labelFor(btn)));
            if (hasToolbar) {
              found = container;
              break;
            }
          }
          if (!found) {
            return {
              composer_chip_count: Math.max(ingredientChips.length, explicitChips.length),
              composer_chip_labels: [...ingredientChips, ...explicitChips].map((item) => item.label.slice(0, 80)).slice(0, 8),
              composer_chip_detail: `composerChips=${Math.max(ingredientChips.length, explicitChips.length)} explicitChips=${explicitChips.length} (no composer container)`,
            };
          }
          const containerRect = found.getBoundingClientRect();
          const nodes = [...found.querySelectorAll('*')]
            .filter((el) => el !== box.el && !box.el.contains(el))
            .filter((el) => visible(el, 20, 20))
            .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
            .filter((item) => item.rect.bottom <= box.rect.top + 6 && item.rect.top >= containerRect.top - 4)
            .filter((item) => item.rect.width <= 360 && item.rect.height <= 220);
          const nodeSet = new Set(nodes.map((item) => item.el));
          const topLevel = nodes.filter((item) => !nodeSet.has(item.el.parentElement));
          const removeButtons = nodes.filter((item) => /close|remove|xóa|xoa|delete|clear|bỏ|huỷ|huy|cancel/i.test(item.label) && item.el.closest('button, [role="button"]'));
          const media = nodes.filter((item) => item.el.matches('img, canvas, video, [style*="background-image"]') || /(^|\\s)image(\\s|$)/i.test(item.label));
          const labels = [...topLevel.map((item) => item.label.slice(0, 80)), ...ingredientChips.map((item) => item.label.slice(0, 80)), ...explicitChips.map((item) => item.label.slice(0, 80))]
            .filter((label, index, arr) => label && arr.indexOf(label) === index)
            .slice(0, 8);
          const chipCount = Math.max(topLevel.length, ingredientChips.length, explicitChips.length);
          return {
            composer_chip_count: chipCount,
            composer_chip_remove_count: removeButtons.length,
            composer_chip_media_count: media.length,
            composer_chip_labels: labels,
            composer_chip_detail: `composerChips=${chipCount} chipRemove=${removeButtons.length} chipMedia=${media.length} ingredientChips=${ingredientChips.length} explicitChips=${explicitChips.length}`,
          };
        }
    """

    def _flow_agent_attachment_ready_count(self, snapshot: Dict[str, Any]) -> int:
        if not isinstance(snapshot, dict):
            return 0
        if "ready_count" in snapshot:
            try:
                return max(0, int(snapshot.get("ready_count") or 0))
            except Exception:
                return 0
        try:
            total = int(snapshot.get("count") or 0)
            file_inputs = int(snapshot.get("file_input_count") or 0)
            busy = int(snapshot.get("busy_count") or 0)
            return max(0, total - file_inputs - busy)
        except Exception:
            return 0

    def _flow_agent_attachment_label_signature(self, snapshot: Dict[str, Any]) -> tuple[str, ...]:
        if not isinstance(snapshot, dict):
            return ()
        labels = snapshot.get("ready_labels")
        if not isinstance(labels, list):
            labels = snapshot.get("labels")
        if not isinstance(labels, list):
            return ()
        return tuple(sorted({str(label or "").strip() for label in labels if str(label or "").strip()}))

    def _flow_agent_attachment_composer_ready_count(self, snapshot: Dict[str, Any]) -> int:
        if not isinstance(snapshot, dict):
            return 0
        try:
            return max(0, int(snapshot.get("composer_ready_count") or 0))
        except Exception:
            return 0

    def _flow_agent_attachment_composer_label_signature(self, snapshot: Dict[str, Any]) -> tuple[str, ...]:
        if not isinstance(snapshot, dict):
            return ()
        labels = snapshot.get("composer_ready_labels")
        if not isinstance(labels, list):
            return ()
        return tuple(sorted({str(label or "").strip() for label in labels if str(label or "").strip()}))

    #: Câu mà ``_chon_anh_trong_menu`` để lại khi nó bấm trúng ô mang đúng tên
    #: ảnh ERP **và** bấm được nút chốt của bảng chọn.

    FLOW_DAU_DA_CHOT = "trong bang chon nguyen lieu"

    def _bang_chon_da_chot(self, attach_detail: str) -> bool:
        """Đường bảng chọn đã chốt xong hay chưa.

        Chốt bằng bảng chọn là hai cú bấm có thật: một vào ô mang đúng tên
        ảnh ERP, một vào nút ``Add to prompt``.  Thả file mù thì không có
        cú nào — nên chỗ này phân biệt hai đường, không phải nới cả hai.
        """
        return self.FLOW_DAU_DA_CHOT in str(attach_detail or "")

    async def _wait_for_flow_agent_source_attachment(
        self,
        page: Any,
        before: Dict[str, Any] | None = None,
        *,
        timeout_s: float = 20.0,
        accept_stable_ready_after_attach: bool = False,
        source_file_name: str = "",
    ) -> tuple[bool, str]:
        before = before if isinstance(before, dict) else {}
        name_tokens = self._flow_agent_source_name_tokens(source_file_name)
        try:
            before_chips = max(0, int(before.get("composer_chip_count") or 0))
        except Exception:
            before_chips = 0
        before_count = self._flow_agent_attachment_ready_count(before)
        before_labels = self._flow_agent_attachment_label_signature(before)
        before_composer_count = self._flow_agent_attachment_composer_ready_count(before)
        before_composer_labels = self._flow_agent_attachment_composer_label_signature(before)
        deadline = asyncio.get_running_loop().time() + max(1.0, float(timeout_s or 20.0))
        last_snapshot: Dict[str, Any] = before
        while asyncio.get_running_loop().time() < deadline:
            last_snapshot = await self._flow_agent_panel_attachment_snapshot(page)
            current_count = self._flow_agent_attachment_ready_count(last_snapshot)
            current_labels = self._flow_agent_attachment_label_signature(last_snapshot)
            current_composer_count = self._flow_agent_attachment_composer_ready_count(last_snapshot)
            current_composer_labels = self._flow_agent_attachment_composer_label_signature(last_snapshot)
            try:
                busy_count = int(last_snapshot.get("busy_count") or 0)
            except Exception:
                busy_count = 0
            try:
                composer_busy_count = int(last_snapshot.get("composer_busy_count") or 0)
            except Exception:
                composer_busy_count = 0
            try:
                current_chips = max(0, int(last_snapshot.get("composer_chip_count") or 0))
            except Exception:
                current_chips = 0
            if current_chips > before_chips and busy_count <= 0 and composer_busy_count <= 0:
                return True, f"composer chip added {before_chips}->{current_chips}; {last_snapshot.get('detail') or ''}"
            if name_tokens and busy_count <= 0 and composer_busy_count <= 0:
                matched_label = self._flow_agent_snapshot_label_matching(last_snapshot, name_tokens)
                if matched_label:
                    return True, f"source file visible in agent panel ({matched_label[:60]}); {last_snapshot.get('detail') or ''}"
            if last_snapshot.get("visible") and current_composer_count > 0 and composer_busy_count <= 0:
                if current_composer_count > before_composer_count:
                    return True, f"composer attachment ready {before_composer_count}->{current_composer_count}; {last_snapshot.get('detail') or ''}"
                if before_composer_count > 0 and current_composer_labels and current_composer_labels != before_composer_labels:
                    return True, f"composer attachment changed after attach {before_composer_count}->{current_composer_count}; {last_snapshot.get('detail') or ''}"
            if last_snapshot.get("visible") and current_count > 0 and busy_count <= 0:
                if current_count > before_count:
                    return True, f"new ready attachment visible {before_count}->{current_count}; {last_snapshot.get('detail') or ''}"
                if before_count > 0 and current_labels and current_labels != before_labels:
                    return True, f"ready attachment changed after attach {before_count}->{current_count}; {last_snapshot.get('detail') or ''}"
                if accept_stable_ready_after_attach and current_count >= before_count:
                    return True, f"ready attachment stable after file attach {before_count}->{current_count}; {last_snapshot.get('detail') or ''}"
            await asyncio.sleep(0.5)
        current_count = self._flow_agent_attachment_ready_count(last_snapshot)
        current_composer_count = self._flow_agent_attachment_composer_ready_count(last_snapshot)
        return False, f"no new ready attachment visible {before_count}->{current_count}, composer {before_composer_count}->{current_composer_count}; {last_snapshot.get('detail') or ''}"

    async def _wait_for_flow_agent_upload_ready(
        self,
        interceptor: Any,
        start_index: int,
        *,
        timeout_s: float = 45.0,
    ) -> tuple[bool, str]:
        deadline = asyncio.get_running_loop().time() + max(2.0, float(timeout_s or 45.0))
        last_detail = "waiting for Flow Agent source upload"
        while asyncio.get_running_loop().time() < deadline:
            calls = list(getattr(interceptor, "_calls", []) or [])[max(0, int(start_index or 0)) :]
            upload_calls = [
                call
                for call in calls
                if any(token in str(getattr(call, "tail", "") or "").lower() for token in ("uploadimage", "uploadmedia"))
            ]
            for call in reversed(upload_calls):
                tail = str(getattr(call, "tail", "") or "uploadImage")
                response = getattr(call, "resp", None)
                if response is None:
                    last_detail = f"{tail} still uploading"
                    continue
                status = int(getattr(call, "status", 0) or 0)
                if status not in (200, 201):
                    return False, f"{tail} failed [{status or 'unknown'}]"
                await asyncio.sleep(1.5)
                return True, f"{tail} completed [{status}]"
            await asyncio.sleep(0.25)
        # Kể tên những lời gọi đã đi qua trong lúc chờ.  Google đổi tên endpoint
        # là hỏng cả ngày, mà câu "không thấy uploadImage" thì không nói được
        # tên mới là gì — có danh sách này thì đọc log một lần là ra.
        da_thay = []
        for call in list(getattr(interceptor, "_calls", []) or [])[max(0, int(start_index or 0)) :]:
            tail = str(getattr(call, "tail", "") or "").strip()
            if tail and tail not in da_thay:
                da_thay.append(tail)
        ke_ten = ", ".join(da_thay[:12]) if da_thay else "khong co loi goi nao"
        return False, (
            f"{last_detail}; no completed uploadImage response in {int(timeout_s)}s"
            f" (da thay: {ke_ten})"
        )

    #: Mục trong menu "Add media" dẫn tới hộp chọn file của máy.  Flow in tên
    #: icon Material thẳng vào textContent, nên ``upload`` bắt được cả
    #: ``file_upload`` lẫn ``drive_folder_upload``.
    #: ``upload(?!ing)``: ô ảnh trên lưới đang tải mang nhãn ``Uploading`` — job
    #: ``69bfdc4f`` đọc ra ``Uploading\nerp-69bfdc4f-1.png\nImage`` rồi tưởng đó
    #: là mục menu, bấm vào không ra hộp chọn file nào.

    FLOW_AGENT_ADD_CONTROL_JS = """
        /* agent-add-control */
        () => {
          const deepQuery = (selector, root = document, seen = new Set()) => {
            const found = [];
            const visit = (node) => {
              if (!node || seen.has(node)) return;
              seen.add(node);
              try {
                found.push(...node.querySelectorAll(selector));
                for (const el of node.querySelectorAll('*')) {
                  if (el.shadowRoot) visit(el.shadowRoot);
                }
              } catch (_) {}
            };
            visit(root);
            return found;
          };
          const visible = (el, minW = 14, minH = 14) => {
            if (!el || !(el instanceof Element)) return false;
            const rect = el.getBoundingClientRect();
            if (rect.width < minW || rect.height < minH) return false;
            const style = window.getComputedStyle(el);
            return style.visibility !== 'hidden'
              && style.display !== 'none'
              && style.opacity !== '0'
              && rect.bottom > 0
              && rect.top < window.innerHeight
              && rect.right > 0
              && rect.left < window.innerWidth;
          };
          const labelFor = (el) => [
            el.textContent || '',
            el.getAttribute('aria-label') || '',
            el.getAttribute('title') || '',
            el.getAttribute('data-testid') || '',
            el.getAttribute('placeholder') || '',
          ].join(' ').replace(/\\s+/g, ' ').trim();
          const textboxes = deepQuery('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]')
            .filter((el) => visible(el, 120, 12))
            .map((el) => {
              const rect = el.getBoundingClientRect();
              const label = labelFor(el);
              const rightPanel = rect.left >= window.innerWidth * 0.35;
              const agentish = /What\\s+do\\s+you\\s+want|Bạn\\s*muốn|Ban\\s*muon|prompt|create|tạo/i.test(label);
              const searchish = /search|tìm\\s*kiếm|tim\\s*kiem|editable\\s*text/i.test(label);
              const score = (rightPanel ? 1000 : 0) + (agentish ? 600 : 0) - (searchish ? 1500 : 0) + rect.bottom / 10;
              return { el, rect, label, score };
            })
            .sort((a, b) => b.score - a.score);
          const box = textboxes[0] || null;
          const boxRect = box
            ? box.rect
            : { left: window.innerWidth * 0.5, top: window.innerHeight * 0.6, right: window.innerWidth, bottom: window.innerHeight, width: window.innerWidth * 0.5 };
          // A long prompt makes the editor tens of thousands of px tall; only its visible slice matters.
          const visTop = Math.max(0, boxRect.top);
          const visBottom = Math.min(window.innerHeight, boxRect.bottom);
          const boxMidY = (visTop + visBottom) / 2;
          const toolbarish = /ingredient|start\\s*generation|arrow_forward|send|gửi|tune|settings/i;
          let container = null;
          if (box) {
            let node = box.el.parentElement;
            for (let depth = 0; node && depth < 12; depth += 1, node = node.parentElement) {
              const rect = node.getBoundingClientRect();
              if (rect.width < 160 || rect.width > window.innerWidth * 0.6) break;
              const hasToolbar = [...node.querySelectorAll('button, [role="button"]')].some((btn) => toolbarish.test(labelFor(btn)));
              if (hasToolbar) {
                container = node;
                break;
              }
            }
          }
          const excluded = /send|arrow_forward|arrow_upward|start\\s*generation|gửi|gui\\b|settings|tune|close|history|instruction|article_spark|new\\s*session|edit_square|filter|help|more_vert|account|cancel|delete|remove|xóa|xoa\\b|đóng|dong\\b|clear\\s*prompt/i;
          const suggestionish = /edit\\s+an?\\s+image|create\\s+a\\s+few|versions?\\s+of|moodboard|storyboard|organi[sz]e|learn\\s+about|brainstorm|develop|show\\s+me|keyboard|shortcut|omni|collections?|generation\\s+costs?/i;
          const strong = /ingredient|add\\s*media|upload|tải\\s*lên|tai\\s*len|đính\\s*kèm|dinh\\s*kem|thêm\\s*ảnh|them\\s*anh|attach|add_photo|photo_library|hình\\s*ảnh|hinh\\s*anh|nguyên\\s*liệu|nguyen\\s*lieu/i;
          const iconAdd = /(^|\\s)(\\+|add|add_2|add_circle|add_box|attach_file|attachment|upload|upload_file|photo|image|media)(\\s|$)/i;
          // A top notice banner or a long prompt can push the composer toolbar just below the fold.
          const belowFold = (el) => {
            if (!el || !(el instanceof Element)) return false;
            const rect = el.getBoundingClientRect();
            if (rect.width < 14 || rect.height < 14) return false;
            const style = window.getComputedStyle(el);
            return style.visibility !== 'hidden'
              && style.display !== 'none'
              && style.opacity !== '0'
              && rect.top >= window.innerHeight - 2
              && rect.top < window.innerHeight + 260
              && rect.right > 0
              && rect.left < window.innerWidth;
          };
          const headerLimit = Math.min(170, window.innerHeight * 0.2);
          const scored = deepQuery('button, [role="button"], label')
            .filter((el) => visible(el, 14, 14) || belowFold(el))
            .map((el) => {
              const rect = el.getBoundingClientRect();
              const label = labelFor(el);
              const midY = (rect.top + rect.bottom) / 2;
              const compact = rect.width <= 96 && rect.height <= 96;
              const inContainer = container ? container.contains(el) : rect.top >= window.innerHeight * 0.3;
              const headerish = !inContainer && rect.top < headerLimit;
              const nearBox = rect.bottom >= visTop - 140
                && rect.top <= visBottom + 140
                && rect.right >= boxRect.left - 200
                && rect.left <= boxRect.right + 60;
              const leftish = rect.left <= boxRect.left + Math.max(200, boxRect.width * 0.4);
              const relevant = strong.test(label) || iconAdd.test(label);
              const distance = Math.min(Math.abs(midY - boxMidY), Math.abs(midY - visBottom), Math.abs(midY - visTop));
              const score = (inContainer ? 1500 : -1500)
                + (nearBox ? 1000 : 0)
                + (strong.test(label) ? 900 : 0)
                + (iconAdd.test(label) ? 400 : 0)
                + (leftish ? 150 : 0)
                - distance / 2
                - (excluded.test(label) ? 5000 : 0)
                - (suggestionish.test(label) ? 5000 : 0)
                - (compact ? 0 : 5000)
                - (relevant ? 0 : 5000)
                - (label.length > 140 ? 800 : 0);
              return { el, rect, label, score, headerish };
            })
            .filter((item) => item.score > 500)
            .sort((a, b) => b.score - a.score);
          const toPoint = (item) => {
            let rect = item.rect;
            if (rect.top + rect.height / 2 >= window.innerHeight - 2) {
              try { item.el.scrollIntoView({ block: 'end', inline: 'nearest' }); } catch (_) {}
              rect = item.el.getBoundingClientRect();
            }
            return {
              x: rect.left + rect.width / 2,
              y: rect.top + rect.height / 2,
              label: item.label.slice(0, 120),
              score: Math.round(item.score),
              offscreen: rect.top + rect.height / 2 >= window.innerHeight - 2 || rect.bottom <= 0,
            };
          };
          const candidates = scored.filter((item) => !item.headerish).slice(0, 4).map(toPoint);
          // The page-header "Add media" menu uploads into the project library, not the prompt: last resort only.
          const fallbackCandidates = scored.filter((item) => item.headerish).slice(0, 2).map(toPoint);
          return {
            ok: candidates.length > 0,
            candidates,
            fallback_candidates: fallbackCandidates,
            composer: box ? { x: boxRect.left + boxRect.width / 2, y: boxMidY, label: box.label.slice(0, 80) } : null,
            detail: candidates.length
              ? `add control: ${candidates[0].label}${candidates[0].offscreen ? ' (below the fold)' : ''}`
              : (box ? `no agent add/upload control near ${box.label.slice(0, 60)}` : 'no agent add/upload control (no composer)'),
          };
        }
    """

    FLOW_AGENT_UPLOAD_MENU_JS = """
        () => {
          const deepQuery = (selector, root = document, seen = new Set()) => {
            const found = [];
            const visit = (node) => {
              if (!node || seen.has(node)) return;
              seen.add(node);
              try {
                found.push(...node.querySelectorAll(selector));
                for (const el of node.querySelectorAll('*')) {
                  if (el.shadowRoot) visit(el.shadowRoot);
                }
              } catch (_) {}
            };
            visit(root);
            return found;
          };
          const visible = (el, minW = 24, minH = 16) => {
            if (!el || !(el instanceof Element)) return false;
            const rect = el.getBoundingClientRect();
            if (rect.width < minW || rect.height < minH) return false;
            const style = window.getComputedStyle(el);
            return style.visibility !== 'hidden'
              && style.display !== 'none'
              && style.opacity !== '0'
              && rect.bottom > 0
              && rect.top < window.innerHeight;
          };
          const labelFor = (el) => [
            el.textContent || '',
            el.getAttribute('aria-label') || '',
            el.getAttribute('title') || '',
            el.getAttribute('data-testid') || '',
          ].join(' ').replace(/\\s+/g, ' ').trim();
          const uploadish = /upload|tải\\s*lên|tai\\s*len|từ\\s*máy|tu\\s*may|computer|device|thiết\\s*bị|thiet\\s*bi|browse|choose\\s*file|chọn\\s*tệp|chon\\s*tep|local|file|drive|photos|ảnh|anh\\b|image|media/i;
          const preferred = /upload|tải\\s*lên|tai\\s*len|computer|device|máy\\s*tính|may\\s*tinh|browse|choose|chọn|chon\\b|local|file/i;
          const excluded = /close|cancel|đóng|dong\\b|hủy|huy\\b|send|arrow_forward|settings|tune|history|instruction|search|tìm|tim\\s*kiem|edit\\s+an?\\s+image|create\\s+a\\s+few|versions?\\s+of|moodboard|storyboard|organi[sz]e|learn\\s+about|brainstorm|develop|show\\s+me|keyboard|shortcut|omni|collections?|generation\\s+costs?|open\\s+image|editor|add\\s*media\\s*menu/i;
          const seenKeys = new Set();
          const items = deepQuery('[role="menuitem"], [role="option"], [role="menu"] button, [role="menu"] [role="button"], [role="listbox"] [role="option"], [role="dialog"] button, li, button, [role="button"], label, a')
            .filter((el) => visible(el))
            .map((el) => {
              const rect = el.getBoundingClientRect();
              return { rect, label: labelFor(el), role: el.getAttribute('role') || el.tagName.toLowerCase() };
            })
            .filter((item) => item.label.length > 0 && item.label.length <= 160)
            .filter((item) => uploadish.test(item.label) && preferred.test(item.label) && !excluded.test(item.label))
            .filter((item) => /menuitem|option/.test(item.role) || (item.rect.width <= 240 && item.rect.height <= 64))
            .filter((item) => /menuitem|option/.test(item.role) || item.rect.top >= window.innerHeight * 0.12)
            .map((item) => ({
              ...item,
              score: (preferred.test(item.label) ? 500 : 0)
                + (/menuitem|option/.test(item.role) ? 300 : 0)
                - (item.rect.width > window.innerWidth * 0.6 ? 900 : 0),
            }))
            .filter((item) => {
              const key = `${item.label}|${Math.round(item.rect.left)}|${Math.round(item.rect.top)}`;
              if (seenKeys.has(key)) return false;
              seenKeys.add(key);
              return true;
            })
            .sort((a, b) => b.score - a.score)
            .slice(0, 5)
            .map((item) => ({
              x: item.rect.left + item.rect.width / 2,
              y: item.rect.top + item.rect.height / 2,
              label: item.label.slice(0, 120),
              role: item.role,
            }));
          return { items };
        }
    """

    FLOW_AGENT_DROP_FILE_JS = """
        ({ b64, name, mime, x, y }) => {
          const deepQuery = (selector, root = document, seen = new Set()) => {
            const found = [];
            const visit = (node) => {
              if (!node || seen.has(node)) return;
              seen.add(node);
              try {
                found.push(...node.querySelectorAll(selector));
                for (const el of node.querySelectorAll('*')) {
                  if (el.shadowRoot) visit(el.shadowRoot);
                }
              } catch (_) {}
            };
            visit(root);
            return found;
          };
          const visible = (el) => {
            if (!el || !(el instanceof Element)) return false;
            const rect = el.getBoundingClientRect();
            if (rect.width < 120 || rect.height < 12) return false;
            const style = window.getComputedStyle(el);
            return style.visibility !== 'hidden' && style.display !== 'none' && style.opacity !== '0';
          };
          let target = null;
          if (x > 0 && y > 0) target = document.elementFromPoint(x, y);
          if (!target) {
            const boxes = deepQuery('textarea, [contenteditable="true"], [role="textbox"]')
              .filter(visible)
              .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom);
            target = boxes[0] || null;
          }
          if (!target) return { ok: false, detail: 'no composer for drop' };
          const bin = atob(b64);
          const bytes = new Uint8Array(bin.length);
          for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
          const file = new File([bytes], name, { type: mime });
          const dt = new DataTransfer();
          dt.items.add(file);
          const rect = target.getBoundingClientRect();
          const opts = {
            bubbles: true,
            cancelable: true,
            composed: true,
            dataTransfer: dt,
            clientX: rect.left + rect.width / 2,
            clientY: rect.top + rect.height / 2,
          };
          for (const type of ['dragenter', 'dragover', 'drop']) {
            target.dispatchEvent(new DragEvent(type, opts));
          }
          const label = (target.getAttribute('aria-label') || target.textContent || '').replace(/\\s+/g, ' ').trim();
          return { ok: true, detail: `${target.tagName.toLowerCase()} ${label.slice(0, 40)}`.trim() };
        }
    """

    async def _flow_agent_label_at_point(self, page: Any, x: Any, y: Any) -> str:
        try:
            label = await page.evaluate(
                """
                ({ x, y }) => {
                  const el = document.elementFromPoint(x, y);
                  if (!el) return '';
                  const control = el.closest('button, [role="button"], [role="option"], [role="menuitem"], a, label') || el;
                  return [
                    control.textContent || '',
                    control.getAttribute('aria-label') || '',
                    control.getAttribute('title') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim().slice(0, 160);
                }
                """,
                {"x": float(x), "y": float(y)},
            )
            return str(label or "")
        except Exception:
            return ""

    async def _click_flow_agent_point_if(self, page: Any, x: Any, y: Any, pattern: str, what: str) -> tuple[bool, str]:
        try:
            px, py = float(x), float(y)
        except (TypeError, ValueError):
            return False, f"{what}: invalid point"
        label = await self._flow_agent_label_at_point(page, px, py)
        if not re.search(pattern, label or "", flags=re.IGNORECASE):
            return False, f"{what} moved (found '{label[:50]}' at {int(px)},{int(py)})"
        try:
            await page.mouse.click(px, py)
        except Exception as exc:
            return False, f"{what} click failed: {humanize_flow_error(str(exc))[:60]}"
        return True, f"{what} '{label[:50]}'@{int(px)},{int(py)}"

    async def _click_flow_agent_new_session_button(self, page: Any) -> tuple[bool, str]:
        try:
            result = await page.evaluate(
                """
                () => {
                  const deepQuery = (selector, root = document, seen = new Set()) => {
                    const found = [];
                    const visit = (node) => {
                      if (!node || seen.has(node)) return;
                      seen.add(node);
                      try {
                        found.push(...node.querySelectorAll(selector));
                        for (const el of node.querySelectorAll('*')) {
                          if (el.shadowRoot) visit(el.shadowRoot);
                        }
                      } catch (_) {}
                    };
                    visit(root);
                    return found;
                  };
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 16 || rect.height < 16) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden' && style.display !== 'none' && style.opacity !== '0' && !el.disabled
                      && rect.bottom > 0 && rect.top < window.innerHeight;
                  };
                  const labelFor = (el) => [
                    el.textContent || '',
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const target = deepQuery('button, [role="button"]')
                    .filter(visible)
                    .map((el) => ({ rect: el.getBoundingClientRect(), label: labelFor(el) }))
                    .filter((item) => item.rect.left >= window.innerWidth * 0.35 && item.rect.width <= 96 && item.rect.height <= 96)
                    .find((item) => /start\\s*new\\s*session|new\\s*session|edit_square|phiên\\s*mới|phien\\s*moi|cuộc\\s*trò\\s*chuyện\\s*mới|cuoc\\s*tro\\s*chuyen\\s*moi/i.test(item.label));
                  if (!target) return { ok: false, detail: 'no start-new-session button' };
                  return {
                    ok: true,
                    x: target.rect.left + target.rect.width / 2,
                    y: target.rect.top + target.rect.height / 2,
                    label: target.label.slice(0, 80),
                  };
                }
                """
            )
        except Exception as exc:
            return False, humanize_flow_error(str(exc))[:120]
        if not isinstance(result, dict) or not result.get("ok"):
            detail = str(result.get("detail") or "") if isinstance(result, dict) else ""
            return False, detail or "no start-new-session button"
        clicked, click_detail = await self._click_flow_agent_point_if(
            page,
            result.get("x"),
            result.get("y"),
            r"new\s*session|edit_square|phiên\s*mới|phien\s*moi|trò\s*chuyện\s*mới|tro\s*chuyen\s*moi",
            "start-new-session",
        )
        if not clicked:
            return False, click_detail
        await asyncio.sleep(1.2)
        return True, click_detail

    def _flow_agent_source_name_tokens(self, source_file_name: str) -> tuple[str, ...]:
        name = Path(str(source_file_name or "").strip()).name.lower()
        if not name:
            return ()
        tokens = [name]
        stem = Path(name).stem
        if len(stem) >= 6 and stem not in tokens:
            tokens.append(stem)
        return tuple(tokens)

    FLOW_AGENT_INGREDIENT_PICKER_JS = """
        ({ tokens }) => {
          const deepQuery = (selector, root = document, seen = new Set()) => {
            const found = [];
            const visit = (node) => {
              if (!node || seen.has(node)) return;
              seen.add(node);
              try {
                found.push(...node.querySelectorAll(selector));
                for (const el of node.querySelectorAll('*')) {
                  if (el.shadowRoot) visit(el.shadowRoot);
                }
              } catch (_) {}
            };
            visit(root);
            return found;
          };
          const visible = (el, minW = 24, minH = 16) => {
            if (!el || !(el instanceof Element)) return false;
            const rect = el.getBoundingClientRect();
            if (rect.width < minW || rect.height < minH) return false;
            const style = window.getComputedStyle(el);
            return style.visibility !== 'hidden'
              && style.display !== 'none'
              && style.opacity !== '0'
              && rect.bottom > 0
              && rect.top < window.innerHeight;
          };
          const labelFor = (el) => [
            el.textContent || '',
            el.getAttribute('aria-label') || '',
            el.getAttribute('title') || '',
            ...[...el.querySelectorAll('img')].map((img) => img.getAttribute('alt') || ''),
          ].join(' ').replace(/\\s+/g, ' ').trim();
          const selectedState = (el) => {
            for (const attr of ['aria-selected', 'aria-checked', 'aria-pressed']) {
              const value = el.getAttribute(attr);
              if (value === 'true') return true;
              if (value === 'false') return false;
            }
            const inner = el.querySelector('[aria-selected], [aria-checked], [aria-pressed], input[type="checkbox"]');
            if (inner) {
              if (inner instanceof HTMLInputElement) return Boolean(inner.checked);
              for (const attr of ['aria-selected', 'aria-checked', 'aria-pressed']) {
                const value = inner.getAttribute(attr);
                if (value === 'true') return true;
                if (value === 'false') return false;
              }
            }
            const cls = typeof el.className === 'string' ? el.className : '';
            if (/selected|checked|active/i.test(cls)) return true;
            return null;
          };
          const lowerTokens = (tokens || []).map((token) => String(token || '').toLowerCase()).filter(Boolean);
          const options = deepQuery('[role="option"], [role="listbox"] button, [role="listbox"] [role="button"], [role="checkbox"], li, button')
            .filter((el) => visible(el, 60, 24))
            .map((el) => {
              const rect = el.getBoundingClientRect();
              return { el, rect, label: labelFor(el), selected: selectedState(el) };
            })
            .filter((item) => item.label.length > 0 && item.label.length <= 240)
            .filter((item) => lowerTokens.some((token) => item.label.toLowerCase().includes(token)))
            .filter((item) => !/upload\\s*media|add\\s*to\\s*prompt/i.test(item.label))
            .sort((a, b) => a.rect.top - b.rect.top);
          const target = options[0] || null;
          const addToPrompt = deepQuery('button, [role="button"]')
            .filter((el) => visible(el, 40, 20))
            .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
            .find((item) => /add\\s*to\\s*prompt|thêm\\s*vào\\s*(prompt|lệnh|câu)|them\\s*vao|use\\s*in\\s*prompt|insert\\s*into\\s*prompt/i.test(item.label));
          const center = (rect) => ({ x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 });
          const uploading = target ? /uploading|đang\\s*tải|dang\\s*tai|processing|đang\\s*xử|dang\\s*xu/i.test(target.label) : false;
          const rawState = target
            ? ['aria-selected', 'aria-checked', 'aria-pressed'].map((attr) => `${attr}=${target.el.getAttribute(attr) || ''}`).join(' ')
              + ` class=${(typeof target.el.className === 'string' ? target.el.className : '').slice(0, 80)}`
            : '';
          return {
            option: target ? { ...center(target.rect), label: target.label.slice(0, 120), selected: target.selected, uploading, raw_state: rawState } : null,
            option_count: options.length,
            add_to_prompt: addToPrompt ? { ...center(addToPrompt.rect), label: addToPrompt.label.slice(0, 80) } : null,
          };
        }
    """

    async def _flow_agent_panel_text(self, page: Any, limit: int = 160) -> str:
        try:
            text = await page.evaluate(
                """
                () => {
                  const nodes = [...document.querySelectorAll('aside, section, div')]
                    .filter((el) => {
                      const rect = el.getBoundingClientRect();
                      const style = window.getComputedStyle(el);
                      return rect.left >= window.innerWidth * 0.6 && rect.width >= 240 && rect.height >= 300
                        && style.display !== 'none' && style.visibility !== 'hidden';
                    })
                    .sort((a, b) => (a.getBoundingClientRect().width * a.getBoundingClientRect().height) - (b.getBoundingClientRect().width * b.getBoundingClientRect().height));
                  const panel = nodes[0];
                  return panel ? (panel.innerText || '').replace(/\\s+/g, ' ').slice(0, 400) : '';
                }
                """
            )
            return str(text or "")[:limit]
        except Exception:
            return ""

    async def _flow_agent_debug_step(self, page: Any, tag: str) -> str:
        if not getattr(self, "_flow_agent_debug_steps", False):
            return ""
        shot = await self._capture_flow_agent_debug_screenshot(page, f"step-{tag}")
        text = await self._flow_agent_panel_text(page, 90)
        return f"[{tag}: {shot}; panel='{text}']"

    async def _confirm_flow_agent_ingredient_picker(self, page: Any, file_name: str, timeout_s: float = 30.0) -> str:
        tokens = list(self._flow_agent_source_name_tokens(file_name))
        if not tokens:
            return "no file name for ingredient picker"
        deadline = asyncio.get_running_loop().time() + max(3.0, float(timeout_s or 30.0))
        state: Dict[str, Any] = {}
        while asyncio.get_running_loop().time() < deadline:
            try:
                state = await page.evaluate(self.FLOW_AGENT_INGREDIENT_PICKER_JS, {"tokens": tokens})
            except Exception as exc:
                state = {"error": humanize_flow_error(str(exc))[:120]}
            state = state if isinstance(state, dict) else {}
            option_state = state.get("option") if isinstance(state.get("option"), dict) else None
            if option_state and not option_state.get("uploading"):
                break
            await asyncio.sleep(0.75)
        option = state.get("option") if isinstance(state.get("option"), dict) else None
        add_button = state.get("add_to_prompt") if isinstance(state.get("add_to_prompt"), dict) else None
        if not option and not add_button:
            return f"no ingredient picker ({str(state.get('error') or 'no option/add-to-prompt visible')[:80]})"
        parts: List[str] = []
        if option:
            option_label = str(option.get("label") or "uploaded item")[:60]
            if option.get("uploading"):
                parts.append(f"still uploading after {int(timeout_s)}s: {option_label}")
            parts.append(f"state[{str(option.get('raw_state') or '')[:90]}]")
            if option.get("selected") is True:
                parts.append(f"already selected {option_label}")
            else:
                token_pattern = "|".join(re.escape(token) for token in tokens)
                _, select_detail = await self._click_flow_agent_point_if(
                    page,
                    option.get("x"),
                    option.get("y"),
                    token_pattern,
                    "select option",
                )
                parts.append(select_detail)
                await asyncio.sleep(0.8)
                parts.append(await self._flow_agent_debug_step(page, "after-select"))
                add_button = None
                try:
                    state = await page.evaluate(self.FLOW_AGENT_INGREDIENT_PICKER_JS, {"tokens": tokens})
                    state = state if isinstance(state, dict) else {}
                    add_button = state.get("add_to_prompt") if isinstance(state.get("add_to_prompt"), dict) else None
                except Exception:
                    add_button = None
        else:
            parts.append("uploaded item not listed in picker")
        if add_button:
            _, add_detail = await self._click_flow_agent_point_if(
                page,
                add_button.get("x"),
                add_button.get("y"),
                r"add\s*to\s*prompt|thêm\s*vào|them\s*vao|use\s*in\s*prompt|insert\s*into\s*prompt",
                "add-to-prompt",
            )
            parts.append(add_detail)
            await asyncio.sleep(1.2)
            parts.append(await self._flow_agent_debug_step(page, "after-add-to-prompt"))
        else:
            parts.append("no add-to-prompt button (picker closed?)")
        return "; ".join(part for part in parts if part)

    def _flow_agent_snapshot_label_matching(self, snapshot: Dict[str, Any], tokens: tuple[str, ...]) -> str:
        if not isinstance(snapshot, dict) or not tokens:
            return ""
        for key in ("composer_chip_labels", "composer_ready_labels", "ready_labels"):
            for label in snapshot.get(key) or []:
                text = str(label or "").lower()
                if any(token in text for token in tokens):
                    return str(label)
        return ""

    async def _drop_file_on_flow_agent_composer(
        self,
        page: Any,
        source: Path,
        composer: Dict[str, Any] | None,
    ) -> tuple[bool, str]:
        try:
            payload = base64.b64encode(source.read_bytes()).decode("ascii")
        except Exception as exc:
            return False, f"drop skipped: {humanize_flow_error(str(exc))[:80]}"
        mime = mimetypes.guess_type(source.name)[0] or "image/jpeg"
        try:
            x = float((composer or {}).get("x") or 0.0)
            y = float((composer or {}).get("y") or 0.0)
        except Exception:
            x, y = 0.0, 0.0
        try:
            result = await page.evaluate(
                self.FLOW_AGENT_DROP_FILE_JS,
                {"b64": payload, "name": source.name, "mime": mime, "x": x, "y": y},
            )
        except Exception as exc:
            return False, f"drop failed: {humanize_flow_error(str(exc))[:100]}"
        if isinstance(result, dict) and result.get("ok"):
            await asyncio.sleep(2.0)
            return True, f"synthetic drop on {str(result.get('detail') or 'composer')[:60]}"
        detail = str(result.get("detail") if isinstance(result, dict) else result or "")
        return False, f"drop failed: {detail[:100]}"

    def _install_flow_page_file_chooser_guard(self, page: Any) -> None:
        """Keep Chromium from ever showing the native Windows "Open" dialog.

        While a 'filechooser' listener is registered Playwright intercepts every file
        dialog on the page. The guard feeds the source image that the current attach
        step is waiting for (or closes the chooser empty when nothing is pending), so a
        chooser that opens after an expect_file_chooser window has timed out can no
        longer leave an orphaned OS dialog on screen.
        """
        if page is None or getattr(page, "_havi_chooser_guard", False):
            return

        def _on_chooser(chooser: Any) -> None:
            async def _apply() -> None:
                if getattr(self, "_flow_agent_chooser_expecting", False):
                    return
                pending = str(getattr(self, "_flow_agent_chooser_file", "") or "")
                try:
                    if pending and Path(pending).is_file():
                        await chooser.set_files(pending)
                        self._flow_agent_chooser_handled = int(getattr(self, "_flow_agent_chooser_handled", 0) or 0) + 1
                        logging.info("Flow file chooser handled by guard with %s", Path(pending).name)
                    else:
                        await chooser.set_files([])
                        logging.info("Flow file chooser closed by guard (no pending source file)")
                except Exception as exc:
                    logging.debug("Flow file chooser guard could not handle the dialog: %s", exc)

            try:
                asyncio.get_running_loop().create_task(_apply())
            except RuntimeError:
                asyncio.ensure_future(_apply())

        try:
            page.on("filechooser", _on_chooser)
            page._havi_chooser_guard = True
        except Exception as exc:
            logging.debug("could not install file chooser guard: %s", exc)

    def _mark_chrome_profile_clean_exit(self, profile_dir: Path) -> bool:
        """Clear the crash flag so Chrome does not show the "Restore pages?" bubble.

        Workers are sometimes stopped hard (watchdog restarts, deploys); Chrome then
        records the profile as crashed and covers the Flow Agent panel with the
        restore bubble on the next launch.
        """
        preferences = Path(profile_dir) / "Default" / "Preferences"
        try:
            if not preferences.is_file():
                return False
            data = json.loads(preferences.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                return False
            profile = data.setdefault("profile", {})
            if not isinstance(profile, dict):
                return False
            if profile.get("exit_type") == "Normal" and profile.get("exited_cleanly") is True:
                return False
            profile["exit_type"] = "Normal"
            profile["exited_cleanly"] = True
            preferences.write_text(json.dumps(data, ensure_ascii=False), encoding="utf-8")
            return True
        except Exception as exc:
            logging.debug("could not mark Chrome profile clean exit: %s", exc)
            return False

    FLOW_MENU_UPLOAD_ITEM = re.compile(
        r"upload(?!ing)|t[aả]i\s*l[eê]n|computer|m[aá]y\s*t[ií]nh|device|thi[eế]t\s*b[iị]"
        r"|browse|ch[oọ]n\s*(t[eệ]p|file)",
        re.I,
    )

