    #: **Chỉ** nút của ô lệnh, không kèm "Add media" của thanh project.  Job
    #: ``90a17981`` bấm trúng "Add media" trên thanh project nên ảnh vào
    #: **thư viện**, không thành nguyên liệu: khung đếm ``6->6``, ``chips=0``.

    FLOW_AGENT_INGREDIENT_ONLY = (
        '[aria-label*="Add ingredient" i]',
        '[aria-label*="prompt box" i]',
    )

    async def _mo_menu_add_media(
        self, page: Any, *, mau_nut: tuple[str, ...] | None = None
    ) -> bool:
        """Bấm nút bung menu "Add media".  Trả về đã bấm được hay chưa."""
        for selector in (mau_nut or self.FLOW_ADD_MEDIA_BUTTON):
            try:
                nut = page.locator(selector).first
                if await nut.count() == 0:
                    continue
                try:
                    await nut.scroll_into_view_if_needed(timeout=1200)
                except Exception:
                    pass
                await nut.click(force=True, timeout=2500)
            except Exception:
                continue
            await asyncio.sleep(0.6)
            return True
        return False

    async def _attach_flow_agent_source_menu_item(
        self,
        page: Any,
        source: Path,
        *,
        so_lan_mo: int = 0,
        mau_nut: tuple[str, ...] | None = None,
    ) -> tuple[bool, str]:
        """Bấm tiếp mục "Upload" sau khi nút "Add media menu" đã bung menu.

        Flow đổi giao diện: chỗ tải ảnh nguồn không còn là nút tải thẳng mà là
        một nút biểu tượng mở menu.  Bấm nút ấy thì không có hộp chọn file nào
        bật ra, nên ``expect_file_chooser`` hết giờ — cả ngày 09/09 mọi job ảnh
        hỏng đúng câu đó.  Menu đã bung rồi thì mục "Upload" trong menu mới là
        cái mở hộp chọn.

        Chỉ bấm mục nói rõ là tải từ máy.  Bấm bừa mục khác thì gặp Drive hay
        Xoá — mở hộp thoại lạ, treo cả phiên browser.
        """
        selectors = tuple(
            f"{khung} {muc}"
            for khung in self.FLOW_MENU_PANEL
            for muc in self.FLOW_MENU_ITEM
        )
        nhan_thay: list[str] = []
        for selector in selectors:
            try:
                locator = page.locator(selector)
                count = await locator.count()
            except Exception:
                continue
            for index in range(count):
                item = locator.nth(index)
                try:
                    nhan = str(await item.inner_text() or "").strip()
                except Exception:
                    nhan = ""
                nhan_thay.append(f"{selector}»{nhan}" if nhan else f"{selector}#{index + 1}")
                if not self.FLOW_MENU_UPLOAD_ITEM.search(nhan):
                    continue
                if self.FLOW_MENU_ITEM_CAM.search(nhan):
                    continue
                try:
                    async with page.expect_file_chooser(timeout=8000) as chooser_info:
                        await item.click(force=True, timeout=2500)
                    chooser = await chooser_info.value
                    await chooser.set_files(str(source))
                    await asyncio.sleep(2.0)
                    # Kể luôn cả menu, không chỉ mục đã bấm.  Mục "upload"
                    # bấm trúng rồi mà ảnh vẫn rơi vào thư viện chứ không
                    # thành nguyên liệu của ô lệnh; muốn biết có mục nào
                    # gắn thẳng từ thư viện hay không thì phải thấy cả danh
                    # sách, mà danh sách ấy trước giờ chỉ in ra lúc hỏng.
                    return True, "file chooser via add-media menu item: %s (menu co: %s)" % (
                        nhan,
                        ", ".join(x for x in nhan_thay[:12] if x) or "khong doc duoc nhan",
                    )
                except Exception:
                    continue
        if not nhan_thay:
            # Menu đang đóng.  Đường tải ảnh lên project bấm nút này bằng
            # ``expect_file_chooser``, hết giờ, rồi bấm tiếp mấy nút khác —
            # mấy cú ấy có thể đóng menu, mà cũng có thể **để nguyên menu mở**.
            # Nút "Add media" là nút bập bênh: menu đang mở thì cú bấm của ta
            # đóng nó lại, soi xong vẫn trắng tay.  Nên bấm tới hai lần: lần
            # đầu không ra mục nào thì lần sau bập ngược lại.
            if so_lan_mo < 2:
                if await self._mo_menu_add_media(page, mau_nut=mau_nut):
                    return await self._attach_flow_agent_source_menu_item(
                        page, source, so_lan_mo=so_lan_mo + 1, mau_nut=mau_nut
                    )
                return False, "add-media menu: khong thay nut bung menu"
            return False, "add-media menu: bam mo %d lan van khong thay muc nao" % so_lan_mo
        return False, "add-media menu: khong muc nao mo duoc hop chon file (%s)" % ", ".join(nhan_thay[:12])

    #: Bảng chọn nguyên liệu bấm ô ảnh xong **chưa** gắn gì cả: ô chỉ sáng lên,
    #: ảnh hiện ở khung xem trước, và phải bấm tiếp nút trắng to
    #: ``Add to prompt`` bên dưới.  Ảnh chụp lúc hỏng của job ``87c82090`` bày
    #: đúng cảnh ấy — ô ``erp-87c82090-1.png`` đang sáng, nút vẫn nguyên.

    FLOW_NUT_THEM_VAO_LENH = (
        'button:has-text("Add to prompt")',
        '[aria-label*="Add to prompt" i]',
        '[role="button"]:has-text("Add to prompt")',
        # Nhãn có thể nằm trong thẻ con chứ không nằm thẳng trên nút; bấm vào
        # thẻ con thì cú bấm vẫn nổi lên tới nút.
        'text="Add to prompt"',
        'button:has-text("Thêm vào câu lệnh")',
        'button:has-text("Thêm vào")',
    )

    #: Bảng chọn nguyên liệu có nút tải riêng, nằm dưới cùng cột trái:
    #: ``Upload media``.  Nó không mang ``role="menuitem"`` nên vòng quét mục
    #: menu không thấy — job ``72977963`` liệt ra 345 mục mà mục nào cũng là ô
    #: ảnh.  Đây mới là đường tải thẳng vào bảng chọn.

    FLOW_NUT_TAI_TRONG_BANG = (
        '[aria-label*="Upload media" i]',
        'button:has-text("Upload media")',
        'button:has-text("Tải lên")',
    )

    #: Ô ảnh đang tải dở trong bảng chọn.  Bấm vào nó thì không thành nguyên
    #: liệu — job ``d17889dc`` đọc ra ``Uploading\nerp-d17889dc-1.png\nImage``.

    FLOW_O_ANH_DANG_TAI = re.compile(r"uploading|\bdang\s*t[aả]i", re.I)

    async def _tai_anh_trong_bang_chon(self, page: Any, source: Path) -> tuple[bool, str]:
        """Bấm ``Upload media`` ngay trong bảng chọn rồi nạp ảnh ERP vào.

        Đường cũ trông chờ ảnh đã nằm sẵn trong thư viện project.  Nhưng cú tải
        lên thư viện thất bại thì ô ảnh kẹt ở ``Uploading`` mãi: job
        ``72977963`` chờ 45 giây, soi 345 mục, lần nào cũng thấy ô của mình còn
        dang dở.  Bảng chọn có nút tải riêng — dùng nó thì không phải trông chờ
        ai cả.
        """
        for selector in self.FLOW_NUT_TAI_TRONG_BANG:
            for mau in (f"{selector}:visible", selector):
                try:
                    nut = page.locator(mau).first
                    if await nut.count() == 0:
                        continue
                except Exception:
                    continue
                try:
                    async with page.expect_file_chooser(timeout=8000) as hop:
                        await nut.click(force=True, timeout=2500)
                    chooser = await hop.value
                    await chooser.set_files(str(source))
                except Exception:
                    continue
                await asyncio.sleep(2.0)
                return True, f"nap anh qua nut tai cua bang chon ({selector})"
        return False, "khong thay nut Upload media trong bang chon"

    async def _bam_them_vao_lenh(self, page: Any) -> tuple[bool, str]:
        """Bấm nút ``Add to prompt`` để chốt ô ảnh vừa chọn thành nguyên liệu.

        Bấm ô ảnh mới chỉ là **chọn**: job ``87c82090`` bấm trúng ô, ảnh hiện
        ở khung xem trước, mà khung lệnh vẫn ``6->6``, ``chips=0``.  Cái chốt
        là nút trắng nằm dưới khung xem trước.
        """
        for selector in self.FLOW_NUT_THEM_VAO_LENH:
            for mau in (f"{selector}:visible", selector):
                try:
                    nut = page.locator(mau).first
                    if await nut.count() == 0:
                        continue
                    await nut.click(force=True, timeout=2500)
                except Exception:
                    continue
                await asyncio.sleep(2.0)
                return True, f"bam nut them vao lenh ({selector})"
        ok, detail = await self._bam_nut_chot_theo_nhan(page)
        if ok:
            return True, detail
        return False, "khong thay nut Add to prompt trong bang chon (%s)" % (
            await self._ke_nut_trong_bang_chon(page),
        )

    #: Nhãn nút chốt, đọc rộng. Bốn mẫu chọn cứng ở trên đều trượt ở job
    #: ``22d41874``, nên vòng này đọc nhãn thật rồi mới bấm. Bấm nhầm cũng
    #: không hại: bước kiểm ``chips``/``attachments`` phía sau vẫn chặn, job
    #: hỏng đúng như khi không bấm gì.

    FLOW_NHAN_NUT_CHOT = re.compile(
        r"add\s*to\s*prompt|th[eê]m\s*v[aà]o|ch[eè]n|insert|confirm|\bdone\b|\bxong\b",
        re.I,
    )

    #: Nút phải tránh: bấm ``Cancel`` là đóng bảng, bấm ``Upload`` là mở lại
    #: hộp chọn file mà không ai điền.

    FLOW_NHAN_NUT_TRANH = re.compile(
        r"cancel|close|delete|remove|upload|h[uủ]y|h[uủ]y\s*b[oỏ]|đ[oó]ng|x[oó]a",
        re.I,
    )

    async def _bam_nut_chot_theo_nhan(self, page: Any) -> tuple[bool, str]:
        """Đọc nhãn từng nút trong bảng chọn rồi bấm cái trông như nút chốt.

        Mẫu chọn cứng phải đoán trước tên nút; vòng này thì không. Nó duyệt
        nút trong lớp phủ, bỏ nút nguy hiểm, rồi bấm nút đầu tiên có nhãn
        giống nút chốt.
        """
        selector = '.cdk-overlay-container button, .cdk-overlay-container [role="button"]'
        try:
            danh_sach = page.locator(selector)
            so = await danh_sach.count()
        except Exception:
            return False, "khong duyet duoc nut trong bang chon"
        for index in range(min(int(so or 0), 40)):
            try:
                nut = danh_sach.nth(index)
                nhan = (await nut.inner_text() or "").strip()
            except Exception:
                continue
            if not nhan or self.FLOW_NHAN_NUT_TRANH.search(nhan):
                continue
            if not self.FLOW_NHAN_NUT_CHOT.search(nhan):
                continue
            try:
                await nut.click(force=True, timeout=2500)
            except Exception:
                continue
            await asyncio.sleep(2.0)
            return True, f"bam nut chot theo nhan ({nhan[:40]})"
        return False, "khong nut nao trong bang chon co nhan giong nut chot"

    #: Soi thẳng **ô nhập lệnh**, đừng soi cây con của panel Tác nhân.
    #:
    #: Job ``048f18e9`` chốt xong, ảnh chụp thấy rõ ô ảnh nằm cạnh câu lệnh,
    #: mà bản soi panel đọc ra ``allMedia=0``: sau cú gắn Flow dựng lại panel,
    #: khung lệnh nổi thành thẻ riêng nên không còn là con của panel nữa.
    _JS_ANH_KHUNG_LENH = """
    (ten) => {
      const kim = String(ten || '').toLowerCase().replace(/\.[a-z0-9]+$/, '');
      const goc = [];
      const dat = (root) => {
        goc.push(root);
        for (const el of root.querySelectorAll('*')) {
          if (el.shadowRoot) dat(el.shadowRoot);
        }
      };
      dat(document);
      const tatca = [];
      for (const r of goc) for (const el of r.querySelectorAll('*')) tatca.push(el);
      const hien = (el, w, h) => {
        const r = el.getBoundingClientRect();
        if (r.width < w || r.height < h) return false;
        if (r.bottom < 0 || r.top > window.innerHeight) return false;
        const st = getComputedStyle(el);
        return st.visibility !== 'hidden' && st.display !== 'none'
          && Number(st.opacity || '1') > 0.05;
      };
      const nhanCua = (el) => [
        el.getAttribute('aria-label'), el.getAttribute('title'),
        el.getAttribute('alt'), el.getAttribute('src'),
      ].filter(Boolean).join(' ').toLowerCase();
      let khop_ten = false;
      if (kim) {
        for (const el of tatca) {
          if (!hien(el, 8, 8)) continue;
          if (nhanCua(el).includes(kim)) { khop_ten = true; break; }
        }
      }
      const oNhap = tatca.filter((el) =>
        el.matches('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]')
        && hien(el, 120, 12));
      // Đi ngược lên tìm thẻ chứa khung lệnh, nhưng **chỉ nhận ô ảnh nằm sát
      // câu lệnh**.  Không chặn theo hình thì cú đi ngược sẽ chạm tới thẻ bọc
      // cả trang, rồi đếm luôn ô trên lưới media — mà lưới thì *có* mọc thêm
      // ô mỗi lần upload, nên job hỏng lại đọc ra "đã gắn".
      const kefBox = (box, el) => {
        const a = box.getBoundingClientRect();
        const b = el.getBoundingClientRect();
        if (b.right < a.left || b.left > a.right) return false;
        return b.bottom >= a.top - 220 && b.top <= a.bottom + 220;
      };
      const anh = [];
      for (const box of oNhap) {
        let node = box;
        for (let i = 0; node && i < 8; i += 1, node = node.parentElement) {
          const trong = [...node.querySelectorAll('img, canvas, video, [style*="background-image"]')]
            .filter((el) => hien(el, 24, 24))
            .filter((el) => {
              const r = el.getBoundingClientRect();
              return r.width <= 260 && r.height <= 260;
            })
            .filter((el) => kefBox(box, el));
          if (trong.length) { for (const el of trong) anh.push(el); break; }
        }
      }
      const duy = [...new Set(anh)];
      return {
        khop_ten,
        so_anh_khung: duy.length,
        so_o_nhap: oNhap.length,
        nhan: duy.slice(0, 8).map((el) => (nhanCua(el) || el.tagName.toLowerCase()).slice(0, 60)),
      };
    }
    """

    async def _soi_o_anh_khung_lenh(
        self, page: Any, ten_tep: str = ""
    ) -> Dict[str, Any]:
        """Đếm ô ảnh đang nằm ngay cạnh câu lệnh, và tra cả tên ảnh ERP."""
        try:
            ra = await page.evaluate(self._JS_ANH_KHUNG_LENH, str(ten_tep or ""))
        except Exception as exc:
            return {
                "khop_ten": False,
                "so_anh_khung": 0,
                "nhan": [],
                "loi": humanize_flow_error(str(exc))[:120],
            }
        if not isinstance(ra, dict):
            return {"khop_ten": False, "so_anh_khung": 0, "nhan": []}
        return ra

    def _khung_lenh_da_nhan(
        self, truoc: Dict[str, Any] | None, sau: Dict[str, Any] | None
    ) -> tuple[bool, str]:
        """Khung lệnh có nhận thêm ảnh không — so trước với sau, không đoán.

        Tên ảnh ERP hiện ra là bằng chứng thẳng.  Không có tên thì đòi khung
        phải **mọc thêm** một ô ảnh: ô cũ còn sót lại từ lượt trước không được
        tính là đã gắn.
        """
        truoc = truoc if isinstance(truoc, dict) else {}
        sau = sau if isinstance(sau, dict) else {}
        try:
            so_truoc = int(truoc.get("so_anh_khung") or 0)
        except Exception:
            so_truoc = 0
        try:
            so_sau = int(sau.get("so_anh_khung") or 0)
        except Exception:
            so_sau = 0
        nhan = ", ".join(str(x) for x in (sau.get("nhan") or [])[:4])
        if sau.get("khop_ten"):
            return True, f"khung lenh mang ten anh nguon ({nhan})"
        if so_sau > so_truoc:
            return True, f"khung lenh moc them o anh {so_truoc}->{so_sau} ({nhan})"
        return False, f"khung lenh khong moc them o anh {so_truoc}->{so_sau} ({nhan})"

    async def _cho_bang_chon_dong(
        self, page: Any, *, timeout_s: float = 10.0
    ) -> tuple[bool, str]:
        """Chờ bảng chọn đóng hẳn rồi hãy soi khung Tác nhân.

        Job ``22d41874`` chốt xong rồi soi ra ``16->0`` — khung tụt về không
        ngay sau cú bấm, trong khi ảnh chụp cho thấy ô ảnh nằm sẵn trong khung
        lệnh.  Lớp phủ CDK còn mở thì thứ nằm dưới nó không "nhìn thấy" được,
        nên soi lúc ấy là soi vào tấm màn.
        """
        deadline = asyncio.get_running_loop().time() + max(1.0, float(timeout_s or 10.0))
        con = -1
        while asyncio.get_running_loop().time() < deadline:
            try:
                con = await page.evaluate(
                    """
                    () => {
                      const khung = document.querySelector('.cdk-overlay-container');
                      if (!khung) return 0;
                      return [...khung.children].filter((el) => {
                        const r = el.getBoundingClientRect();
                        return r.width > 8 && r.height > 8;
                      }).length;
                    }
                    """
                )
            except Exception:
                return True, "khong doc duoc lop phu, coi nhu da dong"
            if not con:
                return True, "bang chon da dong"
            await asyncio.sleep(0.5)
        return False, f"bang chon van mo ({con} lop)"

    async def _ke_nut_trong_bang_chon(self, page: Any) -> str:
        """Kể tên mọi nút đang hiện trong bảng chọn, để khỏi đoán nhãn nút.

        Job ``22d41874`` tải được ảnh, bấm trúng ô, rồi chết ở đúng một câu:
        "khong thay nut Add to prompt".  Không biết nút ấy tên gì thì mỗi lần
        đoán mất trọn một vòng deploy.
        """
        try:
            ten = await page.evaluate(
                """
                () => {
                  const khung = document.querySelector('.cdk-overlay-container');
                  if (!khung) return ['khong co lop phu'];
                  const ra = [];
                  for (const el of khung.querySelectorAll('button, [role="button"]')) {
                    const r = el.getBoundingClientRect();
                    if (r.width < 8 || r.height < 8) continue;
                    const t = (el.innerText || '').trim().replace(/\s+/g, ' ')
                      || (el.getAttribute('aria-label') || '').trim();
                    if (t) ra.push(t.slice(0, 40));
                  }
                  return [...new Set(ra)].slice(0, 20);
                }
                """
            )
        except Exception:
            return "khong ke duoc nut nao"
        if not isinstance(ten, list) or not ten:
            return "bang chon khong co nut nao"
        return ", ".join(str(x) for x in ten)

    async def _chon_anh_trong_menu(
        self, page: Any, ten_tep: str, *, timeout_s: float = 150.0
    ) -> tuple[bool, str]:
        """Bấm thẳng ô ảnh có sẵn trong bảng chọn nguyên liệu.

        Nút gắn nguyên liệu của ô lệnh **không** mở hộp chọn file: nó bung một
        bảng liệt kê media của project.  Job ``d17889dc`` đọc ra đúng mười hai
        mục ``[role="option"]``, tên mục nào cũng là ``erp-…png`` — tức ảnh ERP
        đã nằm sẵn trong ấy rồi.  Vậy thì đừng tải lại lần nữa: bấm đúng ô mang
        tên nó là xong.

        Trước đây cả loạt job chết ở đây vì hàm chỉ đi tìm mục "Upload".  Không
        thấy mục nào tên "Upload" thì nó báo thua, trong khi thứ cần bấm đang
        bày ngay trước mắt.

        Bỏ qua ô còn chữ ``Uploading``: ô ấy chưa tải xong.  Chờ lại vài nhịp,
        vì ảnh vừa đẩy lên thì mất dăm giây mới sẵn sàng.
        """
        ten = str(ten_tep or "").strip()
        if not ten:
            return False, "khong co ten tep de chon trong bang nguyen lieu"
        selectors = tuple(
            f"{khung} {muc}"
            for khung in self.FLOW_MENU_PANEL
            for muc in self.FLOW_MENU_ITEM
        )
        vong = asyncio.get_running_loop()
        han = vong.time() + max(1.0, float(timeout_s or 150.0))
        cho_tai = 0
        thay = 0
        while True:
            for selector in selectors:
                try:
                    locator = page.locator(selector)
                    count = await locator.count()
                except Exception:
                    continue
                for index in range(count):
                    item = locator.nth(index)
                    try:
                        nhan = str(await item.inner_text() or "").strip()
                    except Exception:
                        continue
                    thay += 1
                    if ten not in nhan:
                        continue
                    if self.FLOW_O_ANH_DANG_TAI.search(nhan):
                        cho_tai += 1
                        continue
                    try:
                        await item.click(force=True, timeout=2500)
                    except Exception as exc:
                        return False, "bam o anh %s hong: %s" % (
                            ten, humanize_flow_error(str(exc)),
                        )
                    await asyncio.sleep(1.2)
                    them_ok, them_detail = await self._bam_them_vao_lenh(page)
                    if not them_ok:
                        return False, (
                            f"bam o anh {ten} roi ma khong xac nhan duoc ({them_detail})"
                        )
                    _dong_ok, dong_detail = await self._cho_bang_chon_dong(page)
                    return True, (
                        f"bam o anh {ten} trong bang chon nguyen lieu ({selector})"
                        f" roi {them_detail}; {dong_detail}"
                    )
            if vong.time() >= han:
                break
            await asyncio.sleep(2.0)
        return False, (
            "khong thay o anh %s trong bang chon nguyen lieu"
            " (soi %d muc, %d muc con dang tai)" % (ten, thay, cho_tai)
        )

    async def _chup_man_hinh_soi(self, page: Any, thu_muc: Any, ten: str) -> str:
        """Chụp màn hình trang Flow để soi bằng mắt, trả về đường dẫn file.

        Nhật ký chỉ nói được "chưa ăn"; ảnh nói được **vì sao**.  Năm lượt
        sửa vừa rồi đều đoán cấu trúc panel Tác nhân, mỗi lượt mất một
        vòng deploy.  Ảnh chụp cắt đứt vòng đoán ấy.

        Chỉ ghi ra đĩa cạnh ảnh nguồn, không gửi đi đâu, hỏng thì trả về
        một dòng chứ không được làm chết job.
        """
        try:
            dich = Path(str(thu_muc or ".")) / "soi"
            dich.mkdir(parents=True, exist_ok=True)
            duong_dan = dich / f"{str(ten or 'soi')}.png"
            await page.screenshot(path=str(duong_dan))
        except Exception as exc:
            return f"khong chup duoc: {humanize_flow_error(str(exc))}"
        return str(duong_dan)

    async def _soi_khung_tac_nhan(self, page: Any, ten_tep: str) -> str:
        """Soi một lượt khung Tác nhân rồi trả về một dòng tóm tắt.

        Chỉ đọc: không bấm, không kéo, không thả.  Bốn lượt sửa vừa rồi
        đều **đoán** cách Flow nhận ảnh, mỗi lượt mất một vòng deploy mà
        log chỉ nói được "chưa ăn".  Dòng này trả lời thẳng ba câu:

        * ô lưới và tám lớp bọc của nó có ``draggable`` không — không có
          thì kéo bằng chuột hay bằng ``DragEvent`` đều trượt, phải đi
          đường nút;
        * quanh ô nhập lệnh có những nút nào, nhãn là gì;
        * cả trang còn ``input`` nào không (``input[type=file]`` vẫn là 0
          trong mọi log ngày 09/09).
        """
        ten = str(ten_tep or "").strip()
        try:
            kq = await page.evaluate(
                """
                (ten) => {
                  const hien = (el, w, h) => {
                    const r = el.getBoundingClientRect();
                    if (r.width < w || r.height < h) return false;
                    const s = window.getComputedStyle(el);
                    return s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0';
                  };
                  // Ô nhập lệnh phải nằm **trong khung nhìn**.  Không lọc
                  // thì hàm vớ phải một ``div`` ở đáy vùng cuộn: job
                  // ``f2eee06b`` soi ra ``div@4692`` — cách mép dưới màn
                  // hình mấy nghìn điểm ảnh, thả gì vào đó cũng vô nghĩa.
                  const trong_khung_nhin = (el) => {
                    // Đo phần **nhìn thấy được**, không đo cả thẻ.  Ô nhập
                    // lệnh của Tác nhân đang mang prompt dài nên hộp bao của
                    // nó cao hơn 4000 điểm ảnh — ``div@4692`` trong job
                    // ``f2eee06b`` chính là nó, bị thẻ cha cắt bớt chứ không
                    // hề nằm ngoài màn hình.  Đòi "nằm trọn trong khung nhìn"
                    // là loại nhầm đúng cái ta cần: job ``95c7775f`` soi ra
                    // "khong thay khung".
                    const r = el.getBoundingClientRect();
                    const cao = Math.min(r.bottom, window.innerHeight) - Math.max(r.top, 0);
                    const rong = Math.min(r.right, window.innerWidth) - Math.max(r.left, 0);
                    return cao >= 8 && rong >= 8;
                  };
                  const ta = (el) => {
                    const bit = [];
                    const d = el.getAttribute('draggable');
                    if (d) bit.push('drag=' + d);
                    const r = el.getAttribute('role');
                    if (r) bit.push('role=' + r);
                    const rd = el.getAttribute('aria-roledescription');
                    if (rd) bit.push('rd=' + rd);
                    return el.tagName.toLowerCase() + (bit.length ? '[' + bit.join(',') + ']' : '');
                  };
                  const nhan = (el) => [
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('title') || '',
                    el.getAttribute('data-testid') || '',
                    (el.textContent || '').slice(0, 24),
                  ].join(' ').replace(/\s+/g, ' ').trim().slice(0, 44);
                  const o = [...document.querySelectorAll('[aria-label], [title]')]
                    .filter((el) => (`${el.getAttribute('aria-label') || ''} ${el.getAttribute('title') || ''}`).includes(ten))
                    .filter((el) => hien(el, 40, 40))
                    .sort((a, b) => {
                      const ra = a.getBoundingClientRect();
                      const rb = b.getBoundingClientRect();
                      return rb.width * rb.height - ra.width * ra.height;
                    })[0];
                  let chuoi = 'khong thay o luoi';
                  if (o) {
                    const doan = [];
                    let el = o;
                    for (let i = 0; i < 8 && el; i += 1) { doan.push(ta(el)); el = el.parentElement; }
                    chuoi = doan.join(' < ');
                  }
                  const khung = [...document.querySelectorAll('textarea, [contenteditable="true"], [role="textbox"]')]
                    .filter((el) => hien(el, 60, 16))
                    .filter((el) => trong_khung_nhin(el))
                    .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0];
                  // Đáy **đã cắt**: in ra đáy của cả thẻ thì được ``4692``,
                  // một con số không có trên màn hình, đọc log lại tưởng
                  // hỏng.
                  const day = khung
                    ? Math.min(khung.getBoundingClientRect().bottom, window.innerHeight)
                    : window.innerHeight;
                  const nut = [...document.querySelectorAll('button, [role="button"], label, [aria-haspopup]')]
                    .filter((el) => hien(el, 14, 14))
                    .filter((el) => {
                      const r = el.getBoundingClientRect();
                      return r.left >= window.innerWidth * 0.4 && r.top >= day - 240 && r.top <= day + 160;
                    })
                    .slice(0, 16)
                    .map((el) => {
                      const r = el.getBoundingClientRect();
                      return `${ta(el)}"${nhan(el)}"@${Math.round(r.left)},${Math.round(r.top)}${el.disabled ? '(tat)' : ''}`;
                    });
                  return {
                    o: chuoi,
                    khung: khung ? `${ta(khung)}@${Math.round(day)}` : 'khong thay khung',
                    nut,
                    input: document.querySelectorAll('input').length,
                    file: document.querySelectorAll('input[type="file"]').length,
                  };
                }
                """,
                ten,
            )
        except Exception as exc:
            return f"khong soi duoc khung: {humanize_flow_error(str(exc))}"
        if not isinstance(kq, dict):
            return "khong soi duoc khung: ket qua rong"
        nut = kq.get("nut") if isinstance(kq.get("nut"), list) else []
        return "o luoi: %s | khung: %s | input=%s file=%s | %d nut quanh khung: %s" % (
            kq.get("o"),
            kq.get("khung"),
            kq.get("input"),
            kq.get("file"),
            len(nut),
            " ~ ".join(str(x) for x in nut),
        )

    #: Chữ ký của một ô ảnh trên lưới media: ``thẻ|nhãn``.  Flow đổi tên file
    #: khi nhận, nên tên trên máy không tra được ô nào; cái tra được là **ô
    #: nào vừa mọc thêm**, mà muốn so thì phải có chữ ký.
    _JS_CHU_KY_O_LUOI = """
        () => {
          const hien = (el) => {
            const r = el.getBoundingClientRect();
            if (r.width < 60 || r.height < 60) return false;
            const s = window.getComputedStyle(el);
            return s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0';
          };
          // Panel Tác nhân nằm bên phải và **cũng** có thẻ mang ảnh:
          // "Brainstorm with me", "Turn a concept into prompts"…  Đếm cả
          // chúng thì lượt nào cũng thấy "ô mới", mà kéo vào khung thì rỗng.
          const ben_trai = (el) => el.getBoundingClientRect().left < window.innerWidth * 0.70;
          const la_anh = (el) => {
            if (el.tagName.toLowerCase() === 'img') return true;
            if (el.querySelector('img, video, canvas')) return true;
            const nen = window.getComputedStyle(el).backgroundImage || '';
            return nen !== '' && nen !== 'none';
          };
          const ung_vien = [];
          for (const el of document.querySelectorAll('[aria-label], [title]')) {
            const ten = (el.getAttribute('aria-label') || '').trim()
              || (el.getAttribute('title') || '').trim();
            if (!ten) continue;
            if (!hien(el)) continue;
            if (!ben_trai(el)) continue;
            if (!la_anh(el)) continue;
            ung_vien.push(el);
          }
          // Bỏ thẻ **bọc**: ``cdk-virtual-scroll-viewport|Asset list`` bọc cả
          // lưới nên lượt nào cũng "mới", mà kéo nó thì chẳng kéo ảnh nào —
          // job ``87c82090`` kéo trúng đúng cái vỏ ấy.
          const ra = ung_vien
            .filter((el) => !ung_vien.some((khac) => khac !== el && el.contains(khac)))
            .map((el) => `${el.tagName.toLowerCase()}|`
              + ((el.getAttribute('aria-label') || '').trim()
                 || (el.getAttribute('title') || '').trim()));
          return [...new Set(ra)];
        }
    """

    async def _chup_chu_ky_o_luoi(self, page: Any) -> set[str]:
        """Ghi chữ ký mọi ô ảnh đang có trên lưới media của project.

        Thư viện project không hỏi được bằng API nữa: ``flow.projectInitialData``
        trả 401 vì thư viện ``flow`` gọi sang ``labs.google/fx`` trong khi app
        đã dọn về ``flow.google.com``, còn ``/api/trpc`` trên tên miền mới chỉ
        trả về vỏ HTML.  Lưới trên màn hình là chỗ duy nhất còn nói thật.
        """
        try:
            ds = await page.evaluate(self._JS_CHU_KY_O_LUOI)
        except Exception:
            return set()
        if not isinstance(ds, list):
            return set()
        return {str(x).strip() for x in ds if str(x or "").strip()}

    async def _cho_o_luoi_moi(
        self,
        page: Any,
        truoc: set[str] | None = None,
        *,
        timeout_s: float = 180.0,
        job_id: str = "",
    ) -> str:
        """Chờ lưới mọc thêm một ô rồi trả về chữ ký của ô ấy.

        Flow đặt lại tên file lúc nhận, nên ``erp-<job>-1.png`` không bao giờ
        khớp ô nào — ``o luoi: khong thay o luoi`` trong mọi job là đúng chứ
        không hỏng.  Ô vừa mọc thì tra được: chụp lưới trước khi tải, chụp
        lại sau, cái chênh nhau chính là ảnh ERP.
        """
        moc = {str(x).strip() for x in (truoc or set())}
        vong = asyncio.get_running_loop()
        han = vong.time() + max(1.0, float(timeout_s or 180.0))
        lan = 0
        while True:
            lan += 1
            for chu_ky in sorted(await self._chup_chu_ky_o_luoi(page)):
                if chu_ky not in moc:
                    return chu_ky
            if vong.time() >= han:
                return ""
            if job_id and lan % 20 == 0:
                await self.store.append_log(
                    job_id,
                    "Fallback UI Flow: chờ ô mới trên lưới media — %s"
                    % await self._soi_tien_do_tai_anh(page),
                )
            await asyncio.sleep(1.5)

    async def _cho_anh_hien_tren_luoi(
        self, page: Any, ten_tep: str, *, timeout_s: float = 25.0
    ) -> bool:
        """Chờ ô lưới media của project mang đúng tên file ảnh ERP.

        Cú tải ảnh lên project **có** chạy: bản kết xuất ứng viên lúc
        19:34:49 ngày 09/09 cho thấy ``erp-a20f9b25-1.png``,
        ``erp-eca44a0a-1.jpg``… đã nằm trên lưới, dù job nào cũng vừa báo
        "Flow project upload failed".  Chỗ hỏng là khâu **nhận biết**:
        ``_api.upload_image`` đọc workflow cuối rồi ném lỗi, còn
        ``_project_media_names`` chỉ trả mã media chứ không trả tên file.

        Lưới thì nói thẳng: mỗi ô là một ``FLOW-GRID-TILE-CONTAINER`` có
        ``aria-label`` đúng bằng tên file.  Nên hỏi lưới, đừng hỏi API.
        """
        ten = str(ten_tep or "").strip()
        if not ten:
            return False
        han = asyncio.get_running_loop().time() + max(1.0, float(timeout_s or 25.0))
        while True:
            try:
                thay = await page.evaluate(
                    """
                    (ten) => {
                      const nut = [...document.querySelectorAll('[aria-label], [title]')];
                      return nut.some((el) => {
                        const nhan = `${el.getAttribute('aria-label') || ''} ${el.getAttribute('title') || ''}`;
                        if (!nhan.includes(ten)) return false;
                        const rect = el.getBoundingClientRect();
                        return rect.width >= 40 && rect.height >= 40;
                      });
                    }
                    """,
                    ten,
                )
            except Exception:
                thay = False
            if thay:
                return True
            if asyncio.get_running_loop().time() >= han:
                return False
            await asyncio.sleep(1.5)

    async def _keo_o_luoi_vao_khung(
        self, page: Any, ten_tep: str, *, chu_ky: str = ""
    ) -> tuple[bool, str]:
        """Kéo ô ảnh trên lưới vào khung Tác nhân bằng sự kiện kéo–thả.

        ``_select_flow_edit_target_image`` kéo bằng chuột thật —
        ``mouse.down``, di, ``mouse.up``, rồi **còn bấm thêm một cú** vào
        đích.  Flow hiểu đó là bấm vào ô ảnh nên mở ảnh ra, panel Tác nhân
        biến mất: bản chụp sau đó rơi vào nhánh "không thấy panel" và trả
        về **toàn số 0** — chính là dãy ``16->0`` trong job ``879299d2``.

        Kéo–thả HTML5 thì không đẻ ra cú bấm nào.  Mẹo ở chỗ dùng **một**
        ``DataTransfer`` cho cả lượt: ``dragstart`` bắn vào ô ảnh để chính
        Flow tự nhét dữ liệu của nó vào, rồi đưa nguyên gói ấy sang
        ``drop``.  Nhờ vậy không phải đoán Flow dùng kiểu dữ liệu gì.

        Có ``chu_ky`` thì tra theo chữ ký ``thẻ|nhãn`` của
        ``_chup_chu_ky_o_luoi``, khớp **đúng bằng**.  Tra theo tên file chỉ
        đúng khi Flow giữ nguyên tên, mà Flow thì đặt lại tên lúc nhận.
        """
        ten = str(ten_tep or "").strip()
        ky = str(chu_ky or "").strip()
        if not ten and not ky:
            return False, "khong co ten tep de tim tren luoi"
        try:
            result = await page.evaluate(
                """
                ({ ten, chu_ky }) => {
                  const hien = (el, minW, minH) => {
                    const rect = el.getBoundingClientRect();
                    if (rect.width < minW || rect.height < minH) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0';
                  };
                  const chu_ky_cua = (el) => `${el.tagName.toLowerCase()}|`
                    + ((el.getAttribute('aria-label') || '').trim()
                       || (el.getAttribute('title') || '').trim());
                  const khop = chu_ky
                    ? (el) => chu_ky_cua(el) === chu_ky
                    : (el) => `${el.getAttribute('aria-label') || ''} ${el.getAttribute('title') || ''}`.includes(ten);
                  const o = [...document.querySelectorAll('[aria-label], [title]')]
                    .filter(khop)
                    .filter((el) => hien(el, 40, 40))
                    .sort((a, b) => {
                      const ra = a.getBoundingClientRect();
                      const rb = b.getBoundingClientRect();
                      return rb.width * rb.height - ra.width * ra.height;
                    })[0];
                  if (!o) return { ok: false, detail: `khong thay o luoi mang ten ${chu_ky || ten}` };
                  const trong_khung_nhin = (el) => {
                    // Đo phần **nhìn thấy được**, không đo cả thẻ.  Ô nhập
                    // lệnh của Tác nhân đang mang prompt dài nên hộp bao của
                    // nó cao hơn 4000 điểm ảnh — ``div@4692`` trong job
                    // ``f2eee06b`` chính là nó, bị thẻ cha cắt bớt chứ không
                    // hề nằm ngoài màn hình.  Đòi "nằm trọn trong khung nhìn"
                    // là loại nhầm đúng cái ta cần: job ``95c7775f`` soi ra
                    // "khong thay khung".
                    const r = el.getBoundingClientRect();
                    const cao = Math.min(r.bottom, window.innerHeight) - Math.max(r.top, 0);
                    const rong = Math.min(r.right, window.innerWidth) - Math.max(r.left, 0);
                    return cao >= 8 && rong >= 8;
                  };
                  const khung = [...document.querySelectorAll('textarea, [contenteditable="true"], [role="textbox"]')]
                    .filter((el) => hien(el, 60, 16))
                    .filter(trong_khung_nhin)
                    .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0];
                  if (!khung) return { ok: false, detail: 'khong thay o nhap lenh cua Tac nhan trong khung nhin' };
                  // Một gói cho cả lượt: Flow tự nhét dữ liệu của nó vào ở
                  // ``dragstart``, ta chỉ việc chuyển nguyên gói sang ``drop``.
                  const goi = new DataTransfer();
                  const bay = (loai, dich) => dich.dispatchEvent(new DragEvent(loai, {
                    bubbles: true, cancelable: true, composed: true, dataTransfer: goi,
                  }));
                  bay('dragstart', o);
                  const kieu = [...goi.types];
                  bay('dragenter', khung);
                  bay('dragover', khung);
                  bay('drop', khung);
                  bay('dragend', o);
                  return {
                    ok: true,
                    kieu,
                    detail: `keo o luoi ${chu_ky || ten} vao khung; goi mang: ${kieu.join('|') || 'rong'}`,
                  };
                }
                """,
                {"ten": ten, "chu_ky": ky},
            )
        except Exception as exc:
            return False, f"khong keo duoc o luoi: {humanize_flow_error(str(exc))}"
        if not isinstance(result, dict) or not result.get("ok"):
            return False, str((result or {}).get("detail") or "keo o luoi that bai")
        await asyncio.sleep(2.5)
        return True, str(result.get("detail") or "keo o luoi vao khung")

    #: Số chặng con trỏ đi từ ô ảnh sang khung.  CDK chỉ tính là "đang kéo"
    #: sau khi con trỏ rời điểm nhấn quá ngưỡng, nên nhảy một phát tới đích là
    #: nó bỏ qua cả lượt.

    FLOW_KEO_CHUOT_BUOC = 12

    _JS_DIEM_KEO = """
        ({ ten, chu_ky }) => {
          const hien = (el, minW, minH) => {
            const r = el.getBoundingClientRect();
            if (r.width < minW || r.height < minH) return false;
            const s = window.getComputedStyle(el);
            return s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0';
          };
          const chu_ky_cua = (el) => `${el.tagName.toLowerCase()}|`
            + ((el.getAttribute('aria-label') || '').trim()
               || (el.getAttribute('title') || '').trim());
          const khop = chu_ky
            ? (el) => chu_ky_cua(el) === chu_ky
            : (el) => `${el.getAttribute('aria-label') || ''} ${el.getAttribute('title') || ''}`.includes(ten);
          const o = [...document.querySelectorAll('[aria-label], [title]')]
            .filter(khop)
            .filter((el) => hien(el, 40, 40))
            .sort((a, b) => {
              const ra = a.getBoundingClientRect();
              const rb = b.getBoundingClientRect();
              return rb.width * rb.height - ra.width * ra.height;
            })[0];
          if (!o) return { ok: false, detail: `khong thay o luoi mang ten ${chu_ky || ten}` };
          // Tâm **phần nhìn thấy**, không phải tâm thẻ.  Ô nhập lệnh đang mang
          // prompt dài nên hộp bao của nó cao hơn 4000 điểm ảnh; lấy tâm thẻ là
          // trỏ chuột ra ngoài màn hình, mà ngoài màn hình thì không thả được.
          const tam = (el) => {
            const r = el.getBoundingClientRect();
            const x0 = Math.max(r.left, 0), x1 = Math.min(r.right, window.innerWidth);
            const y0 = Math.max(r.top, 0), y1 = Math.min(r.bottom, window.innerHeight);
            if (x1 - x0 < 8 || y1 - y0 < 8) return null;
            return { x: (x0 + x1) / 2, y: (y0 + y1) / 2 };
          };
          const diem_o = tam(o);
          if (!diem_o) return { ok: false, detail: 'o luoi nam ngoai khung nhin' };
          const khung = [...document.querySelectorAll('textarea, [contenteditable="true"], [role="textbox"]')]
            .filter((el) => hien(el, 60, 16))
            .filter((el) => tam(el))
            .sort((a, b) => b.getBoundingClientRect().bottom - a.getBoundingClientRect().bottom)[0];
          if (!khung) return { ok: false, detail: 'khong thay o nhap lenh cua Tac nhan trong khung nhin' };
          return { ok: true, o: diem_o, khung: tam(khung) };
        }
    """

    async def _keo_chuot_o_luoi_vao_khung(
        self, page: Any, ten_tep: str = "", *, chu_ky: str = ""
    ) -> tuple[bool, str]:
        """Kéo ô ảnh vào khung Tác nhân bằng **chuột thật**, không bấm thêm cú nào.

        Kéo–thả HTML5 bắn xong thì gói vẫn rỗng — job ``90a17981`` ghi đúng chữ
        ``goi mang: rong``.  Gói rỗng nghĩa là Flow không hề cài ``dragstart``:
        lưới của nó là ``cdk-virtual-scroll-viewport``, tức Angular CDK, mà CDK
        kéo bằng **sự kiện con trỏ** chứ không đụng tới ``DataTransfer``.  Sự
        kiện tổng hợp kiểu ấy sẽ chẳng bao giờ mang được gì, nên đường này phải
        đi bằng chuột.

        Khác ``_select_flow_edit_target_image`` ở đúng một chỗ, mà chỗ ấy là tất
        cả: **không bấm thêm sau khi thả**.  Cú bấm ấy là thứ mở ảnh ra và làm
        panel Tác nhân biến mất, để lại dãy ``16->0`` của job ``879299d2``.
        """
        ten = str(ten_tep or "").strip()
        ky = str(chu_ky or "").strip()
        if not ten and not ky:
            return False, "khong co ten tep de tim tren luoi"
        try:
            diem = await page.evaluate(self._JS_DIEM_KEO, {"ten": ten, "chu_ky": ky})
        except Exception as exc:
            return False, f"khong do duoc toa do de keo: {humanize_flow_error(str(exc))}"
        if not isinstance(diem, dict) or not diem.get("ok"):
            return False, str((diem or {}).get("detail") or "khong do duoc toa do de keo")
        try:
            x0 = float(diem["o"]["x"])
            y0 = float(diem["o"]["y"])
            x1 = float(diem["khung"]["x"])
            y1 = float(diem["khung"]["y"])
        except (KeyError, TypeError, ValueError):
            return False, "toa do keo doc khong ra so"
        buoc = max(2, int(self.FLOW_KEO_CHUOT_BUOC))
        try:
            mouse = page.mouse
            await mouse.move(x0, y0)
            await mouse.down()
            # Nhích một cái cho vượt ngưỡng rồi mới đi đường dài.
            await mouse.move(x0 + 8, y0 + 8)
            await asyncio.sleep(0.12)
            for i in range(1, buoc + 1):
                await mouse.move(
                    x0 + (x1 - x0) * i / buoc,
                    y0 + (y1 - y0) * i / buoc,
                )
                await asyncio.sleep(0.05)
            # Dừng một nhịp trên đích: Flow bật lớp "thả vào đây" theo
            # ``dragover``, thả ngay lúc lớp chưa kịp hiện là thả vào chỗ trống.
            await asyncio.sleep(0.4)
            await mouse.up()
        except Exception as exc:
            return False, f"keo chuot hong: {humanize_flow_error(str(exc))}"
        await asyncio.sleep(2.5)
        return True, "keo chuot o luoi %s vao khung (%d,%d)->(%d,%d)" % (
            ky or ten, int(x0), int(y0), int(x1), int(y1),
        )

    async def _tha_anh_vao_khung_tac_nhan(self, page: Any, source: Path) -> tuple[bool, str]:
        """Thả file thẳng vào khung Tác nhân bằng ``DataTransfer``.

        Trang Tác nhân của Flow **không có** ``input[type=file]`` nào —
        ``file_inputs=0`` trong mọi log ngày 09/09.  Không có input thì
        ``set_input_files`` vô nghĩa, mà hộp chọn file mở ra từ menu cũng
        không nạp được gì: ảnh không vào khung, cũng không vào thư viện
        project.  Con đường còn lại là đúng con đường người dùng hay dùng —
        kéo–thả ảnh vào ô nhập lệnh — nên ta dựng ``File`` ngay trong trang
        rồi bắn bộ sự kiện kéo–thả vào ô ấy.

        Bắn **một** lượt trên **một** đích rồi dọn bằng ``dragleave`` và
        ``dragend``.  Bản đầu bắn lên năm lớp bọc: mỗi lớp sau lại
        ``dragenter`` **sau** cú ``drop`` của lớp trước, nên Flow hiểu là
        vẫn đang kéo và giữ nguyên lớp phủ "thả tệp vào đây" che kín trang —
        job ``8ab1f730`` đếm được ``6->0``, ``allMedia=0``.  Sự kiện đã
        ``bubbles`` và ``composed`` thì tự đi lên hết mọi lớp, kể cả qua
        shadow DOM, nên không cần leo tay.
        """
        try:
            raw = source.read_bytes()
        except OSError as exc:
            return False, f"khong doc duoc file nguon: {exc}"
        mime = mimetypes.guess_type(source.name)[0] or "image/png"
        payload = base64.b64encode(raw).decode("ascii")
        # Nghe **mọi** request quanh cú thả.  ``UIInterceptor`` chỉ nghe
        # ``aisandbox-pa.googleapis.com`` nên câu "khong co loi goi nao"
        # trong log không chứng minh được gì.  Muốn biết Flow có nhận cú thả
        # hay không thì phải xem nó có bắn request nào ra không.
        duong_dan: list[str] = []

        def _ghi_request(request: Any) -> None:
            try:
                if str(getattr(request, "method", "")).upper() in {"POST", "PUT", "PATCH"}:
                    duong_dan.append(str(getattr(request, "url", ""))[:120])
            except Exception:
                pass

        try:
            page.on("request", _ghi_request)
        except Exception:
            pass

        try:
            result = await page.evaluate(
                """
                ({ b64, name, mime }) => {
                  const bin = atob(b64);
                  const buf = new Uint8Array(bin.length);
                  for (let i = 0; i < bin.length; i += 1) buf[i] = bin.charCodeAt(i);
                  const file = new File([buf], name, { type: mime });
                  const deepElements = [];
                  const collect = (root) => {
                    if (!root || !root.querySelectorAll) return;
                    for (const el of root.querySelectorAll('*')) {
                      deepElements.push(el);
                      if (el.shadowRoot) collect(el.shadowRoot);
                    }
                  };
                  collect(document);
                  const visible = (el) => {
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 40 || rect.height < 12) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden'
                      && style.display !== 'none'
                      && style.opacity !== '0'
                      && rect.bottom > 0
                      && rect.top < window.innerHeight;
                  };
                  const labelFor = (el) => [
                    el.getAttribute('aria-label') || '',
                    el.getAttribute('placeholder') || '',
                    el.getAttribute('data-testid') || '',
                    (el.textContent || '').slice(0, 40),
                  ].join(' ').replace(/\s+/g, ' ').trim();
                  const boxes = deepElements
                    .filter((el) => el.matches('textarea, [contenteditable="true"], [role="textbox"]'))
                    .filter(visible)
                    .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
                    .sort((a, b) => b.rect.bottom - a.rect.bottom);
                  const box = boxes.find((item) => /muốn|want|create|prompt/i.test(item.label)) || boxes[0];
                  if (!box) return { ok: false, detail: 'khong thay o nhap lenh cua Tac nhan' };
                  const goi = () => { const d = new DataTransfer(); d.items.add(file); return d; };
                  const su_kien = (loai) => new DragEvent(loai, {
                    bubbles: true, cancelable: true, composed: true, dataTransfer: goi(),
                  });
                  for (const loai of ['dragenter', 'dragover', 'drop']) {
                    box.el.dispatchEvent(su_kien(loai));
                  }
                  // Dọn cho bằng hết: thiếu hai cú này thì Flow tưởng còn
                  // đang kéo và để nguyên lớp phủ che kín trang.
                  for (const loai of ['dragleave', 'dragend']) {
                    box.el.dispatchEvent(su_kien(loai));
                  }
                  const ten = box.label || box.el.tagName;
                  return { ok: true, detail: `tha vao o nhap lenh (${ten.slice(0, 60)}) tai ${location.pathname}` };
                }
                """,
                {"b64": payload, "name": source.name, "mime": mime},
            )
        except Exception as exc:
            return False, f"khong tha duoc file vao khung: {humanize_flow_error(str(exc))}"
        finally:
            await asyncio.sleep(4.0)
            try:
                page.remove_listener("request", _ghi_request)
            except Exception:
                pass
        if not isinstance(result, dict) or not result.get("ok"):
            return False, str((result or {}).get("detail") or "tha file vao khung that bai")
        goi = ", ".join(duong_dan[-6:]) if duong_dan else "khong co request nao"
        return True, "%s; sau khi tha: %d request (%s)" % (
            str(result.get("detail") or "tha file vao khung Tac nhan"),
            len(duong_dan),
            goi,
        )

    async def _bam_nut_gan_nguyen_lieu(self, page: Any, source: Path) -> tuple[bool, str]:
        """Bấm đúng nút gắn nguyên liệu của ô lệnh rồi nạp file vào hộp chọn.

        Bảng chấm điểm bên dưới đo theo **tâm** ô nhập lệnh.  Ô ấy đang mang
        prompt dài nên hộp bao của nó cao hơn 4000 điểm ảnh, tâm rơi hẳn ra
        ngoài màn hình, và nút đúng — ``Add ingredients to the prompt box``,
        nằm sát đáy ô — bị chấm âm.  Nút thắng lại là ``Add media`` trên thanh
        project, thứ đẩy ảnh vào **thư viện** chứ không thành nguyên liệu: job
        ``90a17981`` tải lên xong khung vẫn ``6->6``, ``chips=0``.

        Nút này gọi được thẳng bằng tên thì đừng đi vòng qua điểm số.
        """
        da_thu: list[str] = []
        for selector in self.FLOW_AGENT_INGREDIENT_ONLY:
            nut = None
            for mau in (f"{selector}:visible", selector):
                try:
                    ung_vien = page.locator(mau).first
                    if await ung_vien.count() > 0:
                        nut = ung_vien
                        break
                except Exception:
                    continue
            if nut is None:
                continue
            # Bấm một lần: hộp chọn file có thể bật ra ngay…
            try:
                async with page.expect_file_chooser(timeout=4000) as hop:
                    await nut.click(force=True, timeout=2500)
                chooser = await hop.value
                await chooser.set_files(str(source))
                await asyncio.sleep(2.0)
                return True, f"hop chon file tu nut nguyen lieu ({selector})"
            except Exception:
                pass
            # …hoặc bung ra một menu, và mục "Upload" trong đó mới mở hộp chọn.
            # Menu của Angular Material dựng xong mới gắn vào lớp phủ; soi ngay
            # lúc ``expect_file_chooser`` vừa hết giờ thì lớp phủ còn trống.
            await asyncio.sleep(0.8)
            ok, detail = await self._attach_flow_agent_source_menu_item(
                page, source, so_lan_mo=1, mau_nut=(selector,)
            )
            if ok:
                return True, f"{detail} qua nut nguyen lieu ({selector})"
            da_thu.append(f"{selector}: {detail}")
            # …hoặc chẳng có hộp chọn nào cả, mà là một **bảng chọn** liệt kê
            # media của project.  Bảng ấy có nút tải riêng: nạp thẳng vào đó
            # rồi mới đi tìm ô ảnh, khỏi trông chờ cú tải lên thư viện.
            tai_ok, tai_detail = await self._tai_anh_trong_bang_chon(page, source)
            da_thu.append(f"{selector}: {tai_detail}")
            ok, chon_detail = await self._chon_anh_trong_menu(page, source.name)
            if ok:
                return True, f"{chon_detail} qua nut nguyen lieu ({selector})"
            da_thu.append(f"{selector}: {chon_detail}")
        if not da_thu:
            return False, "khong thay nut gan nguyen lieu cua o lenh tren trang"
        return False, "nut gan nguyen lieu bam roi ma khong an — %s" % "; ".join(da_thu)

    async def _attach_flow_agent_source_file(
        self,
        page: Any,
        image_path: str,
        before_snapshot: Dict[str, Any] | None = None,
    ) -> tuple[bool, str]:
        source = Path(str(image_path or "")).expanduser()
        if not source.is_file():
            return False, f"source file missing: {source}"
        attempts: List[str] = []
        # Any file dialog that opens from here on receives this file (or gets closed).
        self._flow_agent_chooser_file = str(source)
        self._flow_agent_chooser_expecting = False
        self._install_flow_page_file_chooser_guard(page)
        top_banner_detail = await self._dismiss_flow_top_banner(page)
        if top_banner_detail:
            attempts.append(top_banner_detail)

        async def _set_any_file_input() -> tuple[bool, str]:
            try:
                scopes: List[Any] = list(getattr(page, "frames", []) or [])
            except Exception:
                scopes = []
            if not scopes:
                scopes = [page]
            for scope in scopes:
                for selector in ('input[type="file"][accept*="image"]', 'input[type="file"]'):
                    try:
                        locator = scope.locator(selector)
                        count = await locator.count()
                    except Exception:
                        count = 0
                    for index in range(count):
                        try:
                            await locator.nth(index).set_input_files(str(source))
                            await asyncio.sleep(2.0)
                            attempts.append(await self._flow_agent_debug_step(page, "after-set-input"))
                            return True, f"{selector} #{index + 1}"
                        except Exception:
                            continue
            return False, "no usable file input"

        async def _click_for_file_chooser(x: Any, y: Any, expected_label: str = "") -> bool:
            expected = str(expected_label or "").strip()
            if expected:
                probe_token = re.escape(expected[:14])
                actual = await self._flow_agent_label_at_point(page, x, y)
                if not re.search(probe_token, actual or "", flags=re.IGNORECASE):
                    attempts.append(f"{expected[:40]} moved (found '{actual[:40]}')")
                    return False
            handled_before = int(getattr(self, "_flow_agent_chooser_handled", 0) or 0)
            self._flow_agent_chooser_expecting = True
            try:
                async with page.expect_file_chooser(timeout=3500) as chooser_info:
                    await page.mouse.click(float(x), float(y))
                chooser = await chooser_info.value
                self._flow_agent_chooser_expecting = False
                await chooser.set_files(str(source))
                await asyncio.sleep(2.0)
                attempts.append(await self._flow_agent_debug_step(page, f"chooser-{re.sub(r'[^a-z0-9]+', '-', expected[:16].lower())}"))
                return True
            except Exception:
                self._flow_agent_chooser_expecting = False
                # A slow UI can open the dialog after the wait above gave up; the page guard
                # feeds it the source file, so give it a moment before declaring "no chooser".
                await asyncio.sleep(2.0)
                if int(getattr(self, "_flow_agent_chooser_handled", 0) or 0) > handled_before:
                    attempts.append(f"late chooser handled by guard after {expected[:40]}")
                    return True
                attempts.append(await self._flow_agent_debug_step(page, f"nochooser-{re.sub(r'[^a-z0-9]+', '-', expected[:16].lower())}"))
                return False
            finally:
                self._flow_agent_chooser_expecting = False

        async def _finish(detail: str, picker_timeout_s: float = 30.0) -> tuple[bool, str]:
            step_detail = await self._flow_agent_debug_step(page, "after-upload")
            picker_detail = await self._confirm_flow_agent_ingredient_picker(page, source.name, timeout_s=picker_timeout_s)
            tried = f" (earlier clicks: {' | '.join(item for item in attempts[:8] if item)})" if attempts else ""
            return True, f"{detail}; {step_detail} {picker_detail}{tried}"[:1600]

        # The composer toolbar re-renders for a moment after a long prompt is inserted,
        # so poll for the add control instead of trusting a single snapshot.
        lookup_deadline = asyncio.get_running_loop().time() + float(getattr(self, "_flow_agent_add_control_lookup_s", 10.0) or 0.0)
        result: Dict[str, Any] = {}
        while True:
            try:
                result = await page.evaluate(self.FLOW_AGENT_ADD_CONTROL_JS)
            except Exception as exc:
                result = {"ok": False, "detail": humanize_flow_error(str(exc))[:120]}
            result = result if isinstance(result, dict) else {}
            if result.get("candidates") or asyncio.get_running_loop().time() >= lookup_deadline:
                break
            await asyncio.sleep(0.75)
        candidates = [item for item in (result.get("candidates") or []) if isinstance(item, dict)]
        fallback_candidates = [item for item in (result.get("fallback_candidates") or []) if isinstance(item, dict)]
        composer = result.get("composer") if isinstance(result.get("composer"), dict) else None
        if not candidates or all(item.get("offscreen") for item in candidates):
            # Flow's top notice banner pushes the composer toolbar below the fold: close it and look again.
            top_banner_detail = await self._dismiss_flow_top_banner(page)
            if top_banner_detail:
                attempts.append(top_banner_detail)
                await asyncio.sleep(0.6)
            try:
                retry = await page.evaluate(self.FLOW_AGENT_ADD_CONTROL_JS)
            except Exception:
                retry = {}
            retry = retry if isinstance(retry, dict) else {}
            retry_candidates = [item for item in (retry.get("candidates") or []) if isinstance(item, dict)]
            if retry_candidates:
                result = retry
                candidates = retry_candidates
                fallback_candidates = [item for item in (retry.get("fallback_candidates") or []) if isinstance(item, dict)]
                composer = retry.get("composer") if isinstance(retry.get("composer"), dict) else composer

        async def _try_add_controls(items: List[Dict[str, Any]], limit: int, picker_timeout_s: float) -> tuple[bool, str] | None:
            for candidate in items[:limit]:
                label = str(candidate.get("label") or "add control")[:80]
                if candidate.get("offscreen"):
                    attempts.append(f"{label[:40]}: below the fold")
                    continue
                if await _click_for_file_chooser(candidate.get("x"), candidate.get("y"), label):
                    return await _finish(f"file chooser via {label}", picker_timeout_s)
                attempts.append(f"{label}: no chooser")
                await asyncio.sleep(0.6)
                try:
                    menu = await page.evaluate(self.FLOW_AGENT_UPLOAD_MENU_JS)
                except Exception:
                    menu = {}
                menu_items = [item for item in ((menu or {}).get("items") or []) if isinstance(item, dict)] if isinstance(menu, dict) else []
                for item in menu_items[:3]:
                    item_label = str(item.get("label") or "menu item")[:80]
                    if await _click_for_file_chooser(item.get("x"), item.get("y"), item_label):
                        return await _finish(f"file chooser via {label} > {item_label}", picker_timeout_s)
                    attempts.append(f"menu {item_label}: no chooser")
                input_ok, input_detail = await _set_any_file_input()
                if input_ok:
                    return await _finish(f"{input_detail} after {label}", picker_timeout_s)
                try:
                    await page.keyboard.press("Escape")
                    await asyncio.sleep(0.3)
                except Exception:
                    pass
            return None

        outcome = await _try_add_controls(candidates, 3, 30.0)
        if outcome is not None:
            return outcome
        # The page-header "Add media" menu (project library upload) is used only when the composer offers no control.
        outcome = await _try_add_controls(fallback_candidates, 2, 10.0)
        if outcome is not None:
            return outcome

        input_ok, input_detail = await _set_any_file_input()
        if input_ok:
            return await _finish(input_detail)

        drop_ok, drop_detail = await self._drop_file_on_flow_agent_composer(page, source, composer)
        if drop_ok:
            verified, verify_detail = await self._wait_for_flow_agent_source_attachment(
                page,
                before_snapshot or {},
                timeout_s=8.0,
                source_file_name=source.name,
            )
            if verified:
                return True, f"{drop_detail}; {verify_detail}"[:400]
            attempts.append(f"{drop_detail}: no chip after drop")
            drop_detail = ""

        shot_detail = await self._capture_flow_agent_debug_screenshot(page, "attach-fail")
        summary = str(result.get("detail") or "no agent add/upload control")
        parts = [summary, *attempts[:5], input_detail, drop_detail, shot_detail]
        return False, "; ".join(part for part in parts if part)[:600]

    async def _capture_flow_agent_debug_screenshot(self, page: Any, tag: str) -> str:
        try:
            ensure_app_dirs()
            stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
            path = DATA_DIR / f"agent-ui-{tag}-{stamp}.png"
            await page.screenshot(path=str(path))
            return f"screenshot={path.name}"
        except Exception as exc:
            return f"screenshot failed: {humanize_flow_error(str(exc))[:60]}"

    async def _select_flow_edit_target_image(
        self,
        page: Any,
        reference_media_name: str,
        *,
        workflow_id: str = "",
        allow_visible_fallback: bool = False,
        require_agent_panel: bool = False,
    ) -> tuple[bool, str]:
        media_token = str(reference_media_name or "").strip()
        workflow_token = str(workflow_id or "").strip()
        try:
            result = await page.evaluate(
                """
                ({ mediaToken, workflowId, allowVisibleFallback, requireAgentPanel }) => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width < 80 || rect.height < 80) return false;
                    const style = window.getComputedStyle(el);
                    return style.visibility !== 'hidden' && style.display !== 'none' && style.opacity !== '0';
                  };
                  const draggable = (el) => (
                    el.closest('[aria-roledescription*="draggable" i], [draggable="true"], [role="button"], [data-index], [data-item-index]')
                    || el.closest('a')
                    || el
                  );
                  const labelFor = (el) => [
                    el?.textContent || '',
                    el?.getAttribute?.('placeholder') || '',
                    el?.getAttribute?.('aria-label') || '',
                    el?.getAttribute?.('title') || '',
                    el?.getAttribute?.('data-testid') || '',
                  ].join(' ').replace(/\\s+/g, ' ').trim();
                  const clippedRect = (rect) => ({
                    left: Math.max(0, rect.left),
                    top: Math.max(0, rect.top),
                    right: Math.min(window.innerWidth, rect.right),
                    bottom: Math.min(window.innerHeight, rect.bottom),
                    get width() { return Math.max(0, this.right - this.left); },
                    get height() { return Math.max(0, this.bottom - this.top); },
                  });
                  const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
                  const rightPanelish = (rect) => rect.left >= window.innerWidth * 0.42
                    || (rect.right >= window.innerWidth * 0.82 && rect.width <= window.innerWidth * 0.62);
                  const agentPanel = () => {
                    const panels = [...document.querySelectorAll('aside, dialog, section, div[role="dialog"], div')]
                      .filter((candidate) => {
                        const rect = candidate.getBoundingClientRect();
                        const style = window.getComputedStyle(candidate);
                        if (rect.width < 260 || rect.height < 180) return false;
                        if (!rightPanelish(rect)) return false;
                        if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') return false;
                        return rect.bottom > window.innerHeight * 0.45 && rect.top < window.innerHeight;
                      })
                      .map((candidate) => {
                        const rect = candidate.getBoundingClientRect();
                        const text = labelFor(candidate);
                        const hasTextbox = Boolean(candidate.querySelector('textarea, input[type="text"], [contenteditable="true"], [role="textbox"]'));
                        const agentish = /Flow\\s+Agent|Tác\\s*nhân|Tac\\s*nhan|Bạn\\s*muốn|Ban\\s*muon|What\\s+do\\s+you|Phiên\\s+không\\s+có\\s+tiêu\\s+đề|Phien\\s+khong\\s+co\\s+tieu\\s+de/i.test(text);
                        const score = (hasTextbox ? 900 : 0) + (agentish ? 700 : 0) + rect.right / 10 + rect.height / 20;
                        return { el: candidate, rect, score };
                      })
                      .filter((item) => item.score >= 900)
                      .sort((a, b) => b.score - a.score);
                    return panels[0] || null;
                  };
                  const agentComposerDropTarget = () => {
                    const panelItem = agentPanel();
                    const panel = panelItem?.el || document;
                    const panelRect = panelItem?.rect || { left: window.innerWidth * 0.45, right: window.innerWidth, top: 0, bottom: window.innerHeight, width: window.innerWidth * 0.55, height: window.innerHeight };
                    const controls = [...panel.querySelectorAll('button, [role="button"], label, [aria-label], [title], [data-testid]')]
                      .map((el) => {
                        const rect = el.getBoundingClientRect();
                        const style = window.getComputedStyle(el);
                        const label = labelFor(el);
                        const visibleControl = rect.width >= 18 && rect.height >= 18
                          && rect.bottom > window.innerHeight * 0.55
                          && rect.top < window.innerHeight
                          && rect.left >= panelRect.left - 12
                          && rect.right <= panelRect.right + 12
                          && style.display !== 'none'
                          && style.visibility !== 'hidden'
                          && style.opacity !== '0';
                        const addish = /\\+|add_2|add|attach|upload|image|media|file|ảnh|anh|hình|hinh|thêm|them/i.test(label);
                        const leftish = rect.left <= panelRect.left + panelRect.width * 0.32;
                        const nearBottom = rect.bottom >= panelRect.bottom - Math.max(180, panelRect.height * 0.28);
                        const score = (visibleControl ? 1000 : -9999) + (addish ? 1000 : 0) + (leftish ? 350 : 0) + (nearBottom ? 350 : 0) - Math.abs(rect.bottom - panelRect.bottom) / 4;
                        return { el, rect, label, score };
                      })
                      .filter((item) => item.score > 900)
                      .sort((a, b) => b.score - a.score);
                    const plus = controls[0];
                    if (plus) {
                      const x = clamp(plus.rect.right + 44, panelRect.left + 42, panelRect.right - 72);
                      const y = clamp(plus.rect.top - 22, Math.max(24, panelRect.top + 36), Math.min(window.innerHeight - 30, panelRect.bottom - 42));
                      return { x, y, detail: `chat composer plus ${Math.round(plus.rect.left)},${Math.round(plus.rect.top)}` };
                    }

                    const editors = [...panel.querySelectorAll('[contenteditable="true"], div[role="textbox"], textarea')]
                      .filter((candidate) => {
                        const rect = candidate.getBoundingClientRect();
                        const clipped = clippedRect(rect);
                        const style = window.getComputedStyle(candidate);
                        return clipped.width > 120
                          && clipped.height > 12
                          && clipped.bottom > window.innerHeight * 0.45
                          && clipped.right > panelRect.left
                          && clipped.left < panelRect.right
                          && style.display !== 'none'
                          && style.visibility !== 'hidden';
                      })
                      .map((candidate) => {
                        const rect = candidate.getBoundingClientRect();
                        const clipped = clippedRect(rect);
                        const label = labelFor(candidate);
                        const agentish = /Bạn\\s*muốn\\s*tạo\\s*gì|Ban\\s*muon\\s*tao\\s*gi|What\\s+do\\s+you|prompt|create/i.test(label);
                        const score = (agentish ? 800 : 0) + clipped.bottom / 10 + clipped.height / 30;
                        return { candidate, rect, clipped, label, score };
                      })
                      .sort((a, b) => b.score - a.score);
                    const editor = editors[0];
                    if (!editor) return null;
                    const x = clamp(editor.clipped.left + Math.max(48, editor.clipped.width * 0.16), panelRect.left + 32, panelRect.right - 72);
                    const y = clamp(editor.clipped.bottom - Math.max(28, Math.min(56, editor.clipped.height * 0.18)), editor.clipped.top + 18, window.innerHeight - 30);
                    return { x, y, detail: `chat composer textbox ${Math.round(editor.rect.left)},${Math.round(editor.rect.top)}` };
                  };
                  const rectInfo = (el) => {
                    const target = draggable(el);
                    target.scrollIntoView({block: 'center', inline: 'center'});
                    const sourceRect = target.getBoundingClientRect();
                    if (requireAgentPanel) {
                      const drop = agentComposerDropTarget();
                      if (!drop) return {ok: false, detail: 'no visible agent chat composer drop target'};
                      return {
                        ok: true,
                        sourceX: sourceRect.left + sourceRect.width / 2,
                        sourceY: sourceRect.top + sourceRect.height / 2,
                        targetX: drop.x,
                        targetY: drop.y,
                        detail: `drag ${target.tagName.toLowerCase()} ${Math.round(sourceRect.left)},${Math.round(sourceRect.top)} -> agent chat ${drop.detail}`,
                      };
                    }
                    const editors = [...document.querySelectorAll('[contenteditable="true"], div[role="textbox"], textarea')]
                      .filter((candidate) => {
                        const rect = candidate.getBoundingClientRect();
                        const style = window.getComputedStyle(candidate);
                        return rect.width > 120
                          && rect.height > 12
                          && rect.bottom > window.innerHeight * 0.45
                          && rect.top < window.innerHeight - 12
                          && rect.bottom <= window.innerHeight + 20
                          && rect.right > 0
                          && rect.left < window.innerWidth
                          && style.display !== 'none'
                          && style.visibility !== 'hidden';
                      })
                      .map((candidate) => {
                        const rect = candidate.getBoundingClientRect();
                        const label = [
                          candidate.textContent || '',
                          candidate.getAttribute('placeholder') || '',
                          candidate.getAttribute('aria-label') || '',
                          candidate.getAttribute('title') || '',
                        ].join(' ');
                        const inRightAgentPanel = rect.left >= window.innerWidth * 0.45 || (rect.right >= window.innerWidth * 0.9 && rect.width <= window.innerWidth * 0.55);
                        if (requireAgentPanel && !inRightAgentPanel) return null;
                        const agentish = /Bạn\\s*muốn\\s*tạo\\s*gì|Ban\\s*muon\\s*tao\\s*gi|What\\s+do\\s+you|prompt|create/i.test(label);
                        const score = (inRightAgentPanel ? 2000 : 0) + (agentish ? 800 : 0) + rect.bottom / 10;
                        return { candidate, rect, score };
                      })
                      .filter(Boolean)
                      .sort((a, b) => b.score - a.score)
                      .map((item) => item.candidate);
                    const editor = editors[0];
                    if (!editor) return {ok: false, detail: requireAgentPanel ? 'no visible agent panel drop editor' : 'no visible prompt editor'};
                    const editorRect = editor.getBoundingClientRect();
                    return {
                      ok: true,
                      sourceX: sourceRect.left + sourceRect.width / 2,
                      sourceY: sourceRect.top + sourceRect.height / 2,
                      targetX: editorRect.left + Math.min(editorRect.width - 20, Math.max(20, editorRect.width * 0.15)),
                      targetY: Math.min(window.innerHeight - 24, Math.max(24, editorRect.top + editorRect.height / 2)),
                      detail: `drag ${target.tagName.toLowerCase()} ${Math.round(sourceRect.left)},${Math.round(sourceRect.top)} -> ${requireAgentPanel ? 'agent panel' : 'prompt'} ${Math.round(editorRect.left)},${Math.round(editorRect.top)}`,
                    };
                  };

                  const tokens = [mediaToken, workflowId]
                    .map((value) => String(value || '').trim())
                    .filter(Boolean);
                  for (const token of tokens) {
                    const escaped = token.replace(/["\\\\]/g, '\\\\$&');
                    const exact = [
                      `[data-media-id*="${escaped}"]`,
                      `[data-media-name*="${escaped}"]`,
                      `[data-workflow-id*="${escaped}"]`,
                      `[data-testid*="${escaped}"]`,
                      `a[href*="${escaped}"] img`,
                      `a[href*="${escaped}"]`,
                      `img[alt*="${escaped}"]`,
                      `img[src*="${escaped}"]`,
                      `[aria-label*="${escaped}"]`,
                      `[title*="${escaped}"]`,
                    ];
                    for (const selector of exact) {
                      for (const el of document.querySelectorAll(selector)) {
                        if (visible(el)) return rectInfo(el);
                      }
                    }
                    for (const el of [...document.querySelectorAll('img, canvas, [role="img"], [style*="background-image"]')]) {
                      if (!visible(el)) continue;
                      const link = el.closest('a');
                      const nhan = el.closest('[aria-label], [title]');
                      const haystack = `${el.getAttribute('alt') || ''} ${el.getAttribute('src') || ''} ${link?.getAttribute('href') || ''} ${nhan?.getAttribute('aria-label') || ''} ${nhan?.getAttribute('title') || ''} ${el.outerHTML || ''}`;
                      if (haystack.includes(token)) return rectInfo(el);
                    }
                  }

                  const onEditPage = /\\/edit\\//.test(window.location.pathname || '');
                  if (allowVisibleFallback || onEditPage) {
                    const candidates = [...document.querySelectorAll('img, canvas, [role="img"], [style*="background-image"]')]
                      .filter(visible)
                      .map((el) => {
                        const rect = el.getBoundingClientRect();
                        const label = [
                          el.getAttribute('alt') || '',
                          el.getAttribute('aria-label') || '',
                          el.getAttribute('title') || '',
                          el.getAttribute('data-testid') || '',
                          el.getAttribute('src') || '',
                        ].join(' ');
                        const area = rect.width * rect.height;
                        const inPrompt = Boolean(el.closest('[contenteditable="true"], textarea, input, button, [role="button"], nav, header'));
                        const central = rect.bottom > 0
                          && rect.top < window.innerHeight * 0.88
                          && rect.left < window.innerWidth * 0.86
                          && rect.right > 0;
                        return { el, rect, area, label, inPrompt, central };
                      })
                      .filter((item) => !item.inPrompt && item.central && item.area >= 12000)
                      .sort((a, b) => b.area - a.area);
                    const fallback = candidates[0];
                    if (fallback) {
                      const selected = rectInfo(fallback.el);
                      if (selected.ok) {
                        selected.detail = `fallback visible edit image: ${selected.detail}`;
                      }
                      return selected;
                    }
                  }

                  return {ok: false, detail: tokens.length ? `media/workflow token not visible: ${tokens.join(', ')}` : 'missing media token'};
                }
                """,
                {
                    "mediaToken": media_token,
                    "workflowId": workflow_token,
                    "allowVisibleFallback": bool(allow_visible_fallback),
                    "requireAgentPanel": bool(require_agent_panel),
                },
            )
        except Exception as exc:
            return False, humanize_flow_error(str(exc))

        ok = bool((result or {}).get("ok")) if isinstance(result, dict) else False
        detail = str((result or {}).get("detail") or "").strip() if isinstance(result, dict) else ""
        if ok:
            try:
                source_x = float((result or {}).get("sourceX"))
                source_y = float((result or {}).get("sourceY"))
                target_x = float((result or {}).get("targetX"))
                target_y = float((result or {}).get("targetY"))
                await page.mouse.move(source_x, source_y)
                await asyncio.sleep(0.15)
                await page.mouse.down()
                steps = 12
                for step in range(1, steps + 1):
                    x = source_x + (target_x - source_x) * step / steps
                    y = source_y + (target_y - source_y) * step / steps
                    await page.mouse.move(x, y)
                    await asyncio.sleep(0.03)
                await page.mouse.up()
                await asyncio.sleep(1.0)
                await page.mouse.click(target_x, target_y)
                await asyncio.sleep(0.3)
            except Exception as exc:
                return False, humanize_flow_error(str(exc))
        return ok, detail

    def _flow_image_call_uses_selected_image(
        self,
        call: Any,
        reference_media_name: str,
        workflow_id: str,
        *,
        allow_any_image_input: bool = False,
    ) -> bool:
        payload = getattr(call, "req", None)
        if not isinstance(payload, dict):
            return False
        expected_media = str(reference_media_name or "").strip()
        expected_workflow = str(workflow_id or "").strip()
        payload_blob = json.dumps(payload, ensure_ascii=False)
        if expected_media and expected_media in payload_blob:
            return True
        if expected_workflow and expected_workflow in payload_blob:
            return True
        requests = payload.get("requests") if isinstance(payload.get("requests"), list) else []
        for item in requests:
            if not isinstance(item, dict):
                continue
            client_context = item.get("clientContext") if isinstance(item.get("clientContext"), dict) else {}
            if expected_workflow and str(client_context.get("workflowId") or "").strip() == expected_workflow:
                return True
            image_inputs = item.get("imageInputs") if isinstance(item.get("imageInputs"), list) else []
            if allow_any_image_input and image_inputs:
                return True
            for image_input in image_inputs:
                if not isinstance(image_input, dict):
                    continue
                values = {
                    str(image_input.get("name") or "").strip(),
                    str(image_input.get("mediaName") or "").strip(),
                    str(image_input.get("imageInputType") or "").strip(),
                    str(image_input.get("role") or "").strip(),
                }
                if expected_media and expected_media in values:
                    return True
        return False

    async def _find_workflow_id_for_media(self, client: Any, media_name: str) -> str:
        safe_media_name = str(media_name or "").strip()
        if not safe_media_name:
            return ""

        for attempt in range(3):
            project_data = await client._api.get_project_data()
            workflows = project_data.get("projectContents", {}).get("workflows", [])
            for workflow in workflows:
                workflow_id = str(workflow.get("name") or "").strip()
                if not workflow_id:
                    continue
                metadata = workflow.get("metadata", {}) or {}
                if str(metadata.get("primaryMediaId") or "").strip() == safe_media_name:
                    return workflow_id
                for media in workflow.get("medias", []) or []:
                    if str(media.get("name") or "").strip() == safe_media_name:
                        return workflow_id
            if attempt < 2:
                await asyncio.sleep(1)

        return ""

    async def _reload_flow_project_page(self, client: Any) -> None:
        page = await client._bm.page()
        project_url = str(
            getattr(client, "_project_url", "")
            or getattr(getattr(client, "_api", None), "_project_page_url", "")
            or self._project_url(getattr(client, "project_id", ""))
        ).strip()
        if not project_url:
            return

        ok, detail = await self._ensure_valid_flow_project_page(page, project_url)
        if not ok:
            raise FlowProjectNotFoundError(detail)
        try:
            await page.reload(wait_until="networkidle", timeout=60_000)
        except Exception:
            try:
                await page.reload(wait_until="domcontentloaded", timeout=60_000)
            except Exception:
                ok, detail = await self._ensure_valid_flow_project_page(page, project_url)
                if not ok:
                    raise FlowProjectNotFoundError(detail)

        try:
            ready = await page.wait_for_function(
                "() => !!window.grecaptcha?.enterprise?.execute",
                timeout=15_000,
            )
            await ready.dispose()
        except Exception:
            pass
        await asyncio.sleep(2.0)

    def _is_recaptcha_error(self, exc: Exception) -> bool:
        detail = str(exc or "").lower()
        return "recaptcha" in detail and "failed" in detail

    def _is_flow_api_argument_error(self, exc: Exception) -> bool:
        # Google answers a drifted batchGenerateImages payload with a bare
        # INVALID_ARGUMENT and no field detail.  The Flow UI keeps working when
        # this happens, so treat it as "use the browser path", not a dead end.
        detail = str(exc or "").lower()
        return "invalid_argument" in detail or ("http 400" in detail and "invalid argument" in detail)

    def _is_image_model_error(self, exc: Exception) -> bool:
        detail = str(exc or "").lower()
        model_markers = ("model", "imagemodelname", "modelnametype")
        problem_markers = ("invalid", "unknown", "unsupported", "not supported", "unrecognized", "not found")
        return any(marker in detail for marker in model_markers) and any(marker in detail for marker in problem_markers)

    def _parse_images_from_flow_payload(
        self,
        payload: Any,
        *,
        prompt: str,
        fallback_workflow_id: str = "",
    ) -> List[Any]:
        from flow._api import GeneratedImage

        response = payload if isinstance(payload, dict) else {}
        images: List[Any] = []

        for media_item in response.get("media", []) or []:
            if not isinstance(media_item, dict):
                continue
            image = GeneratedImage.__new__(GeneratedImage)
            image._raw = media_item
            image.media_name = str(media_item.get("name") or media_item.get("mediaName") or "").strip()
            image.project_id = str(media_item.get("projectId") or "").strip()
            image.workflow_id = str(media_item.get("workflowId") or fallback_workflow_id or "").strip()
            generated = ((media_item.get("image") or {}).get("generatedImage") or {})
            image.fife_url = str(
                generated.get("fifeUrl")
                or generated.get("url")
                or media_item.get("fifeUrl")
                or ""
            ).strip()
            image.seed = generated.get("seed", 0)
            image.model = str(generated.get("modelNameType") or generated.get("model") or "").strip()
            image.prompt = str(generated.get("prompt") or prompt or "").strip()
            image.dimensions = media_item.get("dimensions", {}) or {}
            image.file_path = None
            images.append(image)

        if images:
            return images

        for item in response.get("generatedImages", []) or []:
            if not isinstance(item, dict):
                continue
            image = GeneratedImage.__new__(GeneratedImage)
            image._raw = item
            image.media_name = str(item.get("mediaName") or item.get("name") or "").strip()
            image.project_id = ""
            image.workflow_id = fallback_workflow_id
            image.fife_url = str(item.get("fifeUrl") or item.get("url") or "").strip()
            image.seed = int(item.get("seed", 0) or 0)
            image.model = str(item.get("modelNameType") or item.get("model") or "").strip()
            image.prompt = str(item.get("prompt") or prompt or "").strip()
            image.dimensions = item.get("dimensions", {}) or {}
            image.file_path = None
            images.append(image)
        return images

    async def _wait_for_video_with_progress(
        self,
        client: Any,
        job_id: str,
        video_job: Any,
        label: str,
        *,
        poll_s: float,
        timeout_s: int,
    ) -> Any:
        await self.store.patch_job(job_id, status="polling")
        started_at = time.monotonic()
        last_state = ""
        last_logged_at = -999.0

        while True:
            elapsed = time.monotonic() - started_at
            if elapsed > timeout_s:
                raise RuntimeError(f"{label} đã hết thời gian chờ sau {timeout_s} giây.")

            status = await client.poll_video(video_job.media_name)
            remote_state = getattr(status, "status", "")
            state_message = self._describe_remote_status(remote_state)
            failure_detail = humanize_flow_error(self._video_status_failure_detail(status))

            should_log = remote_state != last_state or (elapsed - last_logged_at) >= max(15.0, poll_s * 3)
            if should_log:
                if getattr(status, "complete", False):
                    await self._set_job_progress(
                        job_id,
                        "saving_artifacts",
                        f"{label}: Flow đã hoàn tất render sau {int(elapsed)} giây. Em đang chuẩn bị lưu artifact.",
                        remote_status=remote_state,
                    )
                    await self.store.append_log(job_id, f"{label}: đã hoàn tất sau {int(elapsed)} giây.")
                elif getattr(status, "failed", False):
                    log_message = failure_detail or f"Flow báo thất bại với trạng thái {state_message}."
                    await self._set_job_progress(
                        job_id,
                        "polling",
                        f"{label}: {log_message}",
                        remote_status=remote_state,
                    )
                    await self.store.append_log(job_id, f"{label}: {log_message}")
                else:
                    await self._set_job_progress(
                        job_id,
                        "polling",
                        f"{label}: {state_message} ({int(elapsed)} giây).",
                        remote_status=remote_state,
                    )
                    await self.store.append_log(job_id, f"{label}: {state_message} ({int(elapsed)} giây).")
                last_logged_at = elapsed
                last_state = remote_state

            if getattr(status, "complete", False):
                await self._set_job_progress(
                    job_id,
                    "saving_artifacts",
                    f"{label}: Flow đã hoàn tất render. Em đang chuẩn bị lưu artifact.",
                    remote_status=remote_state,
                )
                return status

            if getattr(status, "failed", False):
                raise RuntimeError(failure_detail or f"{label} thất bại với trạng thái {state_message}.")

            await asyncio.sleep(poll_s)

    def _describe_remote_status(self, status: str) -> str:
        mapping = {
            "MEDIA_GENERATION_STATUS_PENDING": "đang chờ xử lý",
            "MEDIA_GENERATION_STATUS_RUNNING": "đang tạo nội dung",
            "MEDIA_GENERATION_STATUS_IN_PROGRESS": "đang xử lý",
            "MEDIA_GENERATION_STATUS_COMPLETE": "đã hoàn tất",
            "MEDIA_GENERATION_STATUS_SUCCESS": "đã hoàn tất",
            "MEDIA_GENERATION_STATUS_SUCCESSFUL": "đã hoàn tất",
            "MEDIA_GENERATION_STATUS_FAILED": "đã thất bại",
            "MEDIA_GENERATION_STATUS_REJECTED": "bị từ chối",
        }
        return mapping.get(status, status.replace("_", " ").lower() if status else "đang xử lý")
